def test_finalizer_canonical_authority_key_order_is_cross_process_deterministic() -> None:
    script = "\n".join(
        (
            "import hashlib, json",
            (
                "from src.research_infra."
                "v4_timewarp_simulated_live_research_loop import "
                "FINALIZER_CANONICAL_AUTHORITY_KEYS"
            ),
            "payload = {'conflicts': [{'key': key} for key in "
            "FINALIZER_CANONICAL_AUTHORITY_KEYS[:32]]}",
            "raw = json.dumps(payload, sort_keys=True, separators=(',', ':')).encode()",
            "print(json.dumps({'keys': FINALIZER_CANONICAL_AUTHORITY_KEYS[:32], "
            "'payload_sha256': hashlib.sha256(raw).hexdigest()}))",
        )
    )
    results = []
    for seed in ("1", "8675309"):
        environment = dict(os.environ)
        environment["PYTHONHASHSEED"] = seed
        completed = subprocess.run(
            [sys.executable, "-c", script],
            cwd=Path(__file__).resolve().parents[1],
            env=environment,
            text=True,
            capture_output=True,
            check=True,
        )
        results.append(json.loads(completed.stdout))

    assert results[0] == results[1]
    assert tuple(results[0]["keys"]) == SEALED_FINALIZER_CONFLICT_KEY_PRECEDENCE
    source = Path(timewarp.__file__).read_text(encoding="utf-8")
    assert "for key in FINALIZER_CANONICAL_AUTHORITY_KEYS:" in source
    assert "finalizer_canonical_authority_keys = frozenset" not in source


def test_materializes_lossless_semantic_selected_order_preimage() -> None:
    campaign = CampaignConfig(
        name="campaign-1",
        phase="S0R0_development",
        profile="S0R0",
        days=("2026-01-02",),
        pending_expiry_minutes=240,
        use_repaired_pending_expiry=True,
        materialize_packet_sidecars=False,
        candidate_ledger_packet_max_bytes=64,
    )
    exact_order_row = {"simulated_order_id": "order-1"}
    ledgers = {"order": [exact_order_row]}
    execution_packet = {
        "schema_version": "execution_manager_v4_packet_v1",
        "large_lossless_payload": "x" * 1024,
    }
    broker_packet = {
        "schema_version": "broker_order_lifecycle_capture_v4_packet_v1",
        "large_lossless_payload": "y" * 1024,
    }

    produced = timewarp.materialize_semantic_selected_order_preimage(
        ledgers=ledgers,
        campaign=campaign,
        execution_identity_fields={
            "decision_window_id": "window-1",
            "canonical_replay_candidate_instance_key": "candidate-instance-1",
        },
        candidate_id="candidate-1",
        simulated_order_id="order-1",
        decision_time_utc="2026-01-02T08:00:00+00:00",
        trading_day="2026-01-02",
        selected_order_sequence=7,
        producer_order_stream_index=0,
        producer_order_row=exact_order_row,
        execution_manager_packet=execution_packet,
        broker_order_lifecycle_capture_v4_packet=broker_packet,
    )

    assert len(ledgers["semantic_order_preimage"]) == 1
    assert json.loads(produced["sidecar_payload_canonical_json"]) == {
        "execution_manager_packet": execution_packet,
        "broker_order_lifecycle_capture_v4_packet": broker_packet,
    }
    assert ledgers["order"][0] == {"simulated_order_id": "order-1"}
    assert produced["producer_order_stream_index"] == 0
    assert produced["producer_order_row_sha256"] == timewarp.stable_sha256(
        exact_order_row
    )
    assert produced["selected_order_attempt_primary"] is True
    assert produced["selected_order_sequence"] == 7
    assert produced["owner"]["profile"] == "S0R0"


@pytest.mark.parametrize(
    ("order_rows", "producer_order_stream_index", "producer_order_row"),
    (
        ([{"simulated_order_id": "other"}, {"simulated_order_id": "order-1"}], 0, 1),
        ([{"simulated_order_id": "order-1"}], 0, "detached_copy"),
    ),
)
def test_semantic_order_preimage_rejects_false_capture_identity(
    order_rows: list[dict[str, str]],
    producer_order_stream_index: int,
    producer_order_row: int | str,
) -> None:
    campaign = CampaignConfig(
        name="campaign-1",
        phase="S0R0_development",
        profile="S0R0",
        days=("2026-01-02",),
        pending_expiry_minutes=240,
        use_repaired_pending_expiry=True,
    )
    exact_order = (
        order_rows[producer_order_row]
        if isinstance(producer_order_row, int)
        else dict(order_rows[0])
    )

    with pytest.raises(
        ValueError,
        match="semantic_order_preimage_primary_order_identity_mismatch",
    ):
        timewarp.materialize_semantic_selected_order_preimage(
            ledgers={"order": order_rows},
            campaign=campaign,
            execution_identity_fields={
                "decision_window_id": "window-1",
                "canonical_replay_candidate_instance_key": "candidate-instance-1",
            },
            candidate_id="candidate-1",
            simulated_order_id="order-1",
            decision_time_utc="2026-01-02T08:00:00+00:00",
            trading_day="2026-01-02",
            selected_order_sequence=7,
            producer_order_stream_index=producer_order_stream_index,
            producer_order_row=exact_order,
            execution_manager_packet={"schema_version": "execution-manager-v1"},
            broker_order_lifecycle_capture_v4_packet={
                "schema_version": "broker-capture-v1"
            },
        )


def test_semantic_state_checkpoint_chains_across_gapped_campaign_days() -> None:
    account = AccountState()
    broker = SimulatedBroker(account)
    campaign = "campaign-1"
    profile = "S0R0"
    account.ensure_day("2026-01-02")
    post = timewarp.build_semantic_state_checkpoint(
        campaign=campaign,
        profile=profile,
        trading_day="2026-01-02",
        boundary="post_day",
        account=account,
        broker=broker,
        selected_order_sequence=3,
    )
    next_pre = timewarp.build_semantic_state_checkpoint(
        campaign=campaign,
        profile=profile,
        trading_day="2026-01-05",
        boundary="pre_day",
        account=account,
        broker=broker,
        selected_order_sequence=3,
    )

    assert post["state_root_sha256"] == next_pre["state_root_sha256"]
    assert post["state_projection"] == next_pre["state_projection"]
    assert tuple(post["account_preimage"]) == (
        "accepted_risk_orders_by_day",
        "accepted_risk_orders_by_day_decision_cluster_side",
        "accepted_risk_orders_by_day_decision_time",
        "accepted_risk_orders_by_day_session",
        "accepted_risk_pct_by_day",
        "accepted_risk_pct_by_day_decision_cluster_side",
        "accepted_risk_pct_by_day_decision_time",
        "accepted_risk_pct_by_day_session",
        "balance",
        "closed_trades",
        "daily_start_balance",
        "equity",
        "event_queue",
        "event_sequence",
        "max_drawdown_pct",
        "open_positions",
        "peak_equity",
        "pending_orders",
    )
    assert timewarp.stable_sha256(post["account_preimage"]) == post[
        "state_projection"
    ]["account_root_sha256"]


def test_load_jsonl_retries_transient_timeout(monkeypatch):
    class FlakyJsonl:
        suffix = ".jsonl"

        def __init__(self):
            self.calls = 0

        def exists(self):
            return True

        def open(self, *args, **kwargs):
            self.calls += 1
            if self.calls == 1:
                raise TimeoutError(60, "Operation timed out")
            return io.StringIO('{"row": 1}\n')

    path = FlakyJsonl()
    monkeypatch.setattr(timewarp.time, "sleep", lambda *_args, **_kwargs: None)

    assert timewarp.load_jsonl(path) == [{"row": 1}]
    assert path.calls == 2


def test_rows_by_day_returns_sorted_mapping_and_ignores_unparseable_rows() -> None:
    grouped = timewarp.rows_by_day(
        (
            {"time_utc": "2026-05-14T00:15:00+00:00", "value": 2},
            {"time_utc": "not-a-time", "value": 99},
            {"time_utc": "2026-05-13T23:45:00+00:00", "value": 1},
            {"time_utc": "2026-05-14T00:00:00+00:00", "value": 3},
        )
    )

    assert list(grouped) == ["2026-05-14", "2026-05-13"]
    assert [row["value"] for row in grouped["2026-05-14"]] == [3, 2]
    assert [row["value"] for row in grouped["2026-05-13"]] == [1]


def test_closed_bar_cache_rejects_stale_object_id_alias() -> None:
    timewarp.clear_replay_source_caches()
    rows_a = (
        {"time_utc": "2026-06-01T00:00:00+00:00", "close": 113.6},
    )
    rows_b = (
        {"time_utc": "2026-06-02T00:00:00+00:00", "close": 1.38},
    )
    asof = timewarp.parse_utc("2026-06-02T00:30:00+00:00")
    stale_close = timewarp.parse_utc("2026-06-01T00:15:00+00:00")
    assert asof is not None
    assert stale_close is not None
    cache_key = (id(rows_b), len(rows_b), 15)
    timewarp._CLOSED_BAR_INDEX_CACHE[cache_key] = (
        rows_a,
        (stale_close,),
        tuple(dict(row) for row in rows_a),
    )

    try:
        selected = timewarp.closed_bar_rows_until(
            rows_b,
            timeframe="M15",
            asof=asof,
        )

        assert [row["close"] for row in selected] == [1.38]
        assert timewarp._CLOSED_BAR_INDEX_CACHE[cache_key][0] is rows_b
    finally:
        timewarp.clear_replay_source_caches()


def test_predecision_tick_cache_rejects_stale_object_id_alias(monkeypatch) -> None:
    timewarp.clear_replay_source_caches()
    stale_source = object()
    current_source = object()
    asof_utc = "2026-06-02T10:15:00+00:00"
    cache_key = (id(current_source), asof_utc, 60.0)
    timewarp._PREDECISION_TICK_QUERY_CACHE[cache_key] = (
        stale_source,
        {
            "time_utc": "2026-06-01T10:15:00+00:00",
            "bid": 113.0,
            "ask": 114.0,
        },
        {"path_index_source_path": "stale-source"},
    )

    class CurrentSourcePathTruthIndex:
        def __init__(self, source):
            assert source is current_source

        def query(self, *, after, until):
            del after, until
            return timewarp.PathTruthQuery(
                rows=(
                    {
                        "time_utc": asof_utc,
                        "bid": 99.9,
                        "ask": 100.1,
                    },
                ),
                metadata={
                    "path_index_source_path": "current-source",
                    "path_index_source_sha256": "b" * 64,
                    "path_index_lookup_mode": "unit_test",
                },
            )

    monkeypatch.setattr(timewarp, "PathTruthIndex", CurrentSourcePathTruthIndex)
    try:
        tick, metadata = timewarp._predecision_tick_for_cost(
            candidate={
                "symbol": "XAUUSD",
                "entry_price": 100.0,
                "stop_loss": 90.0,
            },
            path_sources={"TICK": current_source},
            asof_utc=asof_utc,
            config={
                "gtos_vnext_runtime": {
                    "broad_live_as_if_replay_broker_cost_tick_lookback_minutes": 60.0
                }
            },
        )

        assert tick["time_utc"] == asof_utc
        assert metadata["path_index_source_path"] == "current-source"
        assert timewarp._PREDECISION_TICK_QUERY_CACHE[cache_key][0] is current_source
    finally:
        timewarp.clear_replay_source_caches()


def test_clear_replay_source_caches_clears_all_source_derived_indexes() -> None:
    timewarp.clear_replay_source_caches()
    rows = (
        {"time_utc": "2026-06-02T00:00:00+00:00", "close": 1.38},
    )
    asof = timewarp.parse_utc("2026-06-02T00:30:00+00:00")
    after = timewarp.parse_utc("2026-06-01T23:59:00+00:00")
    assert asof is not None
    assert after is not None
    timewarp.closed_bar_rows_until(rows, timeframe="M15", asof=asof)
    timewarp.rows_after_until_indexed(rows, after=after, until=asof)
    timewarp._PREDECISION_TICK_QUERY_CACHE[(1, "unit", 60.0)] = (
        object(),
        None,
        {},
    )

    assert timewarp.replay_source_cache_counts() == {
        "closed_bar_index": 1,
        "row_time_index": 1,
        "predecision_tick_query": 1,
    }

    timewarp.clear_replay_source_caches()

    assert timewarp.replay_source_cache_counts() == {
        "closed_bar_index": 0,
        "row_time_index": 0,
        "predecision_tick_query": 0,
    }


