def test_predecision_market_snapshot_transfer_preserves_atomic_poi_state() -> None:
    poi_state = _unit_fvg_poi_state()
    candidate = {
        "candidate_id": "current-fvg-logical-candidate",
        "decision_time_utc": "2026-05-14T01:00:00+00:00",
        "origin_family": "current_fvg_fill",
        "current_framework": "fvg_fill",
        "poi_state_required": True,
        "poi_id": poi_state["poi_id"],
        "poi_state_hash_sha256": poi_state["poi_state_hash_sha256"],
        "poi_state": poi_state,
        "source_fields": {
            "origin_family": "current_fvg_fill",
            "current_framework": "fvg_fill",
            "poi_state_required": True,
            "poi_id": poi_state["poi_id"],
            "poi_state_hash_sha256": poi_state["poi_state_hash_sha256"],
            "poi_state": poi_state,
        },
    }

    payload = timewarp.predecision_market_snapshot_transfer_payload(candidate)
    merged = timewarp.merge_predecision_market_snapshot_transfer_payload(
        {"candidate_id": candidate["candidate_id"]},
        payload,
    )

    assert payload["poi_state_transfer_status"] == timewarp.POI_STATE_TRANSFER_STATUS
    assert payload["poi_state_required"] is True
    assert payload["poi_state"] == poi_state
    assert payload["source_fields"]["poi_state"] == poi_state
    assert merged["poi_state"] == poi_state
    assert merged["candidate_decision_inputs"]["poi_state"] == poi_state
    assert merged["scheduler_candidate_decision_inputs"]["poi_state"] == poi_state


