def test_scorecard_selected_scheduler_option_preserves_ladder_and_effective_action() -> None:
    scheduler_packet = {
        "decision": {"selected_candidate_ids": ["candidate-risk-ladder"]},
        "asof_utc": "2026-06-03T00:15:00+00:00",
        "all_options_preserved": [
            {
                "candidate_id": "candidate-risk-ladder",
                "decision_time_utc": "2026-06-03T00:15:00+00:00",
                "selector_action": "open-reduced-risk",
                "score_components": {
                    "candidate_decision_inputs": {
                        "selector_action": "reject",
                        "selector_action_origin": "reject",
                        "effective_selector_action": "open-reduced-risk",
                        "risk_expression_ladder": {
                            "ladder_tier": "reduced",
                            "tier_causes": ["signed_reduced_package_authority"],
                        },
                    },
                    "risk_expression_ladder": {
                        "ladder_tier": "reduced",
                        "tier_causes": ["signed_reduced_package_authority"],
                    },
                },
                "decision_status": "selected",
                "action_class": "new_position",
                "score": 1.0,
            }
        ],
    }

    trace = timewarp.compact_scheduler_option_trace(scheduler_packet)
