def test_full_risk_expression_requires_original_top_rank_without_transfer_override() -> None:
    packet = _build_full_risk_expression_packet(
        scheduler_rank=3,
        finalizer_selected_rank=1,
    )

    assert packet["risk_decision"] == "open-reduced-risk", {
        "risk_decision": packet.get("risk_decision"),
        "risk_decision_reason": packet.get("risk_decision_reason"),
        "full_risk_failures": packet.get("package_risk_expression_full_risk_failures"),
        "scheduler_rank": packet.get("package_risk_expression_scheduler_rank"),
        "scheduler_rank_source": packet.get(
            "package_risk_expression_scheduler_rank_source"
        ),
        "finalizer_override_allowed": packet.get(
            "package_risk_expression_finalizer_rank_override_allowed"
        ),
    }
    assert packet["package_risk_expression_ladder"] == "reduced-risk"
    assert packet["package_risk_expression_full_risk_allowed"] is False
    assert packet["package_risk_expression_scheduler_rank"] == 3
    assert (
        packet["package_risk_expression_scheduler_rank_source"]
        == "scheduler_original_preserved_rank"
    )
