    assert packet["package_risk_expression_original_scheduler_rank"] == 3
    assert (
        packet["package_risk_expression_finalizer_rank_override_allowed"] is False
    )
    assert packet["package_risk_expression_finalizer_rank_override_block_reason"] == (
        "original_scheduler_rank_not_top_without_transfer_dominates_original_authority"
    )
    assert (
        "scheduler_selected_rank_not_top"
        in packet["package_risk_expression_full_risk_failures"]
    )
    assert packet["selector_reduced_entry_origin"] == "open-reduced-risk"


