    assert packet["package_risk_expression_fill_floor_unresolved_failures"] == [
        "fill_probability_below_execution_authority_floor"
    ]
    assert (
        "execution_fillability_below_full_risk_floor"
        in packet["package_risk_expression_full_risk_failures"]
    )


