    assert capped["final_approved_risk_pct"] == 0.10
    assert capped["runtime_final_risk_pct"] == 0.10
    assert capped["approved_risk_pct"] == 0.10
    assert capped["scheduler_approved_risk_pct"] == 1.0
    assert capped["selected_cell_risk_pct"] == 1.0
