def test_runtime_public_risk_prefers_executable_final_over_stale_runtime_alias() -> None:
    fields = timewarp.runtime_risk_public_authority_fields(
        {
            "risk_pct": 1.0,
            "final_approved_risk_pct": 1.0,
            "risk_authority": {
                "risk_decision": "trade",
                "final_approved_risk_pct": 1.0,
                "runtime_final_risk_pct": 0.0,
                "approved_risk_pct": 0.25,
            },
        }
    )

    assert fields["final_approved_risk_pct"] == 1.0
    assert fields["runtime_final_risk_pct"] == 1.0
    assert fields["approved_risk_pct"] == 1.0
    assert fields["risk_authority_public_final_risk_pct_source"] == (
        "legacy_nested_executable_final_approved_risk_pct"
    )
    assert fields["risk_authority_public_final_risk_pct_conflict"] is True
    assert fields[
        "risk_authority_public_final_risk_pct_conflicting_nested_fields"
    ] == ["approved_risk_pct", "runtime_final_risk_pct"]


