def _add_strict_limit_fillability(
    row: dict,
    fill_probability: float | None = None,
    *,
    execution_fill_probability_source: str = "predecision_limit_fillability",
) -> dict:
    fill = (
        fill_probability
        if fill_probability is not None
        else row.get("predecision_limit_fillability_probability")
        or row.get("limit_fillability_probability")
        or row.get("execution_fill_probability")
        or row.get("candidate_fill_probability")
        or row.get("fill_probability")
    )
    if fill in (None, ""):
        return row
    row["predecision_limit_fillability_probability"] = fill
    row["limit_fillability_probability"] = fill
    row["execution_fill_probability"] = fill
    row["execution_fill_probability_source"] = execution_fill_probability_source
    for projected_field in (
        "package_new_entry_authority_predecision_limit_fillability_probability",
        "package_new_entry_authority_limit_fillability_probability",
        "package_new_entry_authority_execution_fill_probability",
    ):
        if projected_field in row:
            row[projected_field] = fill
    fillability = row.get("predecision_limit_fillability")
    fillability = dict(fillability) if isinstance(fillability, dict) else {}
    fillability["fill_probability"] = fill
    fillability.setdefault(
        "source_boundary",
        "asof_candidate_fields_only_no_postdecision_path",
    )
    decision_time = timewarp.parse_utc(
        row.get("decision_time_utc") or row.get("asof_utc")
    )
    if decision_time is not None:
        source_time_utc = (decision_time - timedelta(minutes=15)).isoformat()
        fillability.setdefault(
            "current_price_source_time_utc",
            source_time_utc,
        )
        row["execution_fill_probability_source_time_utc"] = source_time_utc
        row["predecision_limit_fillability_source_time_utc"] = source_time_utc
    source_boundary = fillability.get("source_boundary")
    if source_boundary not in (None, ""):
        row["execution_fill_probability_source_boundary"] = source_boundary
        row["predecision_limit_fillability_source_boundary"] = source_boundary
    row["predecision_limit_fillability"] = fillability
    sources = row.get("candidate_decision_quality_field_sources")
    sources = dict(sources) if isinstance(sources, dict) else {}
    sources["limit_fillability_probability"] = (
        "predecision_limit_fillability.fill_probability"
    )
    sources["execution_fill_probability"] = (
        "predecision_limit_fillability.fill_probability"
    )
    row["candidate_decision_quality_field_sources"] = sources
    return row


def _strictify_execution_fillability_fixture_tree(
    value,
    *,
    inherited_decision_time_utc: str | None = None,
) -> None:
    """Bind legacy valid-fixture aliases to one predecision temporal envelope."""

    seen: set[int] = set()

    def visit(node, decision_time_utc: str | None = None) -> None:
        if isinstance(node, dict):
            if id(node) in seen:
                return
            seen.add(id(node))
            carries_signed_payload = bool(
                isinstance(node.get("package_new_entry_authority_payload"), dict)
                or node.get("package_new_entry_authority_hash_sha256")
                not in (None, "")
                or node.get("expected_package_new_entry_authority_hash_sha256")
                not in (None, "")
            )
            if carries_signed_payload:
                signed = timewarp.package_new_entry_authority_attribution_fields(node)
                if signed.get("package_new_entry_authority_valid") is True:
                    return
            local_decision_time = str(
                node.get("decision_time_utc")
                or node.get("asof_utc")
                or node.get("candle_close_utc")
                or decision_time_utc
                or ""
            ).strip()
            nested_fillability = node.get("predecision_limit_fillability")
            nested_fillability = (
                nested_fillability
                if isinstance(nested_fillability, dict)
                else {}
            )
            direct_fill = node.get("execution_fill_probability")
            direct_source = node.get("execution_fill_probability_source")
            if not scheduler.execution_fillability_source_is_authoritative(
                direct_source,
                node.get("execution_fill_probability_authority_class"),
            ):
                direct_fill = None
            fill = next(
                (
                    parsed
                    for candidate in (
                        node.get("predecision_limit_fillability_probability"),
                        node.get("pending_limit_fillability_probability"),
                        node.get("limit_fillability_probability"),
                        nested_fillability.get("fill_probability"),
                        nested_fillability.get("limit_fillability_probability"),
                        direct_fill,
                    )
                    if (parsed := timewarp._optional_float(candidate)) is not None
                ),
                None,
            )
            if fill is not None and local_decision_time:
                node.setdefault("decision_time_utc", local_decision_time)
                _add_strict_limit_fillability(node, fill)
            for key, nested in list(node.items()):
                if (
                    key == "package_new_entry_authority_payload"
                    or key.endswith("_field_sources")
                    or (
                        key.startswith("ultimate_candidate_package_")
                        and key.endswith("_risk_authority")
                    )
                ):
                    continue
                visit(nested, local_decision_time or decision_time_utc)
        elif isinstance(node, list):
            for nested in node:
                visit(nested, decision_time_utc)
        elif isinstance(node, tuple):
            for nested in node:
                visit(nested, decision_time_utc)

    visit(value, inherited_decision_time_utc)


def _finalize_scheduler_risk_admitted_selection_fixture(**kwargs):
    prepared = copy.deepcopy(kwargs)
    scheduler_packet = prepared.get("scheduler_packet")
    _strictify_execution_fillability_fixture_tree(scheduler_packet)
    _strictify_execution_fillability_fixture_tree(prepared.get("all_candidates"))
    v4_packets = prepared.get("v4_packets")
    if isinstance(v4_packets, dict):
        for packet_key, packet in v4_packets.items():
            decision_time = (
                str(packet_key).rsplit("@@", 1)[-1]
                if "@@" in str(packet_key)
                else None
            )
            _strictify_execution_fillability_fixture_tree(
                packet,
                inherited_decision_time_utc=decision_time,
            )
    return timewarp.finalize_scheduler_risk_admitted_selection(**prepared)


def test_strict_fillability_fixture_does_not_promote_generic_source_metadata() -> None:
    row = {
        "decision_time_utc": "2026-05-13T08:15:00+00:00",
        "execution_fill_probability": 0.81,
        "execution_fill_probability_source": "execution_fill_probability",
        "candidate_decision_quality_field_sources": {
            "execution_fill_probability": (
                "predecision_limit_fillability.fill_probability"
            ),
        },
    }

    _strictify_execution_fillability_fixture_tree(row)

    assert "predecision_limit_fillability_probability" not in row
    assert "predecision_limit_fillability" not in row
    assert row["execution_fill_probability_source"] == "execution_fill_probability"


