def _explicit_package_preflight(
    net: float = 1.0,
    probability: float = 0.85,
    fill: float = 0.90,
    *,
    candidate_id: str | None = None,
    decision_time_utc: str | None = None,
    axis_id: str | None = None,
    execution_fill: float | None = None,
    order_allowed: bool = True,
    order_reason: str = "unit_test_package_order_route_authorized",
    order_source: str = "unit_test_explicit_package_preflight",
    total_cost_r: float = 0.05,
) -> dict:
    if (candidate_id is None) != (decision_time_utc is None):
        raise AssertionError("candidate_id and decision_time_utc must be supplied together")
    stable_axis_id = axis_id or (
        f"unit_test:{candidate_id}:member_axis"
        if candidate_id
        else "unit_test:explicit_package_preflight:member_axis"
    )
    cost_packet = _broker_calibrated_fixture_cost_packet(total_cost_r)
    fields = {
        "source_bound_package_candidate_use_allowed": True,
        "ultimate_package_source_bound_candidate_use_allowed": True,
        **_exact_package_member_axis_proof(stable_axis_id),
        "package_replay_candidate_use_allowed": True,
        "package_replay_executable_candidate_use_allowed": True,
        "package_replay_executable_candidate_use_allowed_reason": (
            "broker_cost_and_scheduler_action_executable"
        ),
        "package_replay_order_executable_candidate_use_allowed": order_allowed,
        "package_replay_order_executable_candidate_use_allowed_reason": order_reason,
        "package_replay_order_executable_authority_source": order_source,
        "expected_net_r": net,
        "candidate_expected_net_r": net,
        "probability": probability,
        "candidate_probability": probability,
        "fill_probability": fill,
        "candidate_fill_probability": fill,
        "entry_quality_fill_probability": fill,
        "source_completeness": 1.0,
        "source_completeness_status": "complete",
        "candidate_decision_quality_field_sources": dict(
            PREDECISION_QUALITY_FIELD_SOURCES
        ),
        "candidate_decision_quality_source_boundary": (
            PREDECISION_QUALITY_SOURCE_BOUNDARY
        ),
        "candidate_decision_quality_alias_status": "exact_materialized",
        "candidate_decision_quality_alias_mismatches": [],
        "candidate_decision_quality_provenance_failures": [],
        "pretrade_cost_packet_status": "PASSED",
        "cost_authority": "broker_calibrated_replay_cost",
        "cost_source_gap_status": "source_bound_cost_authority_present",
        "candidate_cost_r_fallback_is_authority": False,
        "expected_cost_r": total_cost_r,
        "pretrade_broker_net_cost_packet": cost_packet,
    }
    if candidate_id is not None and decision_time_utc is not None:
        fields.update(
            {
                "candidate_id": candidate_id,
                "candidate_id_source": "candidate_id",
                "decision_time_utc": decision_time_utc,
                **_exact_candidate_instance_proof(candidate_id, decision_time_utc),
            }
        )
    _add_strict_limit_fillability(
        fields,
        fill if execution_fill is None else execution_fill,
    )
    return fields


def _complete_executable_reduced_risk_fixture(
    row: dict,
    *,
    candidate_id: str | None = None,
    decision_time_utc: str | None = None,
    axis_id: str | None = None,
    entry_fill_probability: float | None = None,
    execution_fill_probability: float | None = None,
    execution_fill_probability_source: str | None = None,
    order_allowed: bool | None = None,
    order_reason: str | None = None,
    order_source: str | None = None,
    total_cost_r: float = 0.05,
) -> dict:
    candidate_id = str(candidate_id or row.get("candidate_id") or "").strip()
    decision_time_utc = str(
        decision_time_utc
        or row.get("decision_time_utc")
        or row.get("candle_close_utc")
        or ""
    ).strip()
    if not candidate_id or not decision_time_utc:
        raise AssertionError("valid executable authority fixtures require exact identity")

    def first_present(*values):
        return next((value for value in values if value not in (None, "")), None)

    expected_net_r = first_present(
        row.get("expected_net_r"),
        row.get("candidate_expected_net_r"),
    )
    probability = first_present(row.get("probability"), row.get("candidate_probability"))
    confidence = first_present(
        row.get("candidate_confidence"),
        row.get("confidence"),
        probability,
    )
    entry_fill_probability = first_present(
        entry_fill_probability,
        row.get("entry_quality_fill_probability"),
        row.get("candidate_fill_probability"),
        row.get("fill_probability"),
    )
    execution_fill_probability = first_present(
        execution_fill_probability,
        row.get("predecision_limit_fillability_probability"),
        row.get("limit_fillability_probability"),
        row.get("execution_fill_probability"),
        entry_fill_probability,
    )
    if expected_net_r is None or probability is None or entry_fill_probability is None:
        raise AssertionError("valid executable authority fixtures require source quality")

    row.update(
        {
            "candidate_id": candidate_id,
            "candidate_id_source": "candidate_id",
            "decision_time_utc": decision_time_utc,
            **_exact_candidate_instance_proof(candidate_id, decision_time_utc),
            **_exact_package_member_axis_proof(
                axis_id or f"unit_test:{candidate_id}:member_axis"
            ),
            "expected_net_r": expected_net_r,
            "candidate_expected_net_r": expected_net_r,
            "probability": probability,
            "candidate_probability": probability,
            "confidence": confidence,
            "candidate_confidence": confidence,
            "fill_probability": entry_fill_probability,
            "candidate_fill_probability": entry_fill_probability,
            "entry_quality_fill_probability": entry_fill_probability,
            "source_completeness": first_present(
                row.get("source_completeness"),
                1.0,
            ),
            "source_completeness_status": first_present(
                row.get("source_completeness_status"),
                "source_completeness_present",
            ),
            "source_bound_package_candidate_use_allowed": True,
            "ultimate_package_source_bound_candidate_use_allowed": True,
            "package_replay_candidate_use_allowed": True,
            "package_replay_executable_candidate_use_allowed": True,
            "package_replay_executable_candidate_use_allowed_reason": (
                "broker_cost_and_scheduler_action_executable"
            ),
        }
    )
    quality_sources = dict(row.get("candidate_decision_quality_field_sources") or {})
    quality_sources.update(PREDECISION_QUALITY_FIELD_SOURCES)
    row["candidate_decision_quality_field_sources"] = quality_sources
    row["candidate_decision_quality_source_boundary"] = (
        PREDECISION_QUALITY_SOURCE_BOUNDARY
    )
    row["candidate_decision_quality_alias_status"] = "exact_materialized"
    row["candidate_decision_quality_alias_mismatches"] = []
    row["candidate_decision_quality_provenance_failures"] = []
    _add_strict_limit_fillability(
        row,
        execution_fill_probability,
        execution_fill_probability_source=(
            execution_fill_probability_source or "predecision_limit_fillability"
        ),
    )

    cost_packet = {
        **_broker_calibrated_fixture_cost_packet(total_cost_r),
        **dict(row.get("pretrade_broker_net_cost_packet") or {}),
    }
    cost_packet.setdefault("total_cost_r", total_cost_r)
    cost_packet.setdefault("atomic_conflicts", [])
    row.update(
        {
            "pretrade_broker_net_cost_packet": cost_packet,
            "pretrade_cost_packet_status": cost_packet["status"],
            "cost_authority": cost_packet["authority"],
            "cost_source_gap_status": cost_packet["cost_source_gap_status"],
            "candidate_cost_r_fallback_is_authority": cost_packet[
                "candidate_cost_r_fallback_is_authority"
            ],
            "expected_cost_r": cost_packet["total_cost_r"],
        }
    )
    if order_allowed is None:
        current_order_allowed = row.get(
            "package_replay_order_executable_candidate_use_allowed"
        )
        order_allowed = (
            current_order_allowed
            if isinstance(current_order_allowed, bool)
            else True
        )
    row["package_replay_order_executable_candidate_use_allowed"] = order_allowed
    row["package_replay_order_executable_candidate_use_allowed_reason"] = (
        order_reason
        or str(
            row.get(
                "package_replay_order_executable_candidate_use_allowed_reason"
            )
            or ""
        ).strip()
        or (
            "unit_test_signed_order_executable_allowed"
            if order_allowed
            else "unit_test_signed_order_executable_denied"
        )
    )
    row["package_replay_order_executable_authority_source"] = (
        order_source
        or str(row.get("package_replay_order_executable_authority_source") or "").strip()
        or "unit_test_complete_executable_reduced_risk_fixture"
    )
    canonical_quality = timewarp.candidate_decision_quality_fields(
        row,
        {"pretrade_broker_net_cost_packet": cost_packet},
    )
    selected_policy_hash = first_present(
        canonical_quality.get("selected_policy_expected_net_assumption_hash"),
        canonical_quality.get("selected_policy_expected_net_calibration_hash"),
        row.get("selected_policy_expected_net_assumption_hash"),
        row.get("selected_policy_expected_net_calibration_hash"),
    )
    if selected_policy_hash is not None:
        row["selected_policy_expected_net_assumption_hash"] = selected_policy_hash
        row["selected_policy_expected_net_calibration_hash"] = selected_policy_hash
        canonical_quality["selected_policy_expected_net_assumption_hash"] = (
            selected_policy_hash
        )
        canonical_quality["selected_policy_expected_net_calibration_hash"] = (
            selected_policy_hash
        )
    row["candidate_decision_quality"] = dict(
        canonical_quality["candidate_decision_quality"]
    )
    for key, value in canonical_quality.items():
        if key.startswith("selected_policy_") and value not in (None, ""):
            row[key] = value
    row["candidate_decision_quality_field_sources"] = dict(
        canonical_quality["candidate_decision_quality_field_sources"]
    )
    row["candidate_decision_quality_source_boundary"] = canonical_quality[
        "candidate_decision_quality_source_boundary"
    ]
    row["candidate_decision_quality_alias_status"] = canonical_quality[
        "candidate_decision_quality_alias_status"
    ]
    row["candidate_decision_quality_alias_mismatches"] = list(
        canonical_quality.get("candidate_decision_quality_alias_mismatches") or []
    )
    row["candidate_decision_quality_provenance_failures"] = list(
        canonical_quality.get("candidate_decision_quality_provenance_failures") or []
    )
    return row


def _stamp_valid_executable_reduced_risk_fixture(
    row: dict,
    *,
    selector_action: str,
    selector_reason: str,
    authority: dict,
    action_intent: str = "new_position",
    config: dict | None = None,
    execution_fill_probability_source: str | None = None,
    **fixture_kwargs,
) -> dict:
    source_bound_router_authority = bool(
        selector_reason == timewarp.SOURCE_BOUND_ROUTER_REFUSAL_OPEN_REDUCED_REASON
        or authority.get("authority_source")
        == "derived_from_source_bound_router_refusal_package_authority"
    )
    if source_bound_router_authority:
        strict_route_floors = dict(STRICT_SOURCE_BOUND_ROUTER_REFUSAL_FLOORS)
        supplied_route_floors = authority.get(
            "source_bound_router_refusal_materialization_floors"
        ) or row.get("source_bound_router_refusal_materialization_floors")
        if isinstance(supplied_route_floors, dict) and all(
            supplied_route_floors.get(field) is not None
            for field in strict_route_floors
        ):
            strict_route_floors = dict(supplied_route_floors)
        row["source_bound_router_refusal_materialization_floors"] = dict(
            strict_route_floors
        )
        authority["source_bound_router_refusal_materialization_floors"] = dict(
            strict_route_floors
        )
    _complete_executable_reduced_risk_fixture(
        row,
        execution_fill_probability_source=execution_fill_probability_source,
        **fixture_kwargs,
    )
    stamped = stamp_package_new_entry_authority(
        row,
        selector_action=selector_action,
        selector_reason=selector_reason,
        authority=authority,
        action_intent=action_intent,
        config=config,
    )
    assert stamped["package_new_entry_authority_valid"] is True, json.dumps(
        stamped.get("package_new_entry_authority_failures"),
        indent=2,
    )
    authority_field = stamped["package_new_entry_authority_authority_field"]
    row[authority_field] = stamped
    row.update(timewarp.package_new_entry_authority_attribution_fields(stamped))
    signed_payload = stamped["package_new_entry_authority_payload"]
    nested_quality = dict(row.get("candidate_decision_quality") or {})
    for key in (
        "selected_policy_for_expected_net_r",
        "selected_policy_expected_net_calibration_status",
        "selected_policy_expected_net_calibrated",
        "selected_policy_expected_net_calibration_required",
        "selected_policy_expected_net_calibration_source",
        "selected_policy_expected_net_calibration_source_boundary",
        "selected_policy_expected_net_calibration_hash",
    ):
        if key in signed_payload:
            row[key] = signed_payload[key]
            nested_quality[key] = signed_payload[key]
    if "selected_policy_expected_net_calibration_hash" in signed_payload:
        row["selected_policy_expected_net_assumption_hash"] = signed_payload[
            "selected_policy_expected_net_calibration_hash"
        ]
        nested_quality["selected_policy_expected_net_assumption_hash"] = (
            signed_payload["selected_policy_expected_net_calibration_hash"]
        )
    row["candidate_decision_quality"] = nested_quality
    return stamped


def _assert_canonical_provisional_package_authority(authority: dict) -> None:
    marker = timewarp.PACKAGE_NEW_ENTRY_AUTHORITY_PROVISIONAL_MARKER
    payload = authority["package_new_entry_authority_payload"]
    canonical_hash = timewarp.package_new_entry_authority_payload_hash_sha256(
        payload
    )
    validation = timewarp.package_new_entry_authority_attribution_fields(
        authority
    )

    assert authority[marker] is True
    assert authority["package_new_entry_authority_valid"] is False
    assert validation["package_new_entry_authority_valid"] is False
    assert "authority_provisional_marker_present" in validation[
        "package_new_entry_authority_failures"
    ]
    assert authority["package_new_entry_authority_hash_sha256"] == canonical_hash
    assert authority[
        "expected_package_new_entry_authority_hash_sha256"
    ] == canonical_hash


def _finalize_provisional_package_authority_fixture(
    *,
    candidate: dict,
    packets: dict,
    authority: dict,
    action_intent: str = "new_position",
) -> dict:
    _assert_canonical_provisional_package_authority(authority)
    selector_reason = str(authority.get("selector_reason") or "").strip()
    authority_seed = {
        key: copy.deepcopy(value)
        for key, value in authority.items()
        if not key.startswith("package_new_entry_authority_")
    }
    row = copy.deepcopy(candidate)
    row.update(
        {
            "selector_action": "open-reduced-risk",
            "selector_reason": selector_reason,
            "scheduler_materialization_action_intent": action_intent,
        }
    )
    cost_packet = packets.get("pretrade_broker_net_cost_packet")
    if isinstance(cost_packet, dict):
        row["pretrade_broker_net_cost_packet"] = copy.deepcopy(cost_packet)
    entry_fill_probability = (
        authority.get("entry_quality_fill_probability")
        or candidate.get("entry_quality_fill_probability")
        or candidate.get("candidate_fill_probability")
        or candidate.get("fill_probability")
    )
    execution_fill_probability = (
        authority.get("execution_fill_probability")
        or candidate.get("execution_fill_probability")
        or candidate.get("predecision_limit_fillability_probability")
        or entry_fill_probability
    )
    execution_fill_probability_source = (
        authority.get("execution_fill_probability_source")
        or candidate.get("execution_fill_probability_source")
        or "predecision_limit_fillability"
    )
    order_allowed = authority.get(
        "package_replay_order_executable_candidate_use_allowed"
    )
    return _stamp_valid_executable_reduced_risk_fixture(
        row,
        selector_action="open-reduced-risk",
        selector_reason=selector_reason,
        authority=authority_seed,
        action_intent=action_intent,
        axis_id=f"unit_test:{row['candidate_id']}:finalized_member_axis",
        entry_fill_probability=entry_fill_probability,
        execution_fill_probability=execution_fill_probability,
        execution_fill_probability_source=execution_fill_probability_source,
        order_allowed=order_allowed if isinstance(order_allowed, bool) else True,
        order_reason=str(
            authority.get(
                "package_replay_order_executable_candidate_use_allowed_reason"
            )
            or "unit_test_finalized_materialized_order_authority"
        ),
        order_source=str(
            authority.get("package_replay_order_executable_authority_source")
            or "unit_test_finalized_materialized_authority"
        ),
    )


def write_json(path: Path, payload: dict) -> None:
    path.write_text(json.dumps(payload, indent=2, sort_keys=True) + "\n", encoding="utf-8")


def write_jsonl(path: Path, rows: list[dict]) -> None:
    path.write_text(
        "".join(json.dumps(row, sort_keys=True) + "\n" for row in rows),
        encoding="utf-8",
    )


def test_path_source_and_oracle_uses_labeled_m15_proxy_when_m1_missing(
    monkeypatch,
) -> None:
    candidate = {
        "symbol": "XAUUSD",
        "side": "LONG",
        "entry_price": 100.0,
        "stop_loss": 99.0,
        "take_profit_1": 102.0,
    }
    rows = (
        {
            "time_utc": "2026-04-21T08:15:00+00:00",
            "open": 100.4,
            "high": 100.7,
            "low": 99.8,
            "close": 100.5,
        },
        {
            "time_utc": "2026-04-21T08:30:00+00:00",
            "open": 100.8,
            "high": 102.5,
            "low": 100.7,
            "close": 102.1,
        },
    )
    source = ResolvedSource(
        spec=SourceSpec(
            symbol="XAUUSD",
            mapped_symbol="XAUUSD",
            timeframe="M15",
            path=Path("fixture_m15.csv"),
            source_family="fixture",
            source_broker="FTMO",
            source_role="owner_authorized_research_hydration",
            source_truth_scope=SOURCE_TRUTH_SCOPE,
        ),
        rows=rows,
        rows_by_day={"2026-04-21": rows},
        sha256="e" * 64,
        day_counts={"2026-04-21": len(rows)},
        selected_status="fixture",
        min_required_rows_per_day=1,
    )
    asof = parse_utc("2026-04-21T08:00:00+00:00")
    expiry = parse_utc("2026-04-21T10:00:00+00:00")
    query_calls = 0
    original_query = timewarp.PathTruthIndex.query

    def counted_query(index, *, after, until):
        nonlocal query_calls
        query_calls += 1
        return original_query(index, after=after, until=until)

    monkeypatch.setattr(timewarp.PathTruthIndex, "query", counted_query)
    query_cache = {}

    oracle, path_source, path_rows = timewarp.path_source_and_oracle(
        candidate=candidate,
        sources={"M15": source},
        day="2026-04-21",
        asof=asof,
        expiry=expiry,
        query_cache=query_cache,
    )
    repeated_oracle, _repeated_source, repeated_rows = (
        timewarp.path_source_and_oracle(
            candidate=candidate,
            sources={"M15": source},
            day="2026-04-21",
            asof=asof,
            expiry=expiry,
            query_cache=query_cache,
        )
    )

    assert query_calls == 1
    assert repeated_oracle == oracle
    assert repeated_rows == path_rows
    assert oracle["source"] == "m15_proxy"
    assert oracle["postdecision_path_proxy"] is True
    assert oracle["ordered_tick_truth_satisfied"] is False
    assert oracle["fill_realism_class"] == "m15_proxy"
    assert oracle["fill_realism_executable"] is False
    assert oracle["fill_status"] == "not_filled_fill_realism_diagnostic_only"
    assert oracle["package_execution_result_scope"] == "diagnostic_counterfactual_only"
    assert "postdecision_m15_path_proxy_used_because_m1_or_tick_path_unavailable" in oracle["source_gaps"]
    assert path_source.spec.diagnostic_fallback_only is True
    assert path_source.spec.replaces_missing_frozen_path_source is True
    assert path_source.selected_status == "selected_m15_postdecision_path_proxy_m1_or_tick_unavailable"
    assert len(path_rows) == 2


def test_path_truth_query_cache_is_scoped_to_exact_source_identity(
    monkeypatch,
) -> None:
    first_rows = (
        {
            "time_utc": "2026-04-21T08:15:00+00:00",
            "open": 100.0,
            "high": 101.0,
            "low": 99.0,
            "close": 100.5,
        },
    )
    second_rows = (
        {
            "time_utc": "2026-04-21T08:15:00+00:00",
            "open": 200.0,
            "high": 201.0,
            "low": 199.0,
            "close": 200.5,
        },
    )

    def source(symbol: str, rows: tuple[dict[str, Any], ...]) -> ResolvedSource:
        return ResolvedSource(
            spec=SourceSpec(
                symbol=symbol,
                mapped_symbol=symbol,
                timeframe="M1",
                path=Path("shared_fixture.csv"),
                source_family=f"fixture_{symbol}",
                source_broker="FTMO",
                source_role="owner_authorized_research_hydration",
                source_truth_scope=SOURCE_TRUTH_SCOPE,
            ),
            rows=rows,
            rows_by_day={"2026-04-21": rows},
            sha256="e" * 64,
            day_counts={"2026-04-21": len(rows)},
            selected_status=f"fixture_{symbol}",
            min_required_rows_per_day=1,
        )

    first_source = source("XAUUSD", first_rows)
    second_source = source("EURUSD", second_rows)
    after = parse_utc("2026-04-21T08:00:00+00:00")
    until = parse_utc("2026-04-21T08:30:00+00:00")
    query_calls = 0
    original_query = timewarp.PathTruthIndex.query

    def counted_query(index, *, after, until):
        nonlocal query_calls
        query_calls += 1
        return original_query(index, after=after, until=until)

    monkeypatch.setattr(timewarp.PathTruthIndex, "query", counted_query)
    query_cache = {}

    first = timewarp.cached_path_truth_query(
        first_source,
        after=after,
        until=until,
        query_cache=query_cache,
    )
    second = timewarp.cached_path_truth_query(
        second_source,
        after=after,
        until=until,
        query_cache=query_cache,
    )
    repeated_first = timewarp.cached_path_truth_query(
        first_source,
        after=after,
        until=until,
        query_cache=query_cache,
    )

    assert query_calls == 2
    assert first.rows == first_rows
    assert second.rows == second_rows
    assert repeated_first is first


