def test_selected_diagnostic_counterfactual_orders_expand_to_missed_contract() -> None:
    source = Path(timewarp.__file__).read_text(encoding="utf-8")
    missed_start = source.index('ledgers["missed"].append')
    condition_start = source.index('"risk_rejected",', missed_start)
    block_end = source.index("execution_sidecar_id = stable_sha256", condition_start)
    missed_block = source[condition_start:block_end]

    assert '"diagnostic_counterfactual_not_materialized"' in missed_block
    assert "selected_candidate_diagnostic_fill_realism_counterfactual" in missed_block
    assert 'sim["order"].get("policy_gross_r")' in missed_block
    assert 'sim["order"].get("raw_gross_r")' in missed_block


