def test_replay_feed_preserves_data_incomplete_error(monkeypatch) -> None:
    feed = timewarp.ReplayFeed(timewarp.HistoricalMT5Adapter({"XAUUSD": {}}), {})

    def fake_ingest(*_args, **_kwargs):
        raise timewarp.DataIncompleteError("Insufficient M15 candles")

    monkeypatch.setattr(timewarp, "ingest_live_data", fake_ingest)

    with pytest.raises(timewarp.DataIncompleteError, match="Insufficient M15"):
        feed.snapshot(symbol="XAUUSD", asof=parse_utc("2026-04-21T08:00:00+00:00"))


