def test_scheduler_config_preserves_package_fill_floor_execution_drag_penalty() -> None:
    config = timewarp.scheduler_config(
        {
            "gtos_vnext_runtime": {
                "scheduler_v4_best_trade_allocator_selector_reduce_risk_package_fill_floor_execution_drag_penalty_enabled": True,
                "scheduler_v4_best_trade_allocator_selector_reduce_risk_package_fill_floor_execution_drag_min_fill_probability": 0.47,
                "scheduler_v4_best_trade_allocator_selector_reduce_risk_package_fill_floor_execution_drag_gap_weight": 1.35,
                "scheduler_v4_best_trade_allocator_selector_reduce_risk_package_fill_floor_execution_drag_cost_weight": 0.90,
                "scheduler_v4_best_trade_allocator_selector_reduce_risk_package_fill_floor_execution_drag_max_penalty": 0.62,
                "scheduler_v4_best_trade_allocator_package_replay_executable_authority_dominates_fill_floor": True,
                "scheduler_v4_best_trade_allocator_selector_reduce_risk_router_refusal_package_new_entry_authority_enabled": True,
                "scheduler_v4_best_trade_allocator_selector_reduce_risk_numeric_disagreement_package_new_entry_authority_enabled": False,
                "ultimate_candidate_package_numeric_disagreement_open_reduced_risk_min_expected_net_r": 1.23,
                "ultimate_candidate_package_numeric_disagreement_open_reduced_risk_min_probability": 0.94,
                "ultimate_candidate_package_numeric_disagreement_open_reduced_risk_min_fill_probability": 0.91,
                "ultimate_candidate_package_numeric_disagreement_open_reduced_risk_min_source_completeness": 0.97,
            }
        }
    )

    assert (
        config[
            "selector_reduce_risk_package_fill_floor_execution_drag_penalty_enabled"
        ]
        is True
    )
    assert (
        config[
            "selector_reduce_risk_package_fill_floor_execution_drag_min_fill_probability"
        ]
        == 0.47
    )
    assert (
        config["selector_reduce_risk_package_fill_floor_execution_drag_gap_weight"]
        == 1.35
    )
    assert (
        config["selector_reduce_risk_package_fill_floor_execution_drag_cost_weight"]
        == 0.90
    )
    assert (
        config["selector_reduce_risk_package_fill_floor_execution_drag_max_penalty"]
        == 0.62
    )
    assert config["package_replay_executable_authority_dominates_fill_floor"] is True
    assert (
        config[
            "selector_reduce_risk_router_refusal_package_new_entry_authority_enabled"
        ]
        is True
    )
    assert (
        config[
            "selector_reduce_risk_numeric_disagreement_package_new_entry_authority_enabled"
        ]
        is False
    )
    assert (
        config[
            "ultimate_candidate_package_numeric_disagreement_open_reduced_risk_min_expected_net_r"
        ]
        == 1.23
    )
    assert (
        config[
            "ultimate_candidate_package_numeric_disagreement_open_reduced_risk_min_probability"
        ]
        == 0.94
    )
    assert (
        config[
            "ultimate_candidate_package_numeric_disagreement_open_reduced_risk_min_fill_probability"
        ]
        == 0.91
    )
    assert (
        config[
            "ultimate_candidate_package_numeric_disagreement_open_reduced_risk_min_source_completeness"
        ]
        == 0.97
    )


