def test_selected_scorecard_quality_binds_exact_candidate_instance() -> None:
    decision_time = "2026-05-13T08:00:00+00:00"
    candidate = {
        "candidate_id": "quality-exact",
        "decision_time_utc": decision_time,
        "symbol": "XAUUSD",
        "side": "LONG",
        "expected_net_r": 1.21,
        "probability": 0.88,
        "fill_probability": 0.77,
        "source_completeness": 1.0,
        "source_completeness_status": "complete",
    }
    stale_instance = {
        **candidate,
        "decision_time_utc": "2026-05-13T07:45:00+00:00",
        "expected_net_r": -4.0,
        "probability": 0.1,
    }
    packets = {
        "selector_packet": {"action": "trade", "reason": "unit_test"},
        "pretrade_broker_net_cost_packet": {
            "status": "PASSED",
            "authority": "broker_calibrated_replay_cost",
            "cost_source_gap_status": "source_bound_cost_authority_present",
            "candidate_cost_r_fallback_is_authority": False,
            "total_cost_r": 0.04,
        },
    }
    instance_key = f"quality-exact@@{decision_time}"

    fields = timewarp.scorecard_selected_runtime_quality_contract_fields(
        {
            "selected_candidate_id": "quality-exact",
            "selected_candidate_ids": ["quality-exact"],
            "decision_time_utc": decision_time,
            "expected_net_r": -99.0,
            "probability": 0.01,
            "source_completeness": 0.0,
        },
        [stale_instance, candidate],
        {instance_key: packets},
    )

    assert fields["expected_net_r"] == 1.21
    assert fields["probability"] == 0.88
    assert fields["fill_probability"] == 0.77
    assert fields["source_completeness"] == 1.0
    assert fields["canonical_replay_candidate_instance_key"] == instance_key
    assert fields["candidate_id"] == "quality-exact"
    assert fields["runtime_quality_contract_candidate_instance_key"] == instance_key
    assert fields["runtime_quality_contract_selected_top_level_truth"] is True
    assert fields["runtime_quality_contract_surface"] == "selected_scorecard"
    assert fields["runtime_quality_contract_quality_field_sources"][
        "probability"
    ] == "candidate.probability"


