def test_member_axis_projection_reuses_exact_immutable_authority_match(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    rows = (
        {
            "stable_member_axis_id": "member_axis:XAUUSD:LONG:cached",
            "symbol": "XAUUSD",
            "side": "LONG",
            "package_role": "scheduler_lifecycle_core",
            "combined_source_bound_signal_r": 8.0,
        },
        {
            "stable_member_axis_id": "member_axis:EURUSD:SHORT:other",
            "symbol": "EURUSD",
            "side": "SHORT",
            "package_role": "scheduler_lifecycle_core",
            "combined_source_bound_signal_r": 3.0,
        },
    )
    monkeypatch.setattr(timewarp, "ultimate_package_member_axis_rows", lambda: rows)
    original_matcher = timewarp._ultimate_package_member_axis_matches_key
    match_calls = 0

    def counted_matcher(member: dict, key: tuple) -> bool:
        nonlocal match_calls
        match_calls += 1
        return original_matcher(member, key)

    monkeypatch.setattr(
        timewarp,
        "_ultimate_package_member_axis_matches_key",
        counted_matcher,
    )
    timewarp._cached_ultimate_package_member_axis_matches.cache_clear()
    timewarp._ULTIMATE_PACKAGE_MEMBER_AXIS_ROW_SNAPSHOTS.clear()
    candidate = {
        "candidate_id": "member-axis-cache-candidate",
        "symbol": "XAUUSD",
        "side": "LONG",
    }

    first = timewarp.ultimate_package_member_axis_parity_fields(candidate)
    second = timewarp.ultimate_package_member_axis_parity_fields(dict(candidate))

    assert second == first
    assert first["ultimate_package_matched_member_axis_ids"] == [
        "member_axis:XAUUSD:LONG:cached"
    ]
    assert match_calls == len(rows)
    assert timewarp._cached_ultimate_package_member_axis_matches.cache_info().hits == 1


