def test_compact_risk_admitted_finalizer_preserves_reallocation_counters() -> None:
    payload = {
        "enabled": True,
        "status": "risk_admitted_selection_materialized",
        "reallocated": True,
        "probe_rows": [
            {
                "candidate_id": f"candidate-{idx}",
                "decision_time_utc": f"2026-04-21T08:0{idx}:00+00:00",
                "canonical_replay_candidate_instance_key": (
                    f"candidate-{idx}@@2026-04-21T08:0{idx}:00+00:00"
                ),
                "causal_finalizer_reallocation_candidate": True,
                "reallocation_terminal_disposition": (
                    "selected" if idx == 0 else "quality_blocked"
                ),
                "reallocation_terminal_disposition_reason": (
                    "selected" if idx == 0 else "unit_test_quality_floor"
                ),
                "selected": idx == 0,
                "status": "blocked",
            }
            for idx in range(4)
        ],
        "original_selected_candidate_ids": ["original"],
        "final_selected_candidate_ids": ["replacement"],
        "reallocation_candidate_probe_count": 4,
        "reallocation_admitted_candidate_probe_count": 2,
        "reallocation_policy_blocked_probe_count": 1,
        "reallocation_quality_blocked_probe_count": 1,
        "reallocation_selected_probe_count": 1,
        "reallocation_unadmitted_probe_count": 1,
        "reallocation_terminal_disposition_counts": {
            "selected": 1,
            "quality_blocked": 1,
            "policy_blocked": 1,
            "unadmitted": 1,
        },
        "reallocation_terminal_disposition_reconciled": True,
        "zero_trade_conversion_candidate_probe_count": 3,
        "zero_trade_conversion_policy_blocked_probe_count": 2,
        "zero_trade_conversion_selected_probe_count": 1,
    }

    compact = timewarp.compact_risk_admitted_finalizer(
        payload,
        probe_row_limit=1,
    )

    assert compact["payload_compacted_for_broad_replay"] is True
    assert compact["reallocation_candidate_probe_count"] == 4
    assert compact["reallocation_admitted_candidate_probe_count"] == 2
    assert compact["reallocation_policy_blocked_probe_count"] == 1
    assert compact["reallocation_quality_blocked_probe_count"] == 1
    assert compact["reallocation_selected_probe_count"] == 1
    assert compact["reallocation_unadmitted_probe_count"] == 1
    assert compact["reallocation_terminal_disposition_counts"] == {
        "selected": 1,
        "quality_blocked": 1,
        "policy_blocked": 1,
        "unadmitted": 1,
    }
    assert compact["reallocation_terminal_disposition_reconciled"] is True
    assert compact["zero_trade_conversion_candidate_probe_count"] == 3
    assert compact["zero_trade_conversion_policy_blocked_probe_count"] == 2
    assert compact["zero_trade_conversion_selected_probe_count"] == 1
    assert compact["reallocation_terminal_probe_row_count"] == 4
    assert len(compact["reallocation_terminal_probe_rows"]) == 4
    assert {
        row["canonical_replay_candidate_instance_key"]
        for row in compact["reallocation_terminal_probe_rows"]
    } == {
        f"candidate-{idx}@@2026-04-21T08:0{idx}:00+00:00"
        for idx in range(4)
    }


