def test_selector_reject_materializes_current_source_bound_order_authority() -> None:
    candidate, selector_packet, packets, runtime = (
        _v150_style_current_source_bound_off_config_surfaces()
    )

    detail = timewarp.selector_reject_open_reduced_materialization_detail(
        selector_packet=selector_packet,
        selector_action="reject",
        candidate=candidate,
        packets=packets,
        runtime=runtime,
    )

    assert detail["applied"] is True
    assert detail["authority_family"] == "off_session_softening"
    assert detail["package_replay_executable_candidate_use_allowed"] is True
    assert detail["package_replay_order_executable_candidate_use_allowed"] is True
    assert detail["package_replay_order_executable_authority_source"] == (
        "selector_reject_open_reduced_materialization_detail"
    )
    authority = detail["open_reduced_authority"]
