def test_missed_scheduler_attribution_marks_non_materialized_candidates() -> None:
    fields = timewarp.scheduler_missed_opportunity_attribution_fields(
        candidate={
            "candidate_id": "skip-before-scheduler",
            "decision_time_utc": "2026-05-13T00:15:00+00:00",
            "scheduler_materialization_skip_reason": "selector_not_risk_bearing",
            "scheduler_materialization_action_intent": "new_position",
            "fill_probability": 0.83,
            "predecision_limit_fillability": {
                "status": "materialized",
                "fill_probability": 0.29,
                "source_boundary": "asof_candidate_fields_only_no_postdecision_path",
                "current_price_source_time_utc": "2026-05-13T00:00:00+00:00",
            },
        },
        scheduler_option=None,
        selected_id_set=set(),
        original_selected_ids=[],
    )

    assert (
        fields["scheduler_selection_disposition"]
        == "candidate_materialization_skipped_before_scheduler"
    )
    assert fields["scheduler_option_status"] == "not_scheduler_materialized"
    assert (
        fields["scheduler_option_reason"]
        == "scheduler_materialization_skipped:selector_not_risk_bearing"
    )
    assert fields["scheduler_action_class"] == "new_position"
    assert fields["entry_quality_fill_probability"] == 0.83
    assert fields["predecision_limit_fillability_probability"] == 0.29
    assert fields["execution_fill_probability"] == 0.29
    assert fields["execution_fill_probability_source"] == (
        "predecision_limit_fillability.fill_probability"
    )
    assert fields["risk_expression_ladder_tier"] == "diagnostic"
    assert "selector_not_risk_bearing" in fields[
        "risk_expression_ladder_tier_causes"
    ]


