def test_risk_finalizer_selection_transfer_distinguishes_prune_from_reallocate() -> None:
    pruned = timewarp.risk_finalizer_selection_transfer_fields(
        ["first", "second"],
        ["second"],
        allow_reallocation=True,
    )

    assert pruned["selection_changed"] is True
    assert pruned["original_selected_set_pruned"] is True
    assert pruned["original_selected_pruned_candidate_ids"] == ["first"]
    assert pruned["rank_selected_within_original"] == 2
    assert pruned["final_selected_ranks_within_original"] == [2]
    assert pruned["final_selected_outside_original_candidate_ids"] == []
    assert pruned["true_reallocated_non_original"] is False
    assert pruned["reallocated"] is False

    reallocated = timewarp.risk_finalizer_selection_transfer_fields(
        ["first"],
        ["second"],
        allow_reallocation=True,
    )

    assert reallocated["selection_changed"] is True
    assert reallocated["original_selected_set_pruned"] is True
    assert reallocated["rank_selected_within_original"] is None
    assert reallocated["final_selected_outside_original_candidate_ids"] == ["second"]
    assert reallocated["true_reallocated_non_original"] is True
    assert reallocated["reallocated"] is True


