def test_package_authority_attribution_prefers_atomic_valid_surface() -> None:
    decision_time = "2026-05-13T00:15:00+00:00"
    candidate_id = "atomic-authority"
    row = {
        **_explicit_package_preflight(
            fill=0.93,
            candidate_id=candidate_id,
            decision_time_utc=decision_time,
        ),
        "candidate_id": candidate_id,
        "decision_time_utc": decision_time,
        "canonical_replay_candidate_instance_key": f"{candidate_id}@@{decision_time}",
        "source_bound_replay_candidate_instance_key": f"{candidate_id}@@{decision_time}",
        "candidate_instance_identity_status": "materialized",
    }
    valid_surface = stamp_package_new_entry_authority(
        row,
        selector_action="open-reduced-risk",
        selector_reason="unit_test_atomic_authority",
        authority={
            "applies": True,
            "allowed": True,
            "authority_family": "unit_test_atomic_authority",
            "source_boundary": (
                "predecision_package_open_reduced_new_entry_authority_no_outcome_fields"
            ),
        },
        action_intent="close_and_reverse",
    )
    invalid_surface = {
        **valid_surface,
        "package_new_entry_authority_valid": False,
        "package_new_entry_authority_status": (
            "invalid_or_missing_signed_new_entry_authority"
        ),
        "package_new_entry_authority_failures": ["authority_hash_mismatch"],
        "package_new_entry_authority_hash_sha256": "0" * 64,
    }

    fields = timewarp.package_new_entry_authority_attribution_fields(
        invalid_surface,
        valid_surface,
    )

    assert fields["package_new_entry_authority_valid"] is True
    assert fields["package_new_entry_authority_status"] == (
        "valid_signed_predecision_new_entry_authority"
    )
    assert fields["package_new_entry_authority_failures"] == []
    assert fields["package_new_entry_authority_hash_sha256"] == valid_surface[
        "package_new_entry_authority_hash_sha256"
    ]
    assert fields["expected_package_new_entry_authority_hash_sha256"] == (
        valid_surface["expected_package_new_entry_authority_hash_sha256"]
    )
    assert (
        fields["package_new_entry_authority_target_action_intent"]
        == "close_and_reverse"
    )
    assert fields["package_new_entry_authority_entry_quality_fill_probability"] == 0.93
    assert (
        fields["package_new_entry_authority_predecision_limit_fillability_probability"]
        == 0.93
    )
    assert fields["package_new_entry_authority_execution_fill_probability"] == 0.93


