def test_lifecycle_and_missed_terminal_attribution_helpers() -> None:
    lifecycle = timewarp.lifecycle_action_attribution_fields(
        candidate={
            "lifecycle_action": "new_position",
            "same_symbol_lifecycle_action": "new_position",
        },
        packets={"lifecycle_packet": {"action": "new_position"}},
        scheduler_option={
            "action_class": "same_direction_scale_in",
            "scheduler_candidate_decision_inputs": {
                "effective_action_intent": "same_direction_scale_in"
            },
        },
        risk_authority={"same_symbol_lifecycle_action": "same_direction_scale_in"},
    )
    terminal = timewarp.missed_opportunity_terminal_status_fields(
        oracle={"limit_first_fill_status": "filled_limit_first"},
        close_reason="target_hit",
    )

    assert lifecycle["lifecycle_action"] == "same_direction_scale_in"
    assert lifecycle["candidate_lifecycle_action"] == "new_position"
    assert lifecycle["scheduler_lifecycle_action"] == "same_direction_scale_in"
    assert lifecycle["risk_lifecycle_action"] == "same_direction_scale_in"
    assert terminal == {
        "fill_status": "not_sent_missed_opportunity",
        "fill_status_scope": "not_sent_missed_opportunity",
        "real_order_fill_status": None,
        "counterfactual_fill_status": "filled_limit_first",
        "counterfactual_order_fill_status": "filled_limit_first",
        "counterfactual_fill_status_scope": "counterfactual_missed_opportunity",
        "missed_counterfactual_fill_status": "filled_limit_first",
        "order_status": "not_sent_missed_opportunity",
        "terminal_outcome": "target_hit",
    }


