def test_compact_pretrade_cost_scalar_conflicts_do_not_override_broker_authority() -> None:
    packets = {
        "cost_r": 9.99,
        "pretrade_broker_net_cost_packet": {
            "status": "PASSED",
            "authority": "broker_calibrated_replay_cost",
            "cost_source_gap_status": "source_bound_cost_authority_present",
            "candidate_cost_r_fallback_is_authority": False,
            "scalar_fields": {
                "total_cost_r": 0.07,
                "status": "REFUSED",
                "refusal_reasons": ["spread_r_exceeds_selected_cell_limit"],
                "cost_source_gap_status": "SOURCE_GAP_COST_FALLBACK",
                "authority": "timewarp_candidate_cost_proxy",
                "candidate_cost_r_fallback_is_authority": True,
            },
        },
    }

    model = timewarp.broker_calibrated_pretrade_cost_model_for_execution(packets)
    fields = timewarp.pretrade_cost_attribution_fields(packets)
    block_reason = timewarp.replay_order_cost_authority_block_reason(
        packets,
        {
            "gtos_vnext_runtime": {
                "broad_live_as_if_replay_enforce_broker_cost_packet_status": True,
            },
            "broad_live_as_if_replay_harness": {
                "live_broker_authority": False,
                "broker_mutation_enabled": False,
                "final_selection_claim": False,
            },
        },
    )
    normalized = timewarp.normalized_pretrade_cost_packet_from_packets(packets)

    assert normalized["status"] == "PASSED"
    assert normalized["authority"] == "broker_calibrated_replay_cost"
    assert normalized["cost_source_gap_status"] == "source_bound_cost_authority_present"
    assert normalized["candidate_cost_r_fallback_is_authority"] is False
    assert normalized["scalar_conflict_status"] == "REFUSED"
    assert normalized["scalar_conflict_authority"] == "timewarp_candidate_cost_proxy"
    assert (
        normalized["scalar_conflict_cost_source_gap_status"]
        == "SOURCE_GAP_COST_FALLBACK"
    )
    assert normalized["scalar_conflict_candidate_cost_r_fallback_is_authority"] is True
    assert model["status"] == "PASSED"
    assert model["expected_total_cost_r"] == 0.07
    assert model["executable_cost_block_reason"] is None
    assert model["authority"] == "broker_calibrated_replay_cost"
    assert fields["broker_pretrade_cost_r"] == 0.07
    assert fields["broker_calibrated_expected_cost_r"] == 0.07
    assert fields["total_execution_cost_r"] == 0.07
    assert fields["broker_pretrade_cost_executable"] is True
    assert fields["broker_pretrade_cost_non_executable_diagnostic_expected_cost_r"] is None
    assert fields["execution_cost_authority"] == "broker_pretrade_cost_only"
    assert (
        fields["net_cost_scope"]
        == "broker_pretrade_plus_optional_fallback_surcharge_not_close_side_all_in"
    )
    assert fields["broker_pretrade_cost_executable_block_reason"] is None
    assert fields["cost_source_gap_status"] == "source_bound_cost_authority_present"
    assert fields["candidate_cost_r_fallback_is_authority"] is False
    assert block_reason is None


def test_refused_broker_cost_authority_is_not_overridden_by_scalar_pass() -> None:
    packets = {
        "pretrade_broker_net_cost_packet": {
            "status": "REFUSED",
            "authority": "broker_calibrated_replay_cost",
            "cost_source_gap_status": "source_bound_cost_authority_present",
            "candidate_cost_r_fallback_is_authority": False,
            "refusal_reasons": ["spread_r_exceeds_selected_cell_limit"],
            "scalar_fields": {
                "total_cost_r": 0.07,
                "status": "PASSED",
                "authority": "broker_calibrated_replay_cost",
                "cost_source_gap_status": "source_bound_cost_authority_present",
                "candidate_cost_r_fallback_is_authority": False,
            },
        },
    }

    normalized = timewarp.normalized_pretrade_cost_packet_from_packets(packets)
    model = timewarp.broker_calibrated_pretrade_cost_model_for_execution(packets)
    block_reason = timewarp.replay_order_cost_authority_block_reason(
        packets,
        {
            "gtos_vnext_runtime": {
                "broad_live_as_if_replay_enforce_broker_cost_packet_status": True,
            },
            "broad_live_as_if_replay_harness": {
                "live_broker_authority": False,
                "broker_mutation_enabled": False,
                "final_selection_claim": False,
            },
        },
    )

    assert normalized["status"] == "REFUSED"
    assert normalized["scalar_conflict_status"] == "PASSED"
    assert model["status"] == "REFUSED"
    assert model["expected_total_cost_r"] == 0.0
    assert model["executable_cost_block_reason"] == (
        "broker_cost_packet_refused:spread_r_exceeds_selected_cell_limit"
    )
    assert block_reason == "broker_cost_packet_refused:spread_r_exceeds_selected_cell_limit"


