def test_pending_snapshot_strips_future_terminal_fields_defensively() -> None:
    account = AccountState()
    account.pending_orders["order-1"] = {
        "simulated_order_id": "order-1",
        "candidate_id": "candidate-1",
        "created_time_utc": "2026-04-21T08:00:00+00:00",
        "order_status": "pending_accepted",
        "side": "LONG",
        "entry_price": 100.0,
        "risk_pct": 0.25,
        "fill_status": "filled",
        "fill_time_utc": "2026-04-21T08:03:00+00:00",
        "fill_price": 100.1,
        "entry_fill_executable": True,
        "entry_fill_authority_status": "passive_queue_confirmed_entry_fill",
        "fill_realism_class": "passive_queue_confirmed",
        "passive_limit_queue_touch_count": 2,
        "terminal_r_scoreable": False,
        "terminal_r_scoreability_status": (
            "entry_fill_executable_terminal_r_ordered_tick_sequence_required"
        ),
        "terminal_outcome": "target_reached_before_stop",
        "final_r": 2.0,
        "gross_r": 2.0,
        "net_proxy_r": 1.9,
        "pnl_cash": 190.0,
        "profit_harvest_mfe_capture_replay_exit_status": "future_outcome",
    }

    rows = account.pending_snapshot(parse_utc("2026-04-21T08:01:00+00:00"))

    assert len(rows) == 1
    row = rows[0]
    assert row["future_oracle_fields_stripped_for_asof_pending_snapshot"] is True
    assert row["order_status"] == "pending_accepted"
    assert row["is_terminal_order_event"] is False
    assert row["terminal_resolution_required"] is True
    assert row["terminal_resolution_status"] == "pending_terminal_resolution_required"
    assert row["terminal_resolution_order_id"] is None
    assert row["pending_snapshot_outcome_field_sanitizer_version"] == (
        "v3_no_future_entry_fill_terminal_r_or_outcome_fields"
    )
    forbidden = {
        "fill_status",
        "fill_time_utc",
        "fill_price",
        "entry_fill_executable",
        "entry_fill_authority_status",
        "fill_realism_class",
        "passive_limit_queue_touch_count",
        "terminal_r_scoreable",
        "terminal_r_scoreability_status",
        "terminal_outcome",
        "final_r",
        "gross_r",
        "net_proxy_r",
        "pnl_cash",
        "profit_harvest_mfe_capture_replay_exit_status",
    }
    assert forbidden.isdisjoint(row)


def test_account_row_keeps_final_r_and_net_proxy_r_separate() -> None:
    account = AccountState()

    row = timewarp.account_row(
        campaign="unit",
        phase="repair",
        day="2026-04-21",
        event="trade_close",
        account=account,
        candidate_id="candidate-gross-net",
        order_id="order-gross-net",
        trade_id="trade-gross-net",
        pnl_cash=82.0,
        final_r=1.00,
        net_proxy_r=0.82,
        gross_r=1.00,
        expected_cost_r=0.18,
        risk_cash=100.0,
        risk_authority={"risk_per_trade_pct": 0.10},
    )

    assert row["final_r"] == 1.00
    assert row["gross_r"] == 1.00
    assert row["expected_cost_r"] == 0.18
    assert row["net_proxy_r"] == 0.82
    assert row["final_r"] != row["net_proxy_r"]
    assert round(row["gross_r"] - row["expected_cost_r"], 8) == row["net_proxy_r"]
    assert row["pnl_cash"] == 82.0


