def test_replay_order_policy_blocks_zero_duration_expiry() -> None:
    asof = parse_utc("2026-04-21T23:59:00+00:00")
    assert asof is not None

    assert (
        timewarp.replay_order_policy_expiry_block_reason(asof=asof, expiry=asof)
        == "zero_duration_expiry_order_policy_block"
    )
    assert (
        timewarp.replay_order_policy_expiry_block_reason(
            asof=asof,
            expiry=asof - timedelta(minutes=1),
        )
        == "zero_duration_expiry_order_policy_block"
    )
    assert (
        timewarp.replay_order_policy_expiry_block_reason(
            asof=asof,
            expiry=asof + timedelta(minutes=1),
        )
        is None
    )


