def test_guarded_fallback_cost_updates_nested_scheduler_quality_inputs() -> None:
    scheduler_option = {
        "expected_cost_r": 0.0458,
        "candidate_expected_net_r": 0.7542,
        "score_components": {
            "candidate_decision_inputs": {
                "decision_time_utc": "2026-05-13T10:00:00+00:00",
                "probability": 0.74,
                "ev_r": 0.80,
                "cost_total_r": 0.0458,
                "expected_cost_r": 0.0458,
                "candidate_expected_net_r": 0.7542,
                "fill_probability": 0.92,
                "predecision_limit_fillability_probability": 0.92,
                "execution_fill_probability_source_time_utc": (
                    "2026-05-13T09:45:00+00:00"
                ),
                "execution_fill_probability_source_boundary": (
                    "asof_candidate_fields_only_no_postdecision_path"
                ),
                "source_completeness": 1.0,
            }
        },
    }

    adjusted = timewarp.scheduler_option_with_guarded_fallback_cost(
        scheduler_option,
        fallback_result={
            "applied": True,
            "broker_pretrade_cost_r": 0.0458,
            "fallback_execution_surcharge_r": 0.05,
            "total_execution_cost_r": 0.0958,
            "expected_cost_r": 0.0958,
        },
    )

    assert adjusted is not scheduler_option
    inputs = adjusted["score_components"]["candidate_decision_inputs"]
    assert inputs["cost_total_r"] == 0.0958
    assert inputs["expected_cost_r"] == 0.0958
    assert inputs["fallback_execution_surcharge_r"] == 0.05
    assert inputs["candidate_expected_net_r"] == 0.7042
    assert adjusted["candidate_expected_net_r"] == 0.7042
    assert (
        adjusted["scheduler_candidate_decision_inputs_cost_adjustment_status"]
        == "guarded_market_fallback_execution_surcharge_applied"
    )
    assert scheduler_option["score_components"]["candidate_decision_inputs"][
        "cost_total_r"
    ] == 0.0458

    fields = timewarp.candidate_execution_quality_attribution_fields(
        candidate={
            "candidate_id": "candidate-fallback-parity",
            "decision_time_utc": "2026-05-13T10:00:00+00:00",
            "symbol": "EURUSD",
            "side": "LONG",
            "candidate_probability": 0.74,
            "candidate_ev_r": 0.80,
            "expected_cost_r": 0.0958,
            "source_window_complete": True,
            "predecision_limit_fillability": {
                "fill_probability": 0.92,
                "current_price_source_time_utc": "2026-05-13T09:45:00+00:00",
                "source_boundary": "asof_candidate_fields_only_no_postdecision_path",
            },
        },
        packets={
            "candidate_probability": 0.74,
            "candidate_ev_r": 0.80,
            "cost_r": 0.0958,
            "expected_cost_r": 0.0958,
            "broker_calibrated_expected_cost_r": 0.0458,
            "broker_pretrade_cost_r": 0.0458,
            "fallback_execution_surcharge_r": 0.05,
            "total_execution_cost_r": 0.0958,
            "pretrade_broker_net_cost_packet": {
                "total_cost_r": 0.0458,
                "status": "PASSED",
                "authority": "broker_calibrated_replay_cost",
                "cost_source_gap_status": "source_bound_cost_authority_present",
                "candidate_cost_r_fallback_is_authority": False,
            },
            "selector_packet": {},
        },
        scheduler_option=adjusted,
    )

    assert fields["expected_cost_r"] == 0.0958
    assert fields["candidate_expected_net_r"] == 0.7042
