def test_selected_scheduler_option_requires_exact_candidate_time_when_supplied() -> None:
    scheduler_packet = {
        "asof_utc": "2026-05-14T00:30:00+00:00",
        "decision": {
            "selected_options": [
                {
                    "candidate_id": "candidate-1",
                    "decision_time_utc": "2026-05-14T00:00:00+00:00",
                    "source_type": "stale-selected-option",
                    "score_components": {
                        "pending_replacement_diagnostic": {
                            "replacement_applied": True,
                            "pending_replacement_causal_quality_gate_status": "passed",
                            "release_pending_ids": ["stale-order"],
                            "runtime_replacement_applied": True,
                            "runtime_release_pending_ids": ["stale-order"],
                        }
                    },
                },
                {
                    "candidate_id": "candidate-1",
                    "decision_time_utc": "2026-05-14T00:30:00+00:00",
                    "source_type": "exact-selected-option",
                    "score_components": {
                        "pending_replacement_diagnostic": {
                            "replacement_applied": True,
                            "pending_replacement_causal_quality_gate_status": "passed",
                            "release_pending_ids": ["exact-order"],
                            "runtime_replacement_applied": True,
                            "runtime_release_pending_ids": ["exact-order"],
                        }
                    },
                },
            ]
        },
    }

    assert (
        timewarp.selected_scheduler_option(
            scheduler_packet,
            "candidate-1",
            decision_time_utc="2026-05-14T00:30:00+00:00",
        )["source_type"]
        == "exact-selected-option"
    )
    assert (
        timewarp.selected_scheduler_replacement_pending_ids(
            scheduler_packet,
            "candidate-1",
            decision_time_utc="2026-05-14T00:30:00+00:00",
        )
        == ["exact-order"]
    )
    assert (
        timewarp.selected_scheduler_option(
            scheduler_packet,
            "candidate-1",
            decision_time_utc="2026-05-14T01:00:00+00:00",
        )
        == {}
    )
    nested_time_packet = {
        "asof_utc": "2026-05-14T00:30:00+00:00",
        "decision": {
            "selected_options": [
                {
                    "candidate_id": "candidate-1",
                    "source_type": "nested-time-selected-option",
                    "score_components": {
                        "candidate_decision_inputs": {
                            "decision_time_utc": "2026-05-14T00:45:00+00:00",
                            "expected_net_r": 1.25,
                        }
                    },
                }
            ]
        },
        "all_options_preserved": [
            {
                "candidate_id": "candidate-1",
                "source_type": "stale-top-level-time-option",
                "decision_time_utc": "2026-05-14T00:30:00+00:00",
            }
        ],
    }
    assert (
        timewarp.selected_scheduler_option(
            nested_time_packet,
            "candidate-1",
            decision_time_utc="2026-05-14T00:45:00+00:00",
        )["source_type"]
        == "nested-time-selected-option"
    )
    assert (
        timewarp.selected_scheduler_option(
            nested_time_packet,
            "candidate-1",
            decision_time_utc="2026-05-14T01:00:00+00:00",
        )
        == {}
    )
    missing_time_packet = {
        "asof_utc": "2026-05-14T00:30:00+00:00",
        "decision": {
            "selected_options": [
                {
                    "candidate_id": "candidate-1",
                    "source_type": "missing-time-selected-option",
                }
            ]
        },
    }
    assert (
        timewarp.selected_scheduler_option(
            missing_time_packet,
            "candidate-1",
            decision_time_utc="2026-05-14T00:30:00+00:00",
        )
        == {}
    )


