def test_broker_calibrated_replay_cost_preserves_raw_historical_tick_below_static_floor() -> None:
    candidate = {
        "candidate_id": "cost-authority-usdjpy",
        "symbol": "USDJPY",
        "side": "SHORT",
        "entry_price": 157.67,
        "stop_loss": 157.8053,
    }

    tick, metadata = timewarp._broker_cost_tick_from_row(
        {
            "time_utc": "2026-05-13T04:29:58.805000+00:00",
            "bid": 157.661,
            "ask": 157.67,
        },
        candidate=candidate,
        asof_utc="2026-05-13T04:30:00+00:00",
        spread_floor_r=0.0841,
    )

    raw_spread_r = (157.67 - 157.661) / abs(157.67 - 157.8053)
    assert tick["bid"] == pytest.approx(157.661)
    assert tick["ask"] == pytest.approx(157.67)
    assert metadata["quote_source"] == "historical_ftmo_predecision_tick"
    assert metadata["historical_tick_spread_r"] == pytest.approx(raw_spread_r)
    assert metadata["measured_tick_spread_floor_r"] == pytest.approx(0.0841)
    assert metadata["measured_tick_spread_floor_enforced"] is False
    assert metadata["measured_tick_spread_floor_used_as_quote_substitute"] is False


