def test_build_source_package_requests_history_through_replay_day(monkeypatch) -> None:
    history_calls: list[dict] = []

    def fake_history_source(symbol, timeframe, *, min_total_rows, start_utc=None, end_utc=None):
        history_calls.append(
            {
                "symbol": symbol,
                "timeframe": timeframe,
                "start_utc": start_utc,
                "end_utc": end_utc,
                "min_total_rows": min_total_rows,
            }
        )
        return None, (f"{symbol}_{timeframe}:source_gap",)

    def fake_m1_source(
        symbol,
        timeframe,
        days,
        *,
        min_rows_per_day,
        verified_no_session_days=(),
    ):
        return None, (f"{symbol}_{timeframe}:source_gap",)

    monkeypatch.setattr(timewarp, "resolve_ftmo_history_source", fake_history_source)
    monkeypatch.setattr(timewarp, "resolve_ftmo_source", fake_m1_source)
    monkeypatch.setattr(timewarp, "resolve_ftmo_tick_source", lambda symbol: (None, ()))

    package = timewarp.build_source_package(("2026-05-04",))

    assert package["requested_history_end_utc"] == "2026-05-05"
    assert package["requested_replay_days"] == ["2026-05-04"]
    assert history_calls
    assert {call["end_utc"] for call in history_calls} == {"2026-05-05"}
    assert {call["timeframe"] for call in history_calls} == {"D1", "H4", "H1", "M15"}
    assert package["primary_hydration_complete"] is False
    assert package["missing_symbols"] == sorted(GTOS_24_SYMBOL_SURFACE)
    primary_blockers = [
        row
        for row in package["ftmo_blocker_rows"]
        if row.get("blocker_type") == "ftmo_primary_hydration_source_gap"
    ]
    assert primary_blockers
    assert all(
        row["requested_history_end_utc"] == "2026-05-05"
        for row in primary_blockers
    )


