def test_history_source_rejects_manifest_ending_before_requested_horizon(
    monkeypatch, tmp_path: Path
) -> None:
    csv_path = tmp_path / "XAUUSD_M15.csv"
    csv_path.write_text("time,open,high,low,close,volume\n", encoding="utf-8")
    spec = SourceSpec(
        symbol="XAUUSD",
        mapped_symbol="XAUUSD",
        timeframe="M15",
        path=csv_path,
        source_family="ftmo_mt5_research_export",
        source_broker="FTMO",
        source_role="owner_authorized_research_hydration",
        start_utc="2026-03-01T00:00:00+00:00",
        end_utc="2026-05-01T00:00:00+00:00",
        row_count=4,
        sha256="a" * 64,
        export_tool="scripts/export_mt5_research_ohlcv.py",
        manifest_path=str(tmp_path / "manifest.json"),
        source_server_hash="b" * 64,
        source_account_hash="c" * 64,
        source_truth_scope=SOURCE_TRUTH_SCOPE,
        not_redacted_account_native=True,
    )
    rows = tuple(
        {
            "time": f"2026-04-30 0{hour}:00:00",
            "open": 1.0,
            "high": 1.1,
            "low": 0.9,
            "close": 1.0,
            "volume": 1,
        }
        for hour in range(4)
    )
    monkeypatch.setattr(timewarp, "ftmo_source_specs", lambda symbol, timeframe: ((spec,), ()))
    monkeypatch.setattr(timewarp, "load_source_rows", lambda path, symbol, timeframe: rows)
    monkeypatch.setattr(timewarp, "file_sha256", lambda path: "a" * 64)

    stale_source, stale_gaps = resolve_ftmo_history_source(
        "XAUUSD",
        "M15",
        min_total_rows=1,
        end_utc="2026-05-05",
    )
    current_source, current_gaps = resolve_ftmo_history_source(
        "XAUUSD",
        "M15",
        min_total_rows=1,
        end_utc="2026-05-01",
    )

    assert stale_source is None
    assert any("before_requested_2026-05-05T00:00:00+00:00" in gap for gap in stale_gaps)
    assert current_source is not None
    assert current_gaps == ()


def test_tick_source_resolver_accepts_manifest_jsonl_path_with_gzip_payload(
    tmp_path: Path,
) -> None:
    export_dir = tmp_path / "data/mt5_research_exports/bridge_ftmo_ticks_micro_test"
    tick_path = export_dir / "ticks/XAUUSD/microstructure_ticks.jsonl"
    tick_gz_path = Path(f"{tick_path}.gz")
    tick_gz_path.parent.mkdir(parents=True, exist_ok=True)
    rows = [
        {
            "time_utc": "2026-05-13T00:00:01+00:00",
            "bid": 100.0,
            "ask": 100.1,
            "volume": 1,
        },
        {
            "time_utc": "2026-05-13T00:01:01+00:00",
            "bid": 100.2,
            "ask": 100.3,
            "volume": 1,
        },
    ]
    with gzip.open(tick_gz_path, "wt", encoding="utf-8") as handle:
        for row in rows:
            handle.write(json.dumps(row, sort_keys=True) + "\n")
    manifest = {
        "files": {
            "XAUUSD_TICK": {
                "file_symbol": "XAUUSD",
                "mt5_symbol": "XAUUSD",
                "timeframe": "TICK",
                "path": (
                    "data/mt5_research_exports/bridge_ftmo_ticks_micro_test/"
                    "ticks/XAUUSD/microstructure_ticks.jsonl"
                ),
                "row_count": 2,
                "sha256": file_sha256(tick_gz_path),
                "source_broker": "FTMO",
                "source_role": "owner_authorized_research_hydration",
                "source_truth_scope": SOURCE_TRUTH_SCOPE,
                "not_redacted_account_native": True,
                "source_server_hash": "b" * 64,
                "source_account_hash": "c" * 64,
                "request_start_utc": "2026-05-13T00:00:00+00:00",
                "request_end_utc": "2026-05-13T00:02:00+00:00",
                "export_tool": "scripts/export_mt5_research_ticks.py",
            }
        }
    }
    write_json(export_dir / "manifest.json", manifest)

    specs, gaps = timewarp.ftmo_source_specs("XAUUSD", "TICK", repo_root=tmp_path)
    source, source_gaps = timewarp.resolve_ftmo_tick_source(
        "XAUUSD",
        repo_root=tmp_path,
    )

    assert gaps == ()
    assert len(specs) == 1
    assert specs[0].path == tick_gz_path
    assert source is not None
    assert source_gaps == ()
    assert source.spec.ordered_tick_truth_satisfied is True
    tick_rows = source.rows_by_day.get("2026-05-13")
    assert len(tick_rows) == 2
    assert tick_rows[0]["symbol"] == "XAUUSD"


