    assert position["terminal_lifecycle_close_expected_cost_r"] == 0.05
    assert position["terminal_lifecycle_close_net_proxy_r"] == 1.75
    assert position["terminal_lifecycle_close_mark_time_utc"] == (
        "2026-04-21T13:15:00+00:00"
    )
    assert position["terminal_lifecycle_close_mark_price"] == 2299.2
    assert position["terminal_lifecycle_close_mark_price_source"] == "tick_ask"
    assert position["terminal_lifecycle_close_mark_quote_side"] == "ask"
    assert position["terminal_lifecycle_close_mark_executable_quote_side"] is True
    assert position["terminal_lifecycle_close_r_path_authority"] == (
        "ordered_tick_truth_terminal_lifecycle_close_r_authority"
    )

    ledgers = account.mutate_open_exposure_for_scheduler_terminal_lifecycle(
        exposure_ids=["trade-short"],
        asof=parse_utc("2026-04-21T13:15:00+00:00"),
        campaign=CampaignConfig(
            name="unit",
            phase="test",
            days=("2026-04-21",),
            pending_expiry_minutes=60,
            use_repaired_pending_expiry=True,
        ),
        day="2026-04-21",
        scheduler_action="close_and_reverse",
        risk_delta_pct=-0.5,
        scheduler_packet_hash="packet-hash",
        reverse_order_context={
            "reverse_candidate_id": "candidate-long",
            "reverse_simulated_order_id": "order-long",
            "reverse_decision_time_utc": "2026-04-21T13:15:00+00:00",
            "reverse_action_intent": "close_and_reverse",
        },
    )

    assert "trade-short" not in account.open_positions
    assert ledgers["event"][0]["terminal_lifecycle_commit_status"] == (
        "committed_scheduler_close_and_reverse_closed_existing"
    )
