def test_pending_expiry_releases_accepted_risk_reservation() -> None:
    account = AccountState()
    candidate_instance_key = (
        "candidate-expire@@2026-04-21T14:00:00+00:00"
    )
    account.record_accepted_risk_order(
        "2026-04-21",
        0.75,
        session_key="ny",
        decision_time_key="2026-04-21T14:00:00+00:00",
    )
    account.pending_orders["order-expire"] = {
        "simulated_order_id": "order-expire",
        "candidate_id": "candidate-expire",
        "canonical_replay_candidate_instance_key": candidate_instance_key,
        "decision_time_utc": "2026-04-21T14:00:00+00:00",
        "symbol": "EURUSD",
        "side": "SHORT",
        "entry_price": 1.08,
        "risk_pct": 0.75,
        "reserved_risk_pct": 0.75,
        "risk_cash": 750.0,
        "risk_authority": {
            "opening_window_session_counter_key": "ny",
            "decision_time_risk_order_counter_key": "2026-04-21T14:00:00+00:00",
        },
    }
    account.queue_event(
        parse_utc("2026-04-21T15:00:00+00:00"),
        "expire_order",
        {
            "simulated_order_id": "order-expire",
            "event_metadata": {"pending_expiry_minutes": 60},
        },
    )
    campaign = CampaignConfig(
        name="kiap_unit",
        phase="unit",
        days=("2026-04-21",),
        pending_expiry_minutes=60,
        use_repaired_pending_expiry=True,
    )

    ledgers = account.process_events_until(
        until=parse_utc("2026-04-21T15:00:00+00:00"),
        campaign=campaign,
        day="2026-04-21",
    )

    assert account.pending_orders == {}
    assert ledgers["order"][0]["order_status"] == "expired_unfilled"
    assert ledgers["order"][0]["order_snapshot_type"] == "expired_order_event"
    assert ledgers["order"][0]["order_event_stage"] == "terminal_expired_unfilled"
    assert ledgers["order"][0]["fill_status"] == "not_filled_expired_unfilled"
    assert ledgers["order"][0]["simulated_order_id"] == "order-expire"
    assert ledgers["order"][0][
        "canonical_replay_candidate_instance_key"
    ] == candidate_instance_key
    assert ledgers["order"][0]["accepted_risk_reservation_released"] is True
    assert ledgers["event"][0]["released_risk_pct"] == 0.75
    assert ledgers.get("missed", []) == []
    assert account.accepted_risk_order_count("2026-04-21") == 0
    assert account.accepted_risk_pct("2026-04-21") == 0.0
    assert account.accepted_risk_order_count("2026-04-21", session_key="ny") == 0
    assert account.accepted_risk_pct("2026-04-21", session_key="ny") == 0.0
    assert (
        account.accepted_risk_order_count_for_decision_time(
            "2026-04-21",
            "2026-04-21T14:00:00+00:00",
        )
        == 0
    )
    assert (
        account.accepted_risk_pct_for_decision_time(
            "2026-04-21",
            "2026-04-21T14:00:00+00:00",
        )
        == 0.0
    )


