def test_factorial_scoreable_close_releases_filled_risk_exactly_once() -> None:
    account = AccountState()
    day = "2026-04-21"
    decision_time = "2026-04-21T14:00:00+00:00"
    risk_pct = 0.625
    account.record_accepted_risk_order(
        day,
        risk_pct,
        session_key="ny",
        decision_time_key=decision_time,
        decision_cluster_key="metals",
        decision_side="LONG",
    )
    account.pending_orders["factorial-order"] = {
        "simulated_order_id": "factorial-order",
        "accepted_risk_reservation_day": day,
        "trading_day": day,
        "candidate_id": "factorial-candidate",
        "symbol": "XAUUSD",
        "side": "LONG",
        "decision_time_utc": decision_time,
        "entry_price": 2400.0,
        "risk_pct": risk_pct,
        "reserved_risk_pct": risk_pct,
        "risk_cash": 625.0,
        "order_status": "pending_accepted",
        "order_snapshot_type": "accepted_pending_asof",
        "order_event_stage": "accepted_pending",
        "order_intent_materialized": True,
        "risk_authority": {
            "opening_window_session_counter_key": "ny",
            "decision_time_risk_order_counter_key": decision_time,
            "same_decision_cluster_side_risk_order_cluster": "metals",
            "same_decision_cluster_side_risk_order_side": "LONG",
            "b7_5_selection_sizing_factorial_binding": {
                "enabled": True,
                "valid": True,
                "arm_id": "S1R1",
                "matched_risk": {
                    "expiry_or_close_release_once": True,
                },
            },
        },
    }
    account.queue_event(
        parse_utc("2026-04-21T14:05:00+00:00"),
        "fill_order",
        {
            "simulated_order_id": "factorial-order",
            "simulated_trade_id": "factorial-trade",
            "fill_price": 2400.0,
            "event_metadata": {},
        },
    )
    account.queue_event(
        parse_utc("2026-04-21T14:35:00+00:00"),
        "close_trade",
        {
            "simulated_trade_id": "factorial-trade",
            "final_r": 1.0,
            "expected_cost_r": 0.1,
            "net_proxy_r": 0.9,
            "close_reason": "target_reached",
        },
    )
    campaign = CampaignConfig(
        name="factorial_unit",
        phase="unit",
        days=(day,),
        pending_expiry_minutes=60,
        use_repaired_pending_expiry=True,
    )

    ledgers = account.process_events_until(
        until=parse_utc("2026-04-21T14:35:00+00:00"),
        campaign=campaign,
        day=day,
    )

    assert ledgers["order"][0]["order_event_stage"] == "terminal_filled"
    assert ledgers["order"][0]["accepted_risk_reservation_released"] is False
    trade = ledgers["trade"][0]
    assert trade["accepted_risk_reservation_released"] is True
    assert trade["accepted_risk_released_pct"] == risk_pct
    assert trade["accepted_risk_close_release_once_status"] == (
        "released_exactly_once_at_terminal_close"
    )
    assert trade["accepted_risk_reservation_release"][
        "day_accepted_risk_pct_before_release"
    ] == risk_pct
    assert trade["accepted_risk_reservation_release"][
        "day_accepted_risk_pct_after_release"
    ] == 0.0
    assert trade["accepted_risk_reservation_release"][
        "accepted_risk_exact_release_required"
    ] is True
    assert trade["accepted_risk_reservation_release"][
        "accepted_risk_reservation_day"
    ] == day
    assert account.closed_trades[0]["accepted_risk_reservation_released"] is True
    assert account.accepted_risk_order_count(day) == 0
    assert account.accepted_risk_pct(day) == 0.0
    assert account.accepted_risk_order_count(day, session_key="ny") == 0
    assert account.accepted_risk_pct(day, session_key="ny") == 0.0
    assert account.open_positions == {}


