def test_dynamic_policy_router_consumes_segment_policy_table(tmp_path: Path) -> None:
    table_path = tmp_path / "segment_table.json"
    table_path.write_text(
        json.dumps(
            {
                "schema_version": "exit_policy_segment_table_v1",
                "default_policy": {
                    "policy_id": "incumbent",
                    "family": "momentum",
                    "params": {"final_target_r": 2.0},
                },
                "segments": [
                    {
                        "segment_id": "leaf|jpy_fx|liquidity_sweep_reclaim|tokyo",
                        "match": {
                            "asset_class": "jpy_fx",
                            "origin_family": "liquidity_sweep_reclaim",
                            "session_bucket": "tokyo",
                        },
                        "fallback_level": "leaf",
                        "policy_id": "trailing_t1_g05",
                        "family": "trailing",
                        "params": {
                            "final_target_r": 3.0,
                            "trailing_trigger_r": 1.0,
                            "trailing_gap_r": 0.5,
                        },
                        "params_fidelity": "exact_params_required",
                        "promoted": True,
                        "n_trades": 50,
                        "n_days": 8,
                        "robust_score": 1.0,
                        "incumbent_delta_r_per_trade": 0.5,
                        "corrected_p": 0.01,
                        "reasons": [],
                    }
                ],
            },
            sort_keys=True,
        ),
        encoding="utf-8",
    )

    record = timewarp.dynamic_policy_router_record(
        candidate={
            "candidate_id": "candidate-segment-trailing",
            "symbol": "USDJPY",
            "side": "LONG",
            "origin_family": "liquidity_sweep_reclaim",
            "route_session": "tokyo",
            "session_bucket": "tokyo",
            "decision_time_utc": "2026-04-21T00:00:00+00:00",
            "source_fields": {"open": 100.0, "close": 101.0, "atr14": 1.0},
        },
        config={
            "gtos_vnext_runtime": {
                "moonshot_dynamic_execution_router_enabled": True,
                "moonshot_dynamic_execution_router_apply_to_execution": True,
                "moonshot_dynamic_execution_router_condition_challenger_enabled": True,
                "moonshot_dynamic_execution_router_condition_challenger_policy": (
                    "condition_asof_displacement_v1"
                ),
                "moonshot_dynamic_execution_router_segment_policy_table_path": str(
                    table_path
                ),
                "moonshot_dynamic_execution_router_segment_policy_params_consumer_ready": True,
            }
        },
        risk_pct=0.25,
    )

    segment = record["route_dimensions"]["segment_exit_policy"]
    assert record["selected_policy"] == "trailing_runner"
    assert segment["applied"] is True
    assert segment["selected_policy_params"]["trailing_gap_r"] == 0.5
    assert record["broker_operation"] is False


