def test_selected_execution_policy_replay_applies_trailing_policy() -> None:
    oracle = {
        "fill_status": "filled_from_ordered_m1_path",
        "fill_time_utc": "2026-04-21T00:00:00+00:00",
        "source": "m1",
        "target_r": 3.0,
    }

    final_r, reason, target_r, replay = timewarp.apply_selected_execution_policy_replay_exit(
        oracle=oracle,
        rows=[
            {
                "time_utc": "2026-04-21T00:01:00+00:00",
                "open": 100.0,
                "high": 101.2,
                "low": 100.8,
                "close": 101.0,
            },
            {
                "time_utc": "2026-04-21T00:02:00+00:00",
                "open": 101.0,
                "high": 101.3,
                "low": 100.4,
                "close": 100.5,
            },
        ],
        candidate={
            "candidate_id": "candidate-trailing",
            "side": "LONG",
            "entry_price": 100.0,
            "stop_loss": 99.0,
            "dynamic_geometry_policy": "trailing_runner",
            "expected_net_r": 0.8,
            "selected_policy_expected_net_calibration_status": (
                "selected_policy_expected_net_calibrated"
            ),
            "selected_policy_expected_net_calibrated": True,
            "selected_policy_expected_net_calibration_required": True,
            "selected_policy_expected_net_calibration_source": (
                "selected_policy_expected_net_r_model"
            ),
            "selected_policy_expected_net_calibration_source_boundary": (
                "predecision_selected_policy_expected_net_r_no_outcome_fields"
            ),
        },
        packets={
            "geometry_contract": {
                "selected_policy": "trailing_runner",
                "target_destination": {
                    "final_target_r": 3.0,
                    "trigger_r": 1.0,
                    "trail_gap_r": 0.5,
                },
            }
        },
        final_r=-1.0,
        close_reason="stop_reached_before_target",
        target_r=3.0,
    )

    assert final_r == -1.0
    assert reason == "stop_reached_before_target"
    assert target_r == 3.0
    assert replay["final_r"] == 0.7
    assert replay["raw_selected_policy_replay_final_r_authority"] is True
    assert replay["final_r_authority"] is False
    assert replay["final_r_authority_status"] == (
        "selected_policy_replay_not_authoritative:path_source_not_ordered_tick_truth:m1"
    )
    assert oracle["selected_execution_policy_replay_bound"] is False


