def test_terminal_unscoreable_selected_policy_emits_fail_closed_diagnostic_envelope() -> None:
    terminal_status = (
        "entry_fill_executable_terminal_r_ordered_tick_sequence_required"
    )
    terminal_reason = "ordered_tick_required_for_adverse_before_profit_sequence"
    oracle = {
        "fill_status": "filled_from_ordered_m1_path",
        "fill_time_utc": "2026-04-21T08:00:00+00:00",
        "entry_fill_executable": True,
        "terminal_r_scoreable": False,
        "terminal_r_scoreability_status": terminal_status,
        "terminal_r_scoreability_reason": terminal_reason,
        "source": "m1",
    }

    final_r, reason, target_r, replay = (
        timewarp.apply_selected_execution_policy_replay_exit(
            oracle=oracle,
            rows=[
                {
                    "time_utc": "2026-04-21T08:01:00+00:00",
                    "open": 100.0,
                    "high": 101.3,
                    "low": 101.0,
                    "close": 101.2,
                },
                {
                    "time_utc": "2026-04-21T08:02:00+00:00",
                    "open": 101.2,
                    "high": 101.35,
                    "low": 100.8,
                    "close": 100.9,
                },
            ],
            candidate={
                "candidate_id": "candidate-momentum-unscoreable",
                "side": "LONG",
                "entry_price": 100.0,
                "stop_loss": 99.0,
                "dynamic_geometry_policy": "momentum_exhaustion",
                "expected_net_r": 0.9,
                "selected_policy_expected_net_calibration_status": (
                    "selected_policy_expected_net_calibrated"
                ),
                "selected_policy_expected_net_calibrated": True,
                "selected_policy_expected_net_calibration_required": True,
                "selected_policy_expected_net_calibration_source": (
                    "selected_policy_expected_net_r_model"
                ),
                "selected_policy_expected_net_calibration_source_boundary": (
                    "predecision_selected_policy_expected_net_r_no_outcome_fields"
                ),
                "execution_fill_probability": 0.92,
                "predecision_limit_fillability_probability": 0.32,
                "predecision_stop_hazard_guard_pressure_score": 0.91,
                "predecision_stop_hazard_guard_pressure_triggered": True,
                "predecision_stop_hazard_guard_risk_cap_applied": False,
            },
            packets={
                "geometry_contract": {
                    "selected_policy": "momentum_exhaustion",
                    "target_destination": {
                        "trigger_r": 1.0,
                        "momentum_pullback_r": 0.4,
                        "final_target_r": 2.0,
                    },
                }
            },
            final_r=1.25,
            close_reason="stale_scoreable_terminal",
            target_r=2.0,
        )
    )

    authority_status = f"selected_policy_replay_not_authoritative:{terminal_status}"
    assert (final_r, reason, target_r) == (None, terminal_status, 2.0)
    assert replay is not None
    assert replay["selected_policy"] == "momentum_exhaustion"
    assert replay["selected_policy_supported"] is True
    assert replay["replay_status"] == "diagnostic_terminal_r_unscoreable"
    assert replay["replay_attempted"] is False
    assert replay["diagnostic_only"] is True
    assert replay["selected_policy_executable_quality_gate_status"] == "blocked"
    assert replay["observation_count"] == 0
    assert replay["final_r"] is None
    assert replay["raw_fixed_target_final_r"] is None
    assert replay["final_r_authority"] is False
    assert replay["ordered_tick_final_r_authority"] is False
    assert replay["m1_proxy_replay_authority"] is False
    assert replay["headline_result_authority"] is False
    assert replay["terminal_r_scoreability_status"] == terminal_status
    assert replay["terminal_r_scoreability_reason"] == terminal_reason
    assert replay["final_r_authority_status"] == authority_status
    assert oracle["selected_execution_policy_replay_exit"] == replay
    assert oracle["selected_execution_policy_replay_bound"] is False
    assert (
        oracle["selected_execution_policy_replay_final_r_authority_status"]
        == authority_status
    )

    metadata = {
        "selected_execution_policy_replay_exit": replay,
        **timewarp.selected_policy_replay_ledger_fields(replay),
        **timewarp.selected_execution_policy_alias_fields(
            order_policy={
                "selected_order_type_architecture": "limit_first",
                "replay_order_policy_hash_sha256": "selected-policy-hash",
            },
            selected_policy_replay_exit=replay,
            dynamic_geometry_policy="momentum_exhaustion",
        ),
    }
    terminal, order_event = (
        timewarp.split_selected_policy_replay_terminal_and_order_event_metadata(
            metadata,
            replay,
        )
    )
    for row in (terminal, order_event):
        assert row["selected_execution_policy_replay_exit"] == replay
        assert row["selected_execution_policy_replay_status"] == (
            "diagnostic_terminal_r_unscoreable"
        )
        assert row["selected_execution_policy_replay_bound"] is False
        assert row["selected_execution_policy_replay_final_r"] is None
        assert row[
            "selected_execution_policy_replay_final_r_authority_status"
        ] == authority_status
        assert row["selected_execution_policy_status"] == (
            "selected_execution_policy_replay_not_authoritative"
        )
        assert row["selected_execution_policy_exit_replay_status"] == (
            authority_status
        )
        assert row["selected_execution_policy_hash_sha256"] == (
            "selected-policy-hash"
        )


