def test_pending_replacement_verifier_rejects_cancel_before_admission(tmp_path: Path) -> None:
    route_dir = tmp_path
    write_jsonl(
        route_dir / "TIMEWARP_SIMULATED_ORDER_LEDGER.jsonl",
        [
            {
                "simulated_order_id": "order-old",
                "order_status": "cancelled_replaced_by_scheduler_v4",
                "replacement_simulated_order_id": "order-new",
                "cancel_before_replacement_admitted": False,
            },
            {
                "simulated_order_id": "order-new",
                "order_status": "risk_rejected",
            },
        ],
    )

    failed = timewarp.verify_pending_replacement_cancel_after_admission(route_dir)

    assert failed["status"] == "failed"
    assert failed["details"][0]["reason"] == "cancelled_before_admitted_replacement"

    write_jsonl(
        route_dir / "TIMEWARP_SIMULATED_ORDER_LEDGER.jsonl",
        [
            {
                "simulated_order_id": "order-old",
                "order_status": "cancelled_replaced_by_scheduler_v4",
                "replacement_simulated_order_id": "order-new",
                "cancel_before_replacement_admitted": False,
                "pending_replacement_causal_quality_gate_status": "passed",
            },
            {
                "simulated_order_id": "order-new",
                "order_status": "pending_accepted",
            },
        ],
    )
    passed = timewarp.verify_pending_replacement_cancel_after_admission(route_dir)

    assert passed["status"] == "passed"

    write_jsonl(
        route_dir / "TIMEWARP_SIMULATED_ORDER_LEDGER.jsonl",
        [
            {
                "simulated_order_id": "order-old",
                "order_status": "cancelled_replaced_by_scheduler_v4",
                "replacement_simulated_order_id": "order-new",
                "cancel_before_replacement_admitted": False,
            },
            {
                "simulated_order_id": "order-new",
                "order_status": "pending_accepted",
            },
        ],
    )
    missing_gate = timewarp.verify_pending_replacement_cancel_after_admission(route_dir)

    assert missing_gate["status"] == "failed"
    assert any(
        item["reason"] == "pending_replacement_causal_quality_gate_not_passed"
        for item in missing_gate["details"]
    )


def test_guarded_market_fallback_decision_requires_no_broker_boundary() -> None:
    candidate = {
        "candidate_id": "candidate-new",
        "symbol": "XAUUSD",
        "side": "LONG",
        "candle_close_utc": "2026-04-21T08:00:00+00:00",
    }
    packets = {
        "candidate_probability": 0.6,
        "candidate_ev_r": 0.2,
        "pretrade_broker_net_cost_packet": {
            "status": "PASSED",
            "authority": "broker_calibrated_replay_cost",
            "cost_source_gap_status": "source_bound_cost_authority_present",
            "total_cost_r": 0.05,
        },
    }
    scheduler_packet = {
        "ultimate_candidate_package_shadow": {
            "shadow_selected_candidate_id": "candidate-new",
            "execution_policy_shadow": {
                "would_order_entry_policy": "shadow_limit_first_delay_queue",
                "would_guarded_market_fallback": "guarded_market_after_fillability_cost_proof",
            },
        }
    }
    config = {
        "gtos_vnext_runtime": {
            "replay_order_fillability_policy_v1_enabled": True,
        },
        "broad_live_as_if_replay_harness": {
            "live_broker_authority": False,
            "broker_mutation_enabled": False,
            "final_selection_claim": False,
        },
    }
    asof = parse_utc("2026-04-21T08:00:00+00:00")
    expiry = parse_utc("2026-04-21T10:00:00+00:00")

    allowed = timewarp.replay_guarded_market_fallback_decision(
        config=config,
        candidate=candidate,
        packets=packets,
        scheduler_packet=scheduler_packet,
        risk_authority={"risk_decision": "trade"},
        selected_option={},
        selected_inputs={
            "fill_probability": 0.3,
            "limit_fillability_probability": 0.3,
            "source_completeness": 1.0,
        },
        limit_oracle_until_fallback={"fill_status": "not_filled_entry_not_touched_before_expiry"},
        asof=asof,
        expiry=expiry,
    )
    blocked_config = {**config, "broad_live_as_if_replay_harness": {}}
    blocked = timewarp.replay_guarded_market_fallback_decision(
        config=blocked_config,
        candidate=candidate,
        packets=packets,
        scheduler_packet=scheduler_packet,
        risk_authority={"risk_decision": "trade"},
        selected_option={},
        selected_inputs={
            "fill_probability": 0.3,
            "limit_fillability_probability": 0.3,
            "source_completeness": 1.0,
        },
        limit_oracle_until_fallback={"fill_status": "not_filled_entry_not_touched_before_expiry"},
        asof=asof,
        expiry=expiry,
    )

    assert allowed["status"] == "eligible"
    assert allowed["live_broker_authority"] is False
    assert blocked["status"] == "not_eligible"
    assert "not_broad_live_as_if_no_broker_replay" in blocked["reasons"]


def test_guarded_market_fallback_clamps_inside_order_lifetime() -> None:
    candidate = {
        "candidate_id": "candidate-fallback-clamp",
        "symbol": "XAUUSD",
        "side": "LONG",
        "candle_close_utc": "2026-04-21T08:00:00+00:00",
    }
    packets = {
        "candidate_probability": 0.7,
        "candidate_ev_r": 0.5,
        "pretrade_broker_net_cost_packet": {
            "status": "PASSED",
            "authority": "broker_calibrated_replay_cost",
            "cost_source_gap_status": "source_bound_cost_authority_present",
            "total_cost_r": 0.05,
        },
    }
    scheduler_packet = {
        "ultimate_candidate_package_shadow": {
            "shadow_selected_candidate_id": "candidate-fallback-clamp",
            "execution_policy_shadow": {
                "would_order_entry_policy": "limit_first_with_guarded_market_fallback",
                "would_guarded_market_fallback": (
                    "guarded_market_after_fillability_cost_proof"
                ),
            },
        }
    }
    config = {
        "gtos_vnext_runtime": {
            "replay_order_fillability_policy_v1_enabled": True,
            "replay_order_fillability_policy_v1_fallback_delay_minutes": 30,
        },
        "broad_live_as_if_replay_harness": {
            "live_broker_authority": False,
            "broker_mutation_enabled": False,
            "final_selection_claim": False,
        },
    }
    base_kwargs = {
        "config": config,
        "candidate": candidate,
        "packets": packets,
        "scheduler_packet": scheduler_packet,
        "risk_authority": {"risk_decision": "trade"},
        "selected_option": {},
        "selected_inputs": {
            "fill_probability": 0.3,
            "limit_fillability_probability": 0.3,
            "source_completeness": 1.0,
        },
        "limit_oracle_until_fallback": {
            "fill_status": "not_filled_entry_not_touched_before_expiry"
        },
        "asof": parse_utc("2026-04-21T08:00:00+00:00"),
    }

    clamped = timewarp.replay_guarded_market_fallback_decision(
        **base_kwargs,
        expiry=parse_utc("2026-04-21T08:20:00+00:00"),
    )
    exhausted = timewarp.replay_guarded_market_fallback_decision(
        **base_kwargs,
        expiry=parse_utc("2026-04-21T08:00:30+00:00"),
    )

    assert clamped["status"] == "eligible"
    assert clamped["fallback_decision_time_utc"] == "2026-04-21T08:19:00+00:00"
    assert clamped["fallback_unclamped_decision_time_utc"] == (
        "2026-04-21T08:30:00+00:00"
    )
    assert clamped["fallback_latest_usable_time_utc"] == (
        "2026-04-21T08:19:00+00:00"
    )
    assert clamped["fallback_time_clamped_inside_order_lifetime"] is True
    assert clamped["fallback_window_exhausted_by_expiry"] is False
    assert "fallback_window_exhausted_by_expiry" not in clamped["reasons"]

    assert exhausted["status"] == "not_eligible"
    assert exhausted["reason"] == "fallback_window_exhausted_by_expiry"
    assert exhausted["fallback_decision_time_utc"] is None
    assert exhausted["fallback_latest_usable_time_utc"] == (
        "2026-04-21T07:59:30+00:00"
    )
    assert exhausted["fallback_window_exhausted_by_expiry"] is True
    assert "fallback_window_exhausted_by_expiry" in exhausted["reasons"]


def test_replay_order_type_primitive_separates_architecture_from_execution_type() -> None:
    assert timewarp.replay_order_type_primitive("limit_first_reduced_risk") == "limit"
    assert (
        timewarp.replay_order_type_primitive(
            None,
            architecture="limit_first_with_guarded_market_fallback",
        )
        == "limit"
    )
    assert timewarp.replay_order_type_primitive("market") == "market"
    assert timewarp.replay_order_type_primitive("shadow_skip_or_reject") == "none"


