    assert payload["probe_count"] == 1
    assert payload["finalizer_backfilled_selected_option_count"] == 1
    probe = payload["probe_rows"][0]
    assert probe["risk_finalizer_backfilled_missing_scheduler_option"] is True
    assert (
        probe["risk_finalizer_backfilled_candidate_identity_source"]
        == "selected:exact_candidate_id_decision_time"
    )
    assert probe["selected"] is False
    assert probe["status"] == "package_executable_authority_required_not_met"
    assert probe["risk_decision_reason"] == (
        "risk_finalizer_backfilled_missing_exact_selected_option_provenance"
    )
    assert probe["risk_finalizer_backfilled_quality_probe_ready"] is False
    assert probe["risk_finalizer_backfilled_executable_authority_status"] == (
        "probe_only_missing_exact_scheduler_selected_option_provenance"
    )
    assert probe["package_replay_executable_candidate_use_allowed"] is False
    assert probe["package_replay_executable_candidate_use_allowed_reason"] == (
        "risk_finalizer_backfilled_missing_exact_selected_option_provenance"
    )
    assert probe["risk_finalizer_backfilled_package_replay_executable_authority_source"] == (
        "risk_finalizer_backfilled_missing_exact_selected_option_provenance"
    )


