def test_numeric_disagreement_reduce_risk_requires_open_reduced_package_quality_authority() -> None:
    decision_time = "2026-04-21T08:00:00+00:00"
    selector_packet = {
        "action": "reduce-risk",
        "reason": "numeric_confluence_structured_disagreement",
        "final_risk_pct": 0.25,
        "component_scores": {
            "broker_net_admission_ev_r": 1.10,
            "broker_net_selected_cell": {
                "broker_net_expectancy_r": 1.10,
                "stress_expectancy_r": 1.00,
            },
            "ultimate_candidate_package": {
                "source_bound_package_candidate_use_allowed": True,
                "admission_sleeve_match_count": 1,
                "matched_sleeve_count": 1,
                "matched_sleeves": [
                    {
                        "sleeve_id": "numeric-mixed-package",
                        "combined_source_bound_signal_r": 12.5,
                    }
                ],
            },
        },
    }
    candidate = {
        "candidate_id": "numeric-mixed-package",
        "decision_time_utc": decision_time,
        "ultimate_package_source_bound_candidate_use_allowed": True,
        **_exact_package_member_axis_proof(
            "member_axis:numeric-mixed-package:LONG:numeric_disagreement"
        ),
        "candidate_expected_net_r": 1.05,
        "probability": 0.72,
        "fill_probability": 0.81,
        "source_completeness": 1.0,
        "source_completeness_status": "source_completeness_present",
    }
    _add_strict_limit_fillability(candidate, 0.81)
    packets = {
        "pretrade_broker_net_cost_packet": {
            "status": "PASSED",
            "authority": "broker_calibrated_replay_cost",
            "cost_source_gap_status": "source_bound_cost_authority_present",
            "candidate_cost_r_fallback_is_authority": False,
        },
        "expected_net_r": 1.05,
        "probability": 0.72,
        "fill_probability": 0.81,
        "source_completeness": 1.0,
    }

    nonpackage_selector_packet = {
        **selector_packet,
        "component_scores": {
            **selector_packet["component_scores"],
            "ultimate_candidate_package": {
                "source_bound_package_candidate_use_allowed": False,
                "admission_sleeve_match_count": 0,
                "matched_sleeve_count": 0,
                "matched_sleeves": [],
            },
        },
    }
    assert (
        timewarp.selector_reduce_risk_new_entry_block_reason(
            nonpackage_selector_packet,
            "new_position",
            candidate={**candidate, "ultimate_package_source_bound_candidate_use_allowed": False},
            packets=packets,
        )
        == "selector_reduce_risk_new_entry_blocked:numeric_confluence_structured_disagreement"
    )
    assert (
        timewarp.selector_reduce_risk_new_entry_block_reason(
            selector_packet,
            "new_position",
            candidate=candidate,
            packets=packets,
        )
        is None
    )
    assert (
        timewarp.selector_reduce_risk_new_entry_block_reason(
            selector_packet,
            "new_position",
            candidate={
                **candidate,
                "package_replay_executable_candidate_use_allowed": True,
            },
            packets=packets,
        )
        is None
    )

    open_reduced_selector_packet = {
        **selector_packet,
        "action": "open-reduced-risk",
        "reason": "ultimate_candidate_package_numeric_disagreement_open_reduced_risk",
    }
    assert (
        timewarp.selector_reduce_risk_new_entry_block_reason(
            open_reduced_selector_packet,
            "new_position",
            candidate={
                **candidate,
                "ultimate_candidate_package_open_reduced_risk_authority": {
                    "applies": True,
                    "allowed": True,
                    "authority_family": "numeric_disagreement_softening",
                },
                "package_replay_executable_candidate_use_allowed": True,
            },
            packets=packets,
        )
        is None
    )


