def test_risk_finalizer_zero_trade_soft_veto_uses_reallocation_score_handoff(
    monkeypatch,
) -> None:
    final_ids, payload = _run_zero_trade_soft_veto_score_override_fixture(
        monkeypatch,
    )

    assert final_ids == ["zero-trade-soft-veto-score-override"]
    assert payload["status"] == "risk_admitted_selection_materialized_from_zero_trade"
    probe = payload["probe_rows"][0]
    assert probe["scheduler_score"] == -0.01
    assert probe["risk_admitted_scheduler_reallocation_score"] == 0.52
    assert probe["scheduler_quality_gate_score"] == 0.52
    assert (
        probe["risk_finalizer_scheduler_quality_score_source"]
        == "zero_trade_soft_veto_risk_admitted_scheduler_reallocation_score"
    )
    assert probe["risk_finalizer_scheduler_score_floor_override_applied"] is True
    assert probe["risk_finalizer_scheduler_score_floor_override_allowed"] is True
    assert probe["risk_finalizer_scheduler_score_floor_override_failures"] == []
    assert probe["risk_finalizer_scheduler_score_floor_override_uses_outcome_fields"] is False
    assert "scheduler_score" not in probe["risk_finalizer_causal_quality_gate_failures"]
    assert probe["risk_finalizer_causal_quality_gate_failures"] == []


