def _source_safe_occurrence_candidate(
    *,
    stop_loss: float,
    emission_ordinal: int = 0,
) -> dict:
    decision_time = "2026-05-14T00:00:00+00:00"
    target = 100.0 + 1.5 * (100.0 - stop_loss)
    row = {
        "candidate_id": "legacy-shared-id",
        "symbol": "XAUUSD",
        "side": "LONG",
        "direction": "LONG",
        "origin_family": "displacement_continuation",
        "candidate_origin_family": "origin_displacement_continuation",
        "framework": "displacement_continuation",
        "timeframe": "M15",
        "market_timeframe": "M15",
        "candle_open_utc": "2026-05-13T23:45:00Z",
        "candle_close_utc": "2026-05-14T00:00:00Z",
        "decision_time_utc": decision_time,
        "entry_price": 100.0,
        "stop_loss": stop_loss,
        "take_profit_1": target,
        "risk_reward_ratio": 1.5,
        "rr": 1.5,
        "entry_reference": 100.0,
        "stop_or_invalidation": stop_loss,
        "target_reference": target,
        "trade_parameters": {
            "direction": "LONG",
            "entry_price": 100.0,
            "stop_loss": stop_loss,
            "take_profit_1": target,
            "risk_reward_ratio": 1.5,
        },
        "source_window_complete": True,
        "source_completeness": 1.0,
        "source_completeness_status": "complete",
        "source_path_feature_status": "raw_data_m15_asof_complete",
        "session": "moonshot_h00_01",
        "session_bucket": "moonshot_h00_01",
        "kill_zone": "moonshot_h00_01",
        "route_session": "moonshot_h00_01",
        "utc_hour_bucket": "h00_01",
        "live_generation_status": "generated_live_asof",
        "candidate_lineage_authority": (
            "producer_bound_not_independently_reverified"
        ),
        "source_fields": {"generation_rule": "displacement_continuation"},
        "predecision_features": {"range_atr14": 2.0},
        CANDIDATE_SOURCE_SAFE_DECISION_TIME_FIELD: decision_time,
        CANDIDATE_SOURCE_SLICE_HASHES_FIELD: {
            timeframe: str(index + 1) * 64
            for index, timeframe in enumerate(("D1", "H4", "H1", "M15"))
        },
        CANDIDATE_SOURCE_ROW_ASSOCIATION_FIELD: {
            timeframe: {
                "row_count": 1,
                "last_open_utc": "2026-05-13T23:45:00Z",
                "completion_witness": {
                    "witness_type": "observed_successor_open_utc_upper_bound",
                    "completion_semantics": "next_bound_open_not_exact_close",
                    "timeframe": timeframe,
                    "predecessor_source_ordinal": 8,
                    "successor_source_ordinal": 9,
                    "predecessor_open_utc": "2026-05-13T23:45:00Z",
                    "successor_open_utc": decision_time,
                    "successor_market_values_consumed": False,
                },
            }
            for timeframe in ("D1", "H4", "H1", "M15")
        },
        CANDIDATE_EMISSION_ORDINAL_FIELD: emission_ordinal,
        "expected_net_r": 0.5,
        "probability": 0.6,
        "fill_probability": 0.7,
        "source_completeness": 1.0,
        "selector_action": "reject",
        "selector_reason": "unit_terminal",
    }
    row[CANDIDATE_SOURCE_SAFE_FINGERPRINT_FIELD] = (
        candidate_source_safe_fingerprint_from_fields(row)
    )
    row[CANDIDATE_SOURCE_LINEAGE_FINGERPRINT_FIELD] = row[
        CANDIDATE_SOURCE_SAFE_FINGERPRINT_FIELD
    ]
    row[CANDIDATE_EMISSION_ANCHOR_KEY_FIELD] = candidate_emission_anchor_key(
        row[CANDIDATE_SOURCE_SAFE_FINGERPRINT_FIELD],
        emission_ordinal,
    )
    row[CANDIDATE_OCCURRENCE_KEY_FIELD] = candidate_occurrence_key_from_fields(row)
    row.update(timewarp.canonical_replay_candidate_instance_fields(row))
    return row


def _unit_scheduler_sidecar(
    scheduler_packet,
    candidates,
):
    """Build only downstream-unit state; production capture is allocator-internal."""

    owners = timewarp._candidate_occurrence_owners(candidates)
    options = timewarp._validate_scheduler_occurrence_option_surfaces(
        scheduler_packet,
        owners,
    )
    return timewarp._scheduler_candidate_option_sidecar_hashes(
        scheduler_packet,
        options,
        typed_owner_projection_sha256_by_occurrence={
            key: timewarp.stable_sha256(
                timewarp._candidate_occurrence_association_projection(candidate)
            )
            for key, candidate in owners.items()
        },
    )


def test_source_safe_occurrence_recomputes_and_survives_scheduler_terminals() -> None:
    first = _source_safe_occurrence_candidate(stop_loss=98.0)
    second = _source_safe_occurrence_candidate(stop_loss=97.5)

    assert first["candidate_id"] == second["candidate_id"]
    assert first["decision_time_utc"] == second["decision_time_utc"]
    assert first[CANDIDATE_SOURCE_SAFE_FINGERPRINT_FIELD] != second[
        CANDIDATE_SOURCE_SAFE_FINGERPRINT_FIELD
    ]
    assert first["canonical_replay_candidate_instance_key"] != second[
        "canonical_replay_candidate_instance_key"
    ]

    packet = scheduler.allocate_decision_window(
        {
            "asof_utc": first["decision_time_utc"],
            "candidates": [first, second],
            "open_positions": [],
            "pending_orders": [],
        },
        {},
    )
    candidate_options = [
        option
        for option in packet["all_options_preserved"]
        if option.get("source_type") == "new_candidate"
    ]
    assert len(candidate_options) == 2
    assert {
        option.get("canonical_replay_candidate_instance_key")
        for option in candidate_options
    } == {
        first[CANDIDATE_OCCURRENCE_KEY_FIELD],
        second[CANDIDATE_OCCURRENCE_KEY_FIELD],
    }

    nested_options = []
    for option in candidate_options:
        nested = copy.deepcopy(option)
        occurrence_key = str(
            option.get("canonical_replay_candidate_instance_key") or ""
        )
        for field in (
            CANDIDATE_OCCURRENCE_KEY_FIELD,
            "canonical_replay_candidate_instance_key",
            "risk_finalizer_probe_instance_key",
            "source_bound_replay_candidate_instance_key",
            "candidate_instance_identity_status",
        ):
            nested.pop(field, None)
        components = dict(nested.get("score_components") or {})
        decision_inputs = dict(components.get("candidate_decision_inputs") or {})
        decision_inputs.update(
            {
                CANDIDATE_OCCURRENCE_KEY_FIELD: occurrence_key,
                "canonical_replay_candidate_instance_key": occurrence_key,
                "risk_finalizer_probe_instance_key": occurrence_key,
                "source_bound_replay_candidate_instance_key": occurrence_key,
                "candidate_instance_identity_status": "materialized",
            }
        )
        components["candidate_decision_inputs"] = decision_inputs
        nested["score_components"] = components
        nested_options.append(nested)
    nested_packet = timewarp.validate_scheduler_candidate_occurrence_associations({
        "decision": {"selected_options": nested_options},
        "all_options_preserved": nested_options,
    }, [first, second])
    nested_pristine = _unit_scheduler_sidecar(
        nested_packet,
        [first, second],
    )
    nested_identity = timewarp.selected_scheduler_instance_identity_fields(
        nested_packet
    )
    assert nested_identity["selected_candidate_instance_keys"] == [
        timewarp.scheduler_all_options_preserved_option_instance_key(option)
        for option in nested_options
    ]
    assert len(set(nested_identity["selected_candidate_instance_keys"])) == 2
    nested_index = timewarp.scheduler_options_by_candidate_id(nested_packet)
    assert all(
        timewarp.scheduler_option_for_candidate(
            nested_index,
            candidate["candidate_id"],
            candidate["decision_time_utc"],
            candidate_occurrence_key=candidate[CANDIDATE_OCCURRENCE_KEY_FIELD],
        )
        is not None
        for candidate in (first, second)
    )
    _selected_ids, disabled_finalizer = (
        timewarp.finalize_scheduler_risk_admitted_selection(
            scheduler_packet=nested_packet,
            selected_ids=[first["candidate_id"], second["candidate_id"]],
            all_candidates=[first, second],
            v4_packets={},
            account=AccountState(),
            day="2026-05-14",
            config={"gtos_vnext_runtime": {}},
            pristine_options_by_occurrence=nested_pristine,
        )
    )
    assert disabled_finalizer["final_selected_candidate_instance_keys"] == (
        nested_identity["selected_candidate_instance_keys"]
    )

    stale = {**first, "entry_price": 101.0}
    stale_fields = timewarp.canonical_replay_candidate_instance_fields(stale)
    assert stale_fields["candidate_instance_identity_status"] == (
        "conflicting_candidate_occurrence_key"
    )
    post_selector_transform = {
        **first,
        "take_profit_1": 104.0,
        "target_reference": 104.0,
        "dynamic_geometry_applied": True,
        "candidate_source_safe_admission_status": (
            "validated_immediately_preselector"
        ),
        "candidate_source_safe_admission_fingerprint_sha256": first[
            CANDIDATE_SOURCE_SAFE_FINGERPRINT_FIELD
        ],
    }
    transformed_fields = timewarp.canonical_replay_candidate_instance_fields(
        post_selector_transform
    )
    assert transformed_fields["candidate_instance_identity_status"] == "materialized"
    assert transformed_fields["canonical_replay_candidate_instance_key"] == first[
        CANDIDATE_OCCURRENCE_KEY_FIELD
    ]


def test_truth_occurrence_claim_requires_declared_recomputable_key() -> None:
    candidate = _source_safe_occurrence_candidate(stop_loss=98.0)
    missing = copy.deepcopy(candidate)
    missing.pop(CANDIDATE_OCCURRENCE_KEY_FIELD)
    for field in (
        "canonical_replay_candidate_instance_key",
        "risk_finalizer_probe_instance_key",
        "source_bound_replay_candidate_instance_key",
    ):
        missing.pop(field, None)
    identity = timewarp.canonical_replay_candidate_instance_fields(missing)
    assert identity["candidate_instance_identity_status"] == (
        "missing_declared_candidate_occurrence_key"
    )
    with pytest.raises(
        ValueError,
        match="candidate_source_safe_occurrence_invalid_before_selector",
    ):
        timewarp.evaluate_candidate_v4(
            candidate=missing,
            config={},
            source=None,
            risk_pct=0.25,
            asof_utc=candidate["decision_time_utc"],
            mso=None,
        )
    with pytest.raises(
        ValueError,
        match="candidate_occurrence_identity_invalid_before_scheduler_materialization",
    ):
        timewarp.materialize_scheduler_window(
            asof_utc=candidate["decision_time_utc"],
            candidates=[missing],
            v4_packets={},
            config={},
        )

    legacy = copy.deepcopy(candidate)
    for field in (
        CANDIDATE_SOURCE_SAFE_FINGERPRINT_FIELD,
        CANDIDATE_SOURCE_LINEAGE_FINGERPRINT_FIELD,
        CANDIDATE_EMISSION_ANCHOR_KEY_FIELD,
        CANDIDATE_EMISSION_ORDINAL_FIELD,
        CANDIDATE_OCCURRENCE_KEY_FIELD,
        "canonical_replay_candidate_instance_key",
        "risk_finalizer_probe_instance_key",
        "source_bound_replay_candidate_instance_key",
    ):
        legacy.pop(field, None)
    legacy_identity = timewarp.canonical_replay_candidate_instance_fields(legacy)
    assert legacy_identity["candidate_instance_identity_status"] == "materialized"
    assert legacy_identity["canonical_replay_candidate_instance_key"] == (
        "legacy-shared-id@@2026-05-14T00:00:00+00:00"
    )


def test_scheduler_pristine_sidecar_boundary_is_default_inert_and_sink_strict() -> None:
    candidate = _source_safe_occurrence_candidate(stop_loss=98.0)
    packet_payload = {
        "selector_packet": {
            "action": "trade",
            "reason": "unit_sidecar_boundary",
            "final_risk_pct": 0.25,
        },
        "lifecycle_packet": {"action": "new_position"},
        "expected_net_r": 0.5,
        "probability": 0.6,
        "fill_probability": 0.7,
        "source_completeness": 1.0,
        "pretrade_broker_net_cost_packet": {
            "status": "PASSED",
            "authority": "broker_calibrated_replay_cost",
            "cost_source_gap_status": "source_bound_cost_authority_present",
            "candidate_cost_r_fallback_is_authority": False,
            "total_cost_r": 0.04,
            "refusal_reasons": [],
        },
    }
    config = {
        "gtos_vnext_runtime": {
            "scheduler_v4_best_trade_allocator_enabled": True,
            "scheduler_v4_best_trade_allocator_apply_to_execution": True,
        }
    }
    legacy_packet_key = (
        f'{candidate["candidate_id"]}@@{candidate["decision_time_utc"]}'
    )
    legacy = copy.deepcopy(candidate)
    for field in (
        *timewarp.CANDIDATE_OCCURRENCE_CONTRACT_FIELDS,
        "canonical_replay_candidate_instance_key",
        "risk_finalizer_probe_instance_key",
        "source_bound_replay_candidate_instance_key",
    ):
        legacy.pop(field, None)

    legacy_packet = timewarp.materialize_scheduler_window(
        asof_utc=candidate["decision_time_utc"],
        candidates=[legacy],
        v4_packets={legacy_packet_key: packet_payload},
        config=config,
    )
    assert legacy_packet["schema_version"] == (
        "scheduler_v4_best_trade_allocator_packet_v1"
    )
    assert legacy_packet["input_counts"]["candidate_rows"] == 1

    with pytest.raises(
        ValueError,
        match="scheduler_pristine_candidate_occurrence_missing",
    ):
        timewarp.materialize_scheduler_window(
            asof_utc=candidate["decision_time_utc"],
            candidates=[copy.deepcopy(legacy)],
            v4_packets={legacy_packet_key: packet_payload},
            config=config,
            _pristine_scheduler_sidecar_sink={},
        )

    skipped_candidate = copy.deepcopy(candidate)
    skipped_packet = timewarp.materialize_scheduler_window(
        asof_utc=candidate["decision_time_utc"],
        candidates=[skipped_candidate],
        v4_packets={},
        config=config,
    )
    assert skipped_candidate.get("scheduler_materialization_status") != (
        "scheduler_option_materialized"
    )
    assert not any(
        option.get("source_type") == "new_candidate"
        for option in skipped_packet["all_options_preserved"]
    )

    skipped_sink_candidate = copy.deepcopy(candidate)
    skipped_sink: dict[str, object] = {}
    skipped_sink_packet = timewarp.materialize_scheduler_window(
        asof_utc=candidate["decision_time_utc"],
        candidates=[skipped_sink_candidate],
        v4_packets={},
        config=config,
        _pristine_scheduler_sidecar_sink=skipped_sink,
    )
    assert skipped_sink["scheduler_sidecar"][
        "option_sha256_by_occurrence"
    ] == {}
    timewarp.validate_pristine_scheduler_candidate_options_by_occurrence(
        skipped_sink_packet,
        [skipped_sink_candidate],
        skipped_sink["scheduler_sidecar"],
    )

    sink: dict[str, object] = {}
    occurrence_packet = timewarp.materialize_scheduler_window(
        asof_utc=candidate["decision_time_utc"],
        candidates=[copy.deepcopy(candidate)],
        v4_packets={candidate[CANDIDATE_OCCURRENCE_KEY_FIELD]: packet_payload},
        config=config,
        _pristine_scheduler_sidecar_sink=sink,
    )
    new_candidate_options = [
        option
        for option in occurrence_packet["all_options_preserved"]
        if option.get("source_type") == "new_candidate"
    ]
    assert len(new_candidate_options) == 1
    assert set(sink) == {"scheduler_sidecar"}
    assert set(sink["scheduler_sidecar"]) == {
        "all_options_preserved_sha256",
        "decision_sha256",
        "option_sha256_by_occurrence",
        "typed_owner_projection_sha256_by_occurrence",
    }
    assert set(
        sink["scheduler_sidecar"]["option_sha256_by_occurrence"]
    ) == {candidate[CANDIDATE_OCCURRENCE_KEY_FIELD]}
    assert set(
        sink["scheduler_sidecar"][
            "typed_owner_projection_sha256_by_occurrence"
        ]
    ) == {candidate[CANDIDATE_OCCURRENCE_KEY_FIELD]}
    with pytest.raises(
        ValueError,
        match="scheduler_candidate_occurrence_owner_missing",
    ):
        timewarp.validate_pristine_scheduler_candidate_options_by_occurrence(
            occurrence_packet,
            [],
            sink["scheduler_sidecar"],
        )
    with pytest.raises(
        ValueError,
        match="scheduler_candidate_occurrence_owner_not_unique",
    ):
        timewarp.validate_pristine_scheduler_candidate_options_by_occurrence(
            occurrence_packet,
            [candidate, copy.deepcopy(candidate)],
            sink["scheduler_sidecar"],
        )

    mixed_materialized = copy.deepcopy(candidate)
    mixed_skipped = _source_safe_occurrence_candidate(stop_loss=97.5)
    mixed_sink: dict[str, object] = {}
    mixed_packet = timewarp.materialize_scheduler_window(
        asof_utc=candidate["decision_time_utc"],
        candidates=[mixed_materialized, mixed_skipped],
        v4_packets={candidate[CANDIDATE_OCCURRENCE_KEY_FIELD]: packet_payload},
        config=config,
        _pristine_scheduler_sidecar_sink=mixed_sink,
    )
    assert mixed_materialized["scheduler_materialization_status"] == (
        "scheduler_option_materialized"
    )
    assert mixed_skipped.get("scheduler_materialization_status") != (
        "scheduler_option_materialized"
    )
    assert set(
        mixed_sink["scheduler_sidecar"]["option_sha256_by_occurrence"]
    ) == {candidate[CANDIDATE_OCCURRENCE_KEY_FIELD]}
    timewarp.validate_pristine_scheduler_candidate_options_by_occurrence(
        mixed_packet,
        [mixed_materialized, mixed_skipped],
        mixed_sink["scheduler_sidecar"],
    )


def test_source_safe_enrichment_atomically_remints_before_selector(
    monkeypatch,
) -> None:
    candidate = _source_safe_occurrence_candidate(stop_loss=98.0)
    original_occurrence = candidate[CANDIDATE_OCCURRENCE_KEY_FIELD]
    raw_data = {
        "candles": {
            "M15": [
                {
                    "time_utc": "2026-05-13T23:45:00+00:00",
                    "open": 99.5,
                    "high": 100.5,
                    "low": 99.0,
                    "close": 100.25,
                    "volume": 10,
                }
            ]
        }
    }

    enriched = timewarp.enrich_candidate_with_predecision_market_snapshot(
        candidate,
        raw_data,
        asof_utc=candidate["decision_time_utc"],
    )

    assert enriched[CANDIDATE_OCCURRENCE_KEY_FIELD] != original_occurrence
    assert candidate_occurrence_key_from_fields(enriched) == enriched[
        CANDIDATE_OCCURRENCE_KEY_FIELD
    ]
    identity = timewarp.canonical_replay_candidate_instance_fields(enriched)
    assert identity["candidate_instance_identity_status"] == "materialized"
    for field in (
        "canonical_replay_candidate_instance_key",
        "risk_finalizer_probe_instance_key",
        "source_bound_replay_candidate_instance_key",
    ):
        assert enriched[field] == enriched[CANDIDATE_OCCURRENCE_KEY_FIELD]
    assert "candidate_source_safe_admission_status" not in enriched

    def identity_gate_passed(**_kwargs):
        raise RuntimeError("identity_gate_passed")

    monkeypatch.setattr(
        timewarp,
        "broker_calibrated_replay_cost_packet",
        identity_gate_passed,
    )
    with pytest.raises(RuntimeError, match="identity_gate_passed"):
        timewarp.evaluate_candidate_v4(
            candidate=enriched,
            config={},
            source=None,
            risk_pct=0.25,
            asof_utc=candidate["decision_time_utc"],
            mso=None,
        )


def test_source_safe_enrichment_batch_preserves_convergent_occurrences_under_reorder() -> None:
    raw_data = {
        "candles": {
            "M15": [
                {
                    "time_utc": "2026-05-13T23:45:00+00:00",
                    "open": 99.5,
                    "high": 100.5,
                    "low": 99.0,
                    "close": 100.25,
                    "volume": 10,
                }
            ]
        }
    }
    without_snapshot = _source_safe_occurrence_candidate(stop_loss=98.0)
    with_snapshot = timewarp.enrich_candidate_with_predecision_market_snapshot(
        _source_safe_occurrence_candidate(stop_loss=98.0, emission_ordinal=1),
        raw_data,
        asof_utc=without_snapshot["decision_time_utc"],
    )
    unrelated = _source_safe_occurrence_candidate(stop_loss=97.5)
    assert without_snapshot[CANDIDATE_OCCURRENCE_KEY_FIELD] != with_snapshot[
        CANDIDATE_OCCURRENCE_KEY_FIELD
    ]

    def reminted_by_parent(rows):
        output = timewarp.enrich_candidates_with_predecision_market_snapshot(
            rows,
            raw_data,
            asof_utc=without_snapshot["decision_time_utc"],
        )
        return {
            parent[CANDIDATE_OCCURRENCE_KEY_FIELD]: candidate[
                CANDIDATE_OCCURRENCE_KEY_FIELD
            ]
            for parent, candidate in zip(rows, output)
        }, output

    base, base_rows = reminted_by_parent([without_snapshot, with_snapshot])
    reordered, reordered_rows = reminted_by_parent(
        [with_snapshot, without_snapshot]
    )
    inserted, inserted_rows = reminted_by_parent(
        [unrelated, with_snapshot, without_snapshot]
    )

    parent_keys = {
        without_snapshot[CANDIDATE_OCCURRENCE_KEY_FIELD],
        with_snapshot[CANDIDATE_OCCURRENCE_KEY_FIELD],
    }
    assert {key: reordered[key] for key in parent_keys} == base
    assert {key: inserted[key] for key in parent_keys} == base
    assert len(set(base.values())) == 2
    for rows in (base_rows, reordered_rows, inserted_rows):
        keys = [row[CANDIDATE_OCCURRENCE_KEY_FIELD] for row in rows]
        assert len(keys) == len(set(keys))
        assert all(candidate_occurrence_key_from_fields(row) == key for row, key in zip(rows, keys))
        assert all(
            timewarp.canonical_replay_candidate_instance_fields(row)[
                "candidate_instance_identity_status"
            ]
            == "materialized"
            for row in rows
        )
    repeated = timewarp.enrich_candidates_with_predecision_market_snapshot(
        base_rows,
        raw_data,
        asof_utc=without_snapshot["decision_time_utc"],
    )
    repeated_again = timewarp.enrich_candidates_with_predecision_market_snapshot(
        repeated,
        raw_data,
        asof_utc=without_snapshot["decision_time_utc"],
    )
    assert [row[CANDIDATE_OCCURRENCE_KEY_FIELD] for row in repeated] == [
        row[CANDIDATE_OCCURRENCE_KEY_FIELD] for row in base_rows
    ]
    assert [row[CANDIDATE_OCCURRENCE_KEY_FIELD] for row in repeated_again] == [
        row[CANDIDATE_OCCURRENCE_KEY_FIELD] for row in base_rows
    ]
    with pytest.raises(
        ValueError,
        match="candidate_source_safe_batch_parent_occurrence_not_unique",
    ):
        timewarp.enrich_candidates_with_predecision_market_snapshot(
            [without_snapshot, copy.deepcopy(without_snapshot)],
            raw_data,
            asof_utc=without_snapshot["decision_time_utc"],
        )


def test_emission_anchor_rejects_swaps() -> None:
    first = _source_safe_occurrence_candidate(
        stop_loss=98.0,
        emission_ordinal=0,
    )
    second = _source_safe_occurrence_candidate(
        stop_loss=98.0,
        emission_ordinal=1,
    )
    assert first[CANDIDATE_SOURCE_SAFE_FINGERPRINT_FIELD] == second[
        CANDIDATE_SOURCE_SAFE_FINGERPRINT_FIELD
    ]

    swapped = [copy.deepcopy(first), copy.deepcopy(second)]
    swapped[0][CANDIDATE_EMISSION_ANCHOR_KEY_FIELD], swapped[1][
        CANDIDATE_EMISSION_ANCHOR_KEY_FIELD
    ] = (
        swapped[1][CANDIDATE_EMISSION_ANCHOR_KEY_FIELD],
        swapped[0][CANDIDATE_EMISSION_ANCHOR_KEY_FIELD],
    )
    with pytest.raises(
        ValueError,
        match="candidate_occurrence_invalid_before_source_safe_batch_transform",
    ):
        timewarp.remint_candidate_occurrences_after_source_safe_transform(
            swapped,
            parent_candidates=swapped,
        )

    swapped_triples = [copy.deepcopy(first), copy.deepcopy(second)]
    triple_fields = (
        CANDIDATE_SOURCE_LINEAGE_FINGERPRINT_FIELD,
        CANDIDATE_EMISSION_ORDINAL_FIELD,
        CANDIDATE_EMISSION_ANCHOR_KEY_FIELD,
    )
    for field in triple_fields:
        swapped_triples[0][field], swapped_triples[1][field] = (
            swapped_triples[1][field],
            swapped_triples[0][field],
        )
    with pytest.raises(
        ValueError,
        match="candidate_source_safe_batch_frozen_lineage_invalid",
    ):
        timewarp.remint_candidate_occurrences_after_source_safe_transform(
            swapped_triples,
            parent_candidates=[first, second],
        )


def test_emission_anchor_rejects_arbitrary_valid_prefix() -> None:
    first = _source_safe_occurrence_candidate(stop_loss=98.0)
