def test_emission_anchor_is_idempotent_when_lexical_hash_order_is_inverted() -> None:
    rows = [
        _source_safe_occurrence_candidate(
            stop_loss=98.996,
            emission_ordinal=ordinal,
        )
        for ordinal in (0, 1)
    ]
    initial_by_anchor = {
        row[CANDIDATE_EMISSION_ANCHOR_KEY_FIELD]: (
            row[CANDIDATE_EMISSION_ORDINAL_FIELD],
            row[CANDIDATE_OCCURRENCE_KEY_FIELD],
        )
        for row in rows
    }
    assert list(initial_by_anchor) != sorted(initial_by_anchor)

    for _pass in range(3):
        rows = timewarp.remint_candidate_occurrences_after_source_safe_transform(
            list(reversed(rows)),
            parent_candidates=list(reversed(rows)),
        )
        assert {
            row[CANDIDATE_EMISSION_ANCHOR_KEY_FIELD]: (
                row[CANDIDATE_EMISSION_ORDINAL_FIELD],
                row[CANDIDATE_OCCURRENCE_KEY_FIELD],
            )
            for row in rows
        } == initial_by_anchor


def test_emission_lineage_keeps_converged_transforms_distinct() -> None:
    first = _source_safe_occurrence_candidate(stop_loss=98.0)
    second = _source_safe_occurrence_candidate(stop_loss=97.5)
    transformed = [copy.deepcopy(first), copy.deepcopy(second)]
    transformed[1].update(
        {
            "stop_loss": first["stop_loss"],
            "stop_or_invalidation": first["stop_or_invalidation"],
            "take_profit_1": first["take_profit_1"],
            "target_reference": first["target_reference"],
        }
    )
    transformed[1]["trade_parameters"] = copy.deepcopy(
        first["trade_parameters"]
    )
    reminted = timewarp.remint_candidate_occurrences_after_source_safe_transform(
        transformed,
        parent_candidates=[first, second],
    )
    assert reminted[0][CANDIDATE_SOURCE_SAFE_FINGERPRINT_FIELD] == reminted[1][
        CANDIDATE_SOURCE_SAFE_FINGERPRINT_FIELD
    ]
    assert reminted[0][CANDIDATE_SOURCE_LINEAGE_FINGERPRINT_FIELD] != reminted[1][
        CANDIDATE_SOURCE_LINEAGE_FINGERPRINT_FIELD
    ]
    assert reminted[0][CANDIDATE_OCCURRENCE_KEY_FIELD] != reminted[1][
        CANDIDATE_OCCURRENCE_KEY_FIELD
    ]
    repeated = timewarp.remint_candidate_occurrences_after_source_safe_transform(
        list(reversed(reminted)),
        parent_candidates=list(reversed(reminted)),
    )
    assert {
        row[CANDIDATE_EMISSION_ANCHOR_KEY_FIELD]: row[
            CANDIDATE_OCCURRENCE_KEY_FIELD
        ]
        for row in repeated
    } == {
        row[CANDIDATE_EMISSION_ANCHOR_KEY_FIELD]: row[
            CANDIDATE_OCCURRENCE_KEY_FIELD
        ]
        for row in reminted
    }


def test_scheduler_occurrence_association_rejects_candidate_a_with_candidate_b_key() -> None:
    first = _source_safe_occurrence_candidate(stop_loss=98.0)
    second = _source_safe_occurrence_candidate(stop_loss=97.5)
    first["candidate_id"] = "candidate-A"
    second["candidate_id"] = "candidate-B"
    packet = scheduler.allocate_decision_window(
        {
            "asof_utc": first["decision_time_utc"],
            "candidates": [first, second],
            "open_positions": [],
            "pending_orders": [],
        },
        {},
    )

    def options_by_candidate_id(source_packet):
        return {
            option["candidate_id"]: option
            for option in source_packet["all_options_preserved"]
            if option.get("candidate_id") in {"candidate-A", "candidate-B"}
        }

    raw_options = options_by_candidate_id(packet)
    forged_unbound = copy.deepcopy(raw_options["candidate-A"])
    second_key = second[CANDIDATE_OCCURRENCE_KEY_FIELD]
    components = dict(forged_unbound.get("score_components") or {})
    decision_inputs = dict(components.get("candidate_decision_inputs") or {})
    for surface in (forged_unbound, decision_inputs):
        for field in (
            CANDIDATE_OCCURRENCE_KEY_FIELD,
            "canonical_replay_candidate_instance_key",
            "risk_finalizer_probe_instance_key",
            "source_bound_replay_candidate_instance_key",
        ):
            surface[field] = second_key
        surface["candidate_instance_identity_status"] = "materialized"
    components["candidate_decision_inputs"] = decision_inputs
    forged_unbound["score_components"] = components
    with pytest.raises(
        ValueError,
        match="scheduler_candidate_option_occurrence_partition_not_bijective",
    ):
        timewarp.validate_scheduler_candidate_occurrence_associations(
            {"all_options_preserved": [forged_unbound]},
            [first, second],
        )

    validated = timewarp.validate_scheduler_candidate_occurrence_associations(
        packet,
        [first, second],
    )
    bound_options = options_by_candidate_id(validated)
    forged_bound = copy.deepcopy(bound_options["candidate-A"])
    components = dict(forged_bound.get("score_components") or {})
    decision_inputs = dict(components.get("candidate_decision_inputs") or {})
    for surface in (forged_bound, decision_inputs):
        surface["candidate_id"] = "candidate-B"
        for field in (
            CANDIDATE_OCCURRENCE_KEY_FIELD,
            "canonical_replay_candidate_instance_key",
            "risk_finalizer_probe_instance_key",
            "source_bound_replay_candidate_instance_key",
        ):
            surface[field] = second_key
        surface["candidate_instance_identity_status"] = "materialized"
    components["candidate_decision_inputs"] = decision_inputs
    forged_bound["score_components"] = components
    with pytest.raises(
        ValueError,
        match="scheduler_candidate_option_occurrence_partition_not_bijective",
    ):
        timewarp.finalized_scheduler_packet_for_selection(
            {"all_options_preserved": [forged_bound]},
            [second_key],
            current_candidates=[first, second],
        )
def test_timewarp_occurrence_packet_options_survive_reorder_and_insertion(
    monkeypatch,
) -> None:
    monkeypatch.setattr(timewarp, "ultimate_package_member_axis_rows", lambda: [])
    first = _source_safe_occurrence_candidate(stop_loss=98.0)
    second = _source_safe_occurrence_candidate(stop_loss=97.5)
    unrelated = _source_safe_occurrence_candidate(stop_loss=96.5)
    unrelated["candidate_id"] = "unrelated-candidate-id"
    candidates = (first, second, unrelated)
    labels = {
        first[CANDIDATE_OCCURRENCE_KEY_FIELD]: "first_selector_terminal",
        second[CANDIDATE_OCCURRENCE_KEY_FIELD]: "second_selector_terminal",
        unrelated[CANDIDATE_OCCURRENCE_KEY_FIELD]: "unrelated_selector_terminal",
    }
    packets = {
        candidate[CANDIDATE_OCCURRENCE_KEY_FIELD]: {
            "selector_packet": {
                "action": "trade",
                "reason": labels[candidate[CANDIDATE_OCCURRENCE_KEY_FIELD]],
                "final_risk_pct": 0.25,
            },
            "lifecycle_packet": {"action": "new_position"},
            "expected_net_r": 0.50,
            "probability": 0.60,
            "fill_probability": 0.70,
            "source_completeness": 1.0,
            "pretrade_broker_net_cost_packet": {
                "status": "PASSED",
                "authority": "broker_calibrated_replay_cost",
                "cost_source_gap_status": "source_bound_cost_authority_present",
                "candidate_cost_r_fallback_is_authority": False,
                "total_cost_r": 0.04,
                "refusal_reasons": [],
            },
        }
        for candidate in candidates
    }
    config = {
        "gtos_vnext_runtime": {
            "scheduler_v4_best_trade_allocator_enabled": True,
            "scheduler_v4_best_trade_allocator_apply_to_execution": True,
        }
    }

    def materialized(rows):
        rows = [
            {
                **copy.deepcopy(candidate),
                "selector_action": "trade",
                "selector_reason": labels[
                    candidate[CANDIDATE_OCCURRENCE_KEY_FIELD]
                ],
                "lifecycle_action": "new_position",
                "risk_pct": 0.25,
            }
            for candidate in rows
        ]
        packet = timewarp.materialize_scheduler_window(
            asof_utc=first["decision_time_utc"],
            candidates=rows,
            v4_packets=packets,
            config=config,
        )
        options = {
            str(option.get("canonical_replay_candidate_instance_key")): option
            for option in packet["all_options_preserved"]
            if option.get("source_type") == "new_candidate"
        }
        return packet, {
            key: (option.get("selector_reason"), option.get("decision_status"))
            for key, option in options.items()
        }

    base_packet, base = materialized((first, second))
    reordered_packet, reordered = materialized((second, first))
    inserted_packet, inserted = materialized((unrelated, first, second))
    first_two_keys = {
        first[CANDIDATE_OCCURRENCE_KEY_FIELD],
        second[CANDIDATE_OCCURRENCE_KEY_FIELD],
    }

    assert set(base) == first_two_keys
    assert base == reordered
    assert {key: inserted[key] for key in first_two_keys} == base
    assert inserted[unrelated[CANDIDATE_OCCURRENCE_KEY_FIELD]][0] == (
        "unrelated_selector_terminal"
    )
    for packet in (base_packet, reordered_packet, inserted_packet):
        options_by_instance = timewarp.scheduler_options_by_candidate_id(packet)
        expected_candidates = (
            candidates if packet is inserted_packet else (first, second)
        )
        for candidate in expected_candidates:
            option = timewarp.scheduler_option_for_candidate(
                options_by_instance,
                candidate["candidate_id"],
                candidate["decision_time_utc"],
                candidate_occurrence_key=candidate[
                    CANDIDATE_OCCURRENCE_KEY_FIELD
                ],
            )
            assert option is not None
            assert option["canonical_replay_candidate_instance_key"] == candidate[
                CANDIDATE_OCCURRENCE_KEY_FIELD
            ]

    base_pristine = _unit_scheduler_sidecar(
        base_packet,
        [first, second],
    )
    finalized = timewarp.finalized_scheduler_packet_for_selection(
        base_packet,
        [
            first[CANDIDATE_OCCURRENCE_KEY_FIELD],
            second[CANDIDATE_OCCURRENCE_KEY_FIELD],
        ],
        current_candidates=[first, second],
        pristine_options_by_occurrence=base_pristine,
    )
    assert set(finalized["decision"]["selected_candidate_instance_keys"]) == (
        first_two_keys
    )


def test_packet_missing_occurrences_form_native_missed_terminal_partition() -> None:
    candidates = [
        _source_safe_occurrence_candidate(
            stop_loss=98.0 - index * 0.25,
        )
        for index in range(3)
    ]
    stages = (
        "missed_zero_selected_window",
        "missed_nonselected_occurrence",
        "selected_order_materialization",
    )
    terminal_rows = [
        timewarp.candidate_packet_missing_terminal_row(
            candidate,
            campaign="unit",
            phase="unit",
            trading_day="2026-05-14",
            decision_time_utc=candidate["decision_time_utc"],
            stage=stage,
        )
        for candidate, stage in zip(candidates, stages, strict=True)
    ]

    candidate_keys = {
        candidate[CANDIDATE_OCCURRENCE_KEY_FIELD] for candidate in candidates
    }
    terminal_keys = {
        row["canonical_replay_candidate_instance_key"] for row in terminal_rows
    }
    assert terminal_keys == candidate_keys
    assert len(terminal_rows) == len(candidate_keys)
    assert {row["candidate_packet_lookup_stage"] for row in terminal_rows} == set(
        stages
    )
    assert all(
        row["terminal_status"] == "NOT_EVALUABLE_CANDIDATE_PACKET_MISSING"
        and row["miss_reason"] == "candidate_occurrence_packet_missing_terminal"
        and row["outcome_not_evaluated"] is True
        and row["final_r"] is None
        and row["net_proxy_r"] is None
        and row["broker_mutation"] is False
        for row in terminal_rows
    )
    binding_terminal = timewarp.candidate_packet_missing_terminal_row(
        candidates[0],
        campaign="unit",
        phase="unit",
        trading_day="2026-05-14",
        decision_time_utc=candidates[0]["decision_time_utc"],
        stage="selected_order_exact_candidate_instance_binding",
        miss_reason=(
            "selected_order_exact_candidate_instance_binding_failed:"
            "duplicate_exact_candidate_instance"
        ),
        terminal_status="NOT_EVALUABLE_SELECTED_ORDER_INSTANCE_BINDING",
    )
    assert binding_terminal["canonical_replay_candidate_instance_key"] in candidate_keys
    assert binding_terminal["outcome_not_evaluated"] is True
    assert binding_terminal["terminal_status"] == (
        "NOT_EVALUABLE_SELECTED_ORDER_INSTANCE_BINDING"
    )
    partition = timewarp.validate_candidate_occurrence_terminal_partition(
        candidates,
        missed_terminal_rows=terminal_rows,
        selected_terminal_instance_keys=(),
    )
    assert partition["status"] == (
        "exact_candidate_occurrence_terminal_multiset_conserved"
    )
    assert partition["input_occurrence_count"] == 3

    with pytest.raises(
        ValueError,
        match="candidate_terminal_partition_multiset_mismatch",
    ):
        timewarp.validate_candidate_occurrence_terminal_partition(
            candidates,
            missed_terminal_rows=terminal_rows[:-1],
            selected_terminal_instance_keys=(),
        )
    tampered = copy.deepcopy(terminal_rows[0])
    tampered["entry_price"] = 101.0
    with pytest.raises(
        ValueError,
        match="candidate_terminal_partition_missed_identity_not_recomputed",
    ):
        timewarp.validate_candidate_occurrence_terminal_partition(
            candidates,
            missed_terminal_rows=[tampered, *terminal_rows[1:]],
            selected_terminal_instance_keys=(),
        )
    with pytest.raises(
        ValueError,
        match="candidate_terminal_partition_selected_occurrence_not_unique",
    ):
        timewarp.validate_candidate_occurrence_terminal_partition(
            candidates,
            missed_terminal_rows=terminal_rows[1:],
            selected_terminal_instance_keys=[
                candidates[0][CANDIDATE_OCCURRENCE_KEY_FIELD],
                candidates[0][CANDIDATE_OCCURRENCE_KEY_FIELD],
            ],
        )


def test_multi_select_option_pending_and_missed_risk_join_exact_occurrence() -> None:
    first = _source_safe_occurrence_candidate(stop_loss=98.0)
    second = _source_safe_occurrence_candidate(stop_loss=97.5)
    first_key = first[CANDIDATE_OCCURRENCE_KEY_FIELD]
    second_key = second[CANDIDATE_OCCURRENCE_KEY_FIELD]

    def option(candidate, marker, input_sequence):
        return {
            "candidate_id": candidate["candidate_id"],
            "symbol": candidate["symbol"],
            "side": candidate["side"],
            "source_type": "new_candidate",
            "input_sequence": input_sequence,
            "decision_time_utc": candidate["decision_time_utc"],
            CANDIDATE_OCCURRENCE_KEY_FIELD: candidate[
                CANDIDATE_OCCURRENCE_KEY_FIELD
            ],
            "canonical_replay_candidate_instance_key": candidate[
                CANDIDATE_OCCURRENCE_KEY_FIELD
            ],
            "candidate_instance_identity_status": "materialized",
            "selector_reason": marker,
            "score_components": {
                "pending_replacement_diagnostic": {
                    "marker": marker,
                    "pending_replacement_causal_quality_gate_status": "passed",
                    "runtime_replacement_applied": True,
                    "runtime_release_pending_ids": [f"pending-{marker}"],
                }
            },
        }

    first_option = option(first, "first", 0)
    second_option = option(second, "second", 1)
    scheduler_packet = timewarp.validate_scheduler_candidate_occurrence_associations({
        "decision": {
            "selected_options": [first_option, second_option],
            "selected_candidate_ids": [
                first["candidate_id"],
                second["candidate_id"],
            ],
            "selected_candidate_instance_keys": [first_key, second_key],
        },
        "all_options_preserved": [first_option, second_option],
    }, [first, second])
    pristine = _unit_scheduler_sidecar(
        scheduler_packet,
        [first, second],
    )
    first_option, second_option = scheduler_packet["all_options_preserved"]

    assert timewarp.selected_scheduler_option(
        scheduler_packet,
        second["candidate_id"],
        decision_time_utc=second["decision_time_utc"],
        candidate_occurrence_key=second_key,
    )["selector_reason"] == "second"
    assert timewarp.selected_scheduler_pending_replacement(
        scheduler_packet,
        second["candidate_id"],
        decision_time_utc=second["decision_time_utc"],
        candidate_occurrence_key=second_key,
    )["marker"] == "second"
    assert timewarp.selected_scheduler_replacement_pending_ids(
        scheduler_packet,
        second["candidate_id"],
        decision_time_utc=second["decision_time_utc"],
        candidate_occurrence_key=second_key,
    ) == ["pending-second"]

    probes = {
        first_key: {
            "candidate_id": first["candidate_id"],
            "risk_decision": "reject",
            "risk_decision_reason": "first_probe",
        },
        second_key: {
            "candidate_id": second["candidate_id"],
            "risk_decision": "reject",
            "risk_decision_reason": "second_probe",
        },
    }
    first_missed = timewarp.risk_finalizer_missed_opportunity_attribution_fields(
        candidate_id=first["candidate_id"],
        decision_time_utc=first["decision_time_utc"],
        candidate_occurrence_key=first_key,
        probe_by_candidate_id=probes,
        original_selected_id_set={first["candidate_id"]},
        original_selected_instance_key_set={second_key},
    )
    second_missed = timewarp.risk_finalizer_missed_opportunity_attribution_fields(
        candidate_id=second["candidate_id"],
        decision_time_utc=second["decision_time_utc"],
        candidate_occurrence_key=second_key,
        probe_by_candidate_id=probes,
        original_selected_id_set={second["candidate_id"]},
        original_selected_instance_key_set={second_key},
    )
    assert first_missed["risk_decision_reason"] == "first_probe"
    assert first_missed["risk_finalizer_preselected_candidate"] is False
    assert second_missed["risk_decision_reason"] == "second_probe"
    assert second_missed["risk_finalizer_preselected_candidate"] is True

    duplicate_second = copy.deepcopy(second_option)
    ambiguous_packet = {
        **scheduler_packet,
        "decision": {
            **scheduler_packet["decision"],
            "selected_options": [second_option, duplicate_second],
        },
    }
    assert timewarp.selected_scheduler_option(
        ambiguous_packet,
        second["candidate_id"],
        decision_time_utc=second["decision_time_utc"],
        candidate_occurrence_key=second_key,
    ) == {}

    options_by_key = {first_key: first_option, second_key: second_option}
    reverse_lexical_rank = sorted(options_by_key, reverse=True)
    ranked_packet = {
        "decision": {
            "selected_options": [
                options_by_key[key] for key in reverse_lexical_rank
            ],
            "selected_candidate_ids": [
                options_by_key[key]["candidate_id"] for key in reverse_lexical_rank
            ],
            "selected_candidate_instance_keys": reverse_lexical_rank,
        },
        "risk_admitted_final_selected_candidate_instance_keys": (
            reverse_lexical_rank
        ),
        "all_options_preserved": [first_option, second_option],
    }
    ranked_pristine = _unit_scheduler_sidecar(
        ranked_packet,
        [first, second],
    )
    assert timewarp.selected_candidate_instance_execution_order(ranked_packet) == (
        reverse_lexical_rank
    )
    disabled_ids, disabled_finalizer = (
        timewarp.finalize_scheduler_risk_admitted_selection(
            scheduler_packet=ranked_packet,
            selected_ids=[
                options_by_key[key]["candidate_id"] for key in reverse_lexical_rank
            ],
            all_candidates=[first, second],
            v4_packets={},
            account=AccountState(),
            day="2026-05-14",
            config={"gtos_vnext_runtime": {}},
            pristine_options_by_occurrence=ranked_pristine,
        )
    )
    assert disabled_ids == [
        options_by_key[key]["candidate_id"] for key in reverse_lexical_rank
    ]
    assert disabled_finalizer["final_selected_candidate_instance_keys"] == (
        reverse_lexical_rank
    )
    pending_markers_in_execution_order = [
        timewarp.selected_scheduler_pending_replacement(
            ranked_packet,
            options_by_key[key]["candidate_id"],
            decision_time_utc=options_by_key[key]["decision_time_utc"],
            candidate_occurrence_key=key,
        )["marker"]
        for key in timewarp.selected_candidate_instance_execution_order(ranked_packet)
    ]
    assert pending_markers_in_execution_order == [
        options_by_key[key]["selector_reason"] for key in reverse_lexical_rank
    ]
    exact_finalized = timewarp.finalized_scheduler_packet_for_selection(
        scheduler_packet,
        [second_key, first_key],
        current_candidates=[first, second],
        pristine_options_by_occurrence=pristine,
    )
    assert exact_finalized["decision"]["selected_candidate_instance_keys"] == [
        second_key,
        first_key,
    ]
    with pytest.raises(
        ValueError,
        match="finalized_scheduler_selection_tokens_not_unique",
    ):
        timewarp.finalized_scheduler_packet_for_selection(
            scheduler_packet,
            [first_key, first_key],
            current_candidates=[first, second],
            pristine_options_by_occurrence=pristine,
        )
    with pytest.raises(
        ValueError,
        match="finalized_scheduler_selection_instance_ambiguous",
    ):
        timewarp.finalized_scheduler_packet_for_selection(
            scheduler_packet,
            [first["candidate_id"]],
            current_candidates=[first, second],
            pristine_options_by_occurrence=pristine,
        )
    duplicate_ranked_packet = copy.deepcopy(ranked_packet)
    duplicate_ranked_packet[
        "risk_admitted_final_selected_candidate_instance_keys"
    ] = [first_key, first_key]
    with pytest.raises(
        ValueError,
        match="finalized_scheduler_selected_instance_order_not_unique",
    ):
        timewarp.selected_candidate_instance_execution_order(
            duplicate_ranked_packet
        )


def test_truth_historical_adapter_attaches_only_causal_successor_witness() -> None:
    rows = tuple(
        {
            "time": stamp,
            "time_utc": stamp,
            "open": 100.0 + index,
            "high": 101.0 + index,
            "low": 99.0 + index,
            "close": 100.5 + index,
            "volume": 10 + index,
        }
        for index, stamp in enumerate(
            (
                "2026-05-13T23:45:00+00:00",
                "2026-05-14T00:00:00+00:00",
                "2026-05-14T00:15:00+00:00",
            )
        )
    )
    source_hash = timewarp.stable_sha256(rows)
    source = ResolvedSource(
        spec=SourceSpec(
            symbol="XAUUSD",
            mapped_symbol="XAUUSD",
            timeframe="M15",
            path=Path("/fixture/XAUUSD_M15.csv"),
            source_family="fixture",
            source_broker="FTMO",
            source_role="owner_authorized_research_hydration",
            row_count=len(rows),
            sha256=source_hash,
        ),
        rows=rows,
        rows_by_day=timewarp.rows_by_day(rows),
        sha256=source_hash,
        day_counts={},
        selected_status="fixture",
        min_required_rows_per_day=1,
    )
    adapter = timewarp.HistoricalMT5Adapter(
        {"XAUUSD": {"M15": source}},
        require_successor_witness=True,
    )
    naive_asof = parse_utc("2026-05-14T00:00:00+00:00").replace(tzinfo=None)
    with pytest.raises(timewarp.SourceTimebaseError, match="replay_context_asof_naive"):
        adapter.set_replay_context(symbol="XAUUSD", asof=naive_asof)
    legacy_adapter = timewarp.HistoricalMT5Adapter(
        {"XAUUSD": {"M15": source}},
        require_successor_witness=False,
    )
    legacy_adapter.set_replay_context(symbol="XAUUSD", asof=naive_asof)
    assert legacy_adapter._asof is not None
    assert legacy_adapter._asof.utcoffset() == timedelta(0)
    adapter.set_replay_context(
        symbol="XAUUSD",
        asof=parse_utc("2026-05-14T00:00:00+00:00"),
    )

    selected = adapter.get_candles("XAUUSD", 15, 10)

    assert len(selected) == 1
    witness = selected[0]["wave21_completed_bar_witness"]
    assert witness["predecessor_source_ordinal"] == 0
    assert witness["successor_source_ordinal"] == 1
    assert witness["successor_open_utc"] == "2026-05-14T00:00:00+00:00"
    assert witness["successor_market_values_consumed"] is False
    assert selected[0]["close"] == 100.5
    assert 101.5 not in selected[0].values()

    adapter.set_replay_context(
        symbol="XAUUSD",
        asof=parse_utc("2026-05-13T23:59:59.999999+00:00"),
    )
    assert adapter.get_candles("XAUUSD", 15, 10) == []

    naive_rows = tuple(
        {**row, "time": str(row["time"]).replace("+00:00", ""),
         "time_utc": str(row["time_utc"]).replace("+00:00", "")}
        for row in rows
    )
    naive_source = ResolvedSource(
        spec=source.spec,
        rows=naive_rows,
        rows_by_day={},
        sha256=source.sha256,
        day_counts={},
        selected_status="fixture",
        min_required_rows_per_day=1,
    )
    naive_adapter = timewarp.HistoricalMT5Adapter(
        {"XAUUSD": {"M15": naive_source}},
        require_successor_witness=True,
    )
    naive_adapter.set_replay_context(
        symbol="XAUUSD",
        asof=parse_utc("2026-05-14T00:00:00+00:00"),
    )
    with pytest.raises(timewarp.SourceTimebaseError, match="row_0_time_utc_naive"):
        naive_adapter.get_candles("XAUUSD", 15, 10)


def test_candidate_sidecar_lookup_fails_closed_when_timed_exact_instance_missing():
    index_by_id = {
        "reused-candidate": 7,
        "reused-candidate@@2026-05-14T00:00:00+00:00": 11,
    }

    exact_index, exact_status = timewarp.candidate_sidecar_index_for_decision(
        index_by_id,
        candidate_id="reused-candidate",
        decision_time_utc="2026-05-14T00:00:00+00:00",
    )
    drift_index, drift_status = timewarp.candidate_sidecar_index_for_decision(
        index_by_id,
        candidate_id="reused-candidate",
        decision_time_utc="2026-05-14T00:30:00+00:00",
    )
    legacy_index, legacy_status = timewarp.candidate_sidecar_index_for_decision(
        index_by_id,
        candidate_id="reused-candidate",
    )

    assert exact_index == 11
    assert exact_status == "exact_candidate_time_sidecar_match"
    assert drift_index is None
    assert drift_status == "exact_candidate_time_sidecar_missing_no_unique_fallback"
    assert legacy_index == 7
    assert legacy_status == "legacy_candidate_id_sidecar_fallback_without_time"


def test_risk_finalizer_ranked_options_prioritize_primary_trade_before_fallback():
    ranked = timewarp.scheduler_ranked_candidate_options(
        {
            "all_options_preserved": [
                {
                    "candidate_id": "higher-score-fallback",
                    "action_class": "new_position",
                    "score": 3.0,
                    "runtime_eligible": True,
                    "selector_action": "open-reduced-risk",
                },
                {
                    "candidate_id": "primary-trade",
                    "action_class": "new_position",
                    "score": 1.0,
                    "runtime_eligible": True,
                    "selector_action": "trade",
                },
            ]
        }
    )

    assert [row["candidate_id"] for row in ranked] == [
        "primary-trade",
        "higher-score-fallback",
    ]
    assert ranked[0]["risk_finalizer_authority_priority_tier"] == 0
    assert ranked[1]["risk_finalizer_authority_priority_tier"] == 1
    assert ranked[1]["scheduler_preserved_rank"] == 1
    assert ranked[0]["risk_finalizer_transfer_rank"] == 1
    assert ranked[1]["risk_finalizer_transfer_rank"] == 2
    assert ranked[1]["scheduler_original_preserved_rank"] == 1


def test_terminal_lifecycle_options_are_not_risk_finalizer_candidates():
    terminal = {
        "candidate_id": "stale-pending-candidate",
        "action_class": "cancel_pending",
        "score": 5.0,
        "runtime_eligible": True,
        "pending_id": "pending-1",
        "selector_action": "reduce-risk",
    }
    ranked = timewarp.scheduler_ranked_candidate_options(
        {
            "all_options_preserved": [
                terminal,
                {
                    "candidate_id": "primary-trade",
                    "action_class": "new_position",
                    "score": 1.0,
                    "runtime_eligible": True,
                    "selector_action": "trade",
                },
            ]
        }
    )

    assert [row["candidate_id"] for row in ranked] == ["primary-trade"]
    assert timewarp.scheduler_option_finalizer_ineligibility_reason(
        terminal,
        min_trade_score=0.25,
    ) == "scheduler_option_terminal_no_new_order_action:cancel_pending"

    assert timewarp.scheduler_option_finalizer_ineligibility_reason(
        {
            "candidate_id": "scale-in-veto",
            "action_class": "same_direction_scale_in",
            "decision_status": (
                "candidate_vetoed_package_lifecycle_scale_in_opportunity_cost_failed"
            ),
            "runtime_eligible": False,
        },
        min_trade_score=0.25,
    ) == (
        "scheduler_option_status_not_executable:"
        "candidate_vetoed_package_lifecycle_scale_in_opportunity_cost_failed"
    )


def test_terminal_lifecycle_selection_rewrites_packet_without_order_candidates():
    packet = {
        "decision": {
            "selected_candidate_id": "stale-pending-candidate",
            "selected_candidate_ids": ["stale-pending-candidate"],
            "selected_action_class": "cancel_pending",
            "selected_option": {
                "candidate_id": "stale-pending-candidate",
                "action_class": "cancel_pending",
                "pending_id": "pending-1",
                "source_type": "pending_order",
                "decision_status": "terminal_pending_cancel_selected",
                "reason": "pending_cancel_threshold_met",
            },
        },
        "runtime_effect_now": False,
        "broker_operation": False,
        "order_calls": 0,
    }

    detail = timewarp.scheduler_terminal_no_new_order_selection_detail(packet)
    rewritten = timewarp.terminal_no_new_order_scheduler_packet(packet, detail)

    assert detail["terminal_no_new_order_selected"] is True
    assert detail["terminal_action"] == "cancel_pending"
    assert detail["selected_pending_id"] == "pending-1"
    assert rewritten["decision"]["selected_candidate_ids"] == []
    assert rewritten["decision"]["selected_candidate_id"] is None
    assert rewritten["decision"]["selected_action_class"] == "cancel_pending"
    assert rewritten["decision"]["terminal_no_new_order_lifecycle_selected"] is True
    assert rewritten["risk_admitted_final_selected_candidate_ids"] == []
    assert rewritten["order_calls"] == 0


