def test_finalizer_admission_rank_requires_exact_broker_cost_authority() -> None:
    base_probe = {
        "risk_admitted": True,
        "package_replay_executable_candidate_use_allowed": True,
        "pretrade_cost_packet_status": "PASSED",
        "cost_source_gap_status": "source_bound_cost_authority_present",
        "candidate_expected_net_r": 1.20,
        "candidate_probability": 0.86,
        "candidate_fill_probability": 0.90,
        "execution_fill_probability": 0.90,
        "execution_fill_probability_source": "predecision_limit_fillability_probability",
        "source_completeness": 1.0,
        "final_approved_risk_pct": 0.25,
        "candidate_id": "rank-cost-authority",
        "decision_time_utc": "2026-04-21T08:00:00+00:00",
    }

    proxy_rank = timewarp.finalizer_admission_rank_fields(
        {
            **base_probe,
            "cost_authority": "timewarp_candidate_cost_proxy",
        }
    )
    broker_rank = timewarp.finalizer_admission_rank_fields(
        {
            **base_probe,
            "cost_authority": "broker_calibrated_replay_cost",
        }
    )

    assert proxy_rank["finalizer_admission_executable_cost_ok"] is False
    assert proxy_rank["finalizer_admission_rank_key"][4] == 1
    assert broker_rank["finalizer_admission_executable_cost_ok"] is True
    assert broker_rank["finalizer_admission_rank_key"][4] == 0


def test_finalizer_admission_rank_values_final_risk_before_signed_soft_category() -> None:
    base = {
        "decision_time_utc": "2026-04-21T08:00:00+00:00",
        "risk_admitted": True,
        "package_replay_executable_candidate_use_allowed": True,
        "pretrade_cost_packet_status": "PASSED",
        "cost_source_gap_status": "source_bound_cost_authority_present",
        "cost_authority": "broker_calibrated_replay_cost",
        "candidate_probability": 0.90,
        "execution_fill_probability": 0.90,
        "execution_fill_probability_source": (
            "predecision_limit_fillability.fill_probability"
        ),
        "execution_fill_probability_authority_class": (
            "predecision_passive_limit_fillability_authority"
        ),
        "execution_fill_probability_source_time_utc": (
            "2026-04-21T07:45:00+00:00"
        ),
        "execution_fill_probability_source_boundary": (
            "asof_candidate_fields_only_no_postdecision_path"
        ),
        "source_completeness": 1.0,
    }
    lower_risk_signed_soft = timewarp.finalizer_admission_rank_fields(
        {
            **base,
            "candidate_id": "lower-risk-signed-soft",
            "candidate_expected_net_r": 1.20,
            "approved_risk_pct": 1.0,
            "scheduler_approved_risk_pct": 0.10,
            "final_approved_risk_pct": 0.10,
            "risk_finalizer_signed_soft_transfer_displacement_allowed": True,
            "risk_finalizer_transfer_dominates_original_allowed": True,
        }
    )
    higher_value_plain = timewarp.finalizer_admission_rank_fields(
        {
            **base,
            "candidate_id": "higher-value-plain",
            "candidate_expected_net_r": 0.90,
            "approved_risk_pct": 0.25,
            "scheduler_approved_risk_pct": 0.25,
            "final_approved_risk_pct": 0.25,
            "risk_finalizer_transfer_dominates_original_allowed": True,
        }
    )

    assert lower_risk_signed_soft[
        "finalizer_admission_expected_transfer_score"
    ] == pytest.approx(0.0972)
    assert higher_value_plain[
        "finalizer_admission_expected_transfer_score"
    ] == pytest.approx(0.18225)
    assert higher_value_plain["finalizer_admission_rank_key"] < lower_risk_signed_soft[
        "finalizer_admission_rank_key"
    ]
    assert lower_risk_signed_soft[
        "finalizer_admission_signed_soft_transfer_displacement_priority"
    ] == 0


