def test_risk_finalizer_primary_probe_alias_prefers_selected_policy_blocked_probe() -> None:
    aliases = timewarp.risk_finalizer_primary_probe_alias_fields(
        {
            "status": "risk_admitted_selection_causal_quality_gate_blocked",
            "probe_rows": [
                {
                    "candidate_id": "first-probe",
                    "decision_time_utc": "2026-04-21T08:00:00+00:00",
                    "selected": False,
                    "status": "risk_admitted_pending_finalizer_rank_selection",
                    "risk_decision": "reduce-risk",
                    "risk_decision_reason": "first_probe_not_the_blocker",
                },
                {
                    "candidate_id": "blocked-policy-probe",
                    "decision_time_utc": "2026-04-21T08:00:00+00:00",
                    "selected": False,
                    "status": "selected_policy_executable_quality_gate_failed",
                    "policy_selection_block_reason": (
                        "selected_policy_executable_quality_gate_failed:"
                        "selected_policy_stop_hazard_pressure_suppressed_uncapped"
                    ),
                    "risk_decision": "reduce-risk",
                    "risk_decision_reason": "unit_test_policy_blocker",
                    "selected_policy_executable_quality_gate_status": "blocked",
                    "selected_policy_executable_quality_gate_failures": [
                        "selected_policy_stop_hazard_pressure_suppressed_uncapped"
                    ],
                    "selected_policy_executable_quality_gate_source_boundary": (
                        "predecision_selected_policy_executable_quality_gate_no_outcome_fields"
                    ),
                    "selected_policy_executable_quality_gate_uses_outcome_fields": False,
                },
            ],
        }
    )

    assert aliases["finalizer_primary_probe_source"] == "policy_blocked_probe"
    assert aliases["finalizer_primary_probe_candidate_id"] == "blocked-policy-probe"
    assert (
        aliases[
            "finalizer_primary_probe_selected_policy_executable_quality_gate_status"
        ]
        == "blocked"
    )
    assert aliases["risk_finalizer_selected_policy_executable_quality_gate_status"] == (
        "blocked"
    )
    assert aliases[
        "finalizer_primary_probe_selected_policy_executable_quality_gate_failures"
    ] == ["selected_policy_stop_hazard_pressure_suppressed_uncapped"]
    assert aliases["risk_finalizer_policy_selection_block_reason"].startswith(
        "selected_policy_executable_quality_gate_failed:"
    )


def test_risk_finalizer_blocks_unresolved_fill_floor_probe_execution() -> None:
    probe = {
        "candidate_id": "unresolved-fill-floor-probe",
        "decision_time_utc": "2026-04-21T08:00:00+00:00",
        "selected": True,
        "status": "risk_admitted_selection_materialized",
        "risk_admitted": True,
        "risk_decision": "reduce-risk",
        "final_approved_risk_pct": 0.25,
        "scheduler_option_package_fill_floor_authority_allowed": False,
        "scheduler_option_package_fill_floor_authority_failures": [
            "fill_probability_below_execution_authority_floor",
            "numeric_disagreement_fill_probability",
        ],
        "scheduler_option_package_fill_floor_authority_raw_failures": [
            "fill_probability_below_execution_authority_floor",
            "numeric_disagreement_fill_probability",
        ],
        "scheduler_option_package_fill_floor_authority_resolved_failures": [],
        "scheduler_option_package_fill_floor_authority_unresolved_failures": [
            "fill_probability_below_execution_authority_floor",
            "numeric_disagreement_fill_probability",
        ],
    }

    assert timewarp.risk_finalizer_probe_executable_finalized(probe) is False
    aliases = timewarp.risk_finalizer_primary_probe_alias_fields(
        {
            "status": "risk_admitted_selection_materialized",
            "probe_rows": [probe],
        }
    )

    assert aliases["finalizer_primary_probe_source"] == "selected_probe"
    assert aliases["finalizer_primary_probe_executable_finalized"] is False
    assert aliases["risk_finalizer_executable_finalized"] is False
    assert aliases["executable_finalized"] is False
    assert aliases[
        "risk_finalizer_scheduler_option_package_fill_floor_authority_raw_failures"
    ] == [
        "fill_probability_below_execution_authority_floor",
        "numeric_disagreement_fill_probability",
    ]
    assert aliases[
        "risk_finalizer_scheduler_option_package_fill_floor_authority_resolved_failures"
    ] == []
    assert aliases[
        "risk_finalizer_scheduler_option_package_fill_floor_authority_unresolved_failures"
    ] == [
        "fill_probability_below_execution_authority_floor",
        "numeric_disagreement_fill_probability",
    ]


def test_finalizer_preflight_preserves_exact_fill_floor_failure_provenance() -> None:
    candidate_id = "fill-floor-preflight-provenance"
    decision_time = "2026-04-21T08:00:00+00:00"
    candidate = {
        **_explicit_package_preflight(
            net=0.69,
            probability=0.74,
            fill=0.86,
            candidate_id=candidate_id,
            decision_time_utc=decision_time,
        ),
        "candle_close_utc": decision_time,
        "symbol": "EURUSD",
        "side": "LONG",
        "entry_price": 1.10,
        "stop_loss": 1.09,
        "take_profit_1": 1.12,
        "selector_action": "trade",
    }
    failure = "expected_net_r"
    scheduler_option = {
        "candidate_id": candidate_id,
        "decision_time_utc": decision_time,
        "selector_action": "trade",
        "action_class": "new_position",
        "scheduler_option_package_fill_floor_authority_allowed": False,
        "scheduler_option_package_fill_floor_authority_failures": [failure],
        "scheduler_option_package_fill_floor_authority_raw_failures": [failure],
        "scheduler_option_package_fill_floor_authority_resolved_failures": [],
        "scheduler_option_package_fill_floor_authority_unresolved_failures": [failure],
        "score_components": {"candidate_decision_inputs": dict(candidate)},
    }

    packet = timewarp.finalizer_pre_order_materialization_preflight(
        candidate=candidate,
        packets={
            "pretrade_broker_net_cost_packet": candidate[
                "pretrade_broker_net_cost_packet"
            ]
        },
        scheduler_packet={"asof_utc": decision_time},
        scheduler_option=scheduler_option,
        risk_authority={"risk_decision": "trade", "final_approved_risk_pct": 0.25},
        account=AccountState(),
        day="2026-04-21",
        config={},
        pending_expiry_minutes=60,
    )

    assert packet["pre_order_materialization_preflight_allowed"] is False
    assert packet["pre_order_materialization_preflight_block_reason"] == (
        "package_fill_floor_unresolved_executable_authority:expected_net_r"
    )
    assert packet["scheduler_option_package_fill_floor_authority_allowed"] is False
    assert packet["scheduler_option_package_fill_floor_authority_failures"] == [failure]
    assert packet["scheduler_option_package_fill_floor_authority_raw_failures"] == [
        failure
    ]
    assert packet[
        "scheduler_option_package_fill_floor_authority_resolved_failures"
    ] == []
    assert packet[
        "scheduler_option_package_fill_floor_authority_unresolved_failures"
    ] == [failure]


