def _soft_cap_scheduler_probe_detail(
    *,
    raw_hard_failures: list[str] | None = None,
) -> dict:
    raw_hard_failures = list(raw_hard_failures or [])
    contract = _soft_capped_selected_policy_gate_surface()
    replacement_quality = {
        **contract["replacement_reallocation_quality"],
        "raw_hard_gate_failures": raw_hard_failures,
        "hard_gate_failures": [
            *raw_hard_failures,
            timewarp.SOFT_CAP_SYNTHETIC_SCORE_FAILURE,
        ],
        "eligible_for_reallocation_promotion": False,
    }
    common = {
        **contract,
        "candidate_id": "soft-cap-probe",
        "action_class": "new_position",
        "expected_net_r": 1.15,
        "probability": 0.84,
        "fill_probability": 0.80,
        "source_completeness": 1.0,
        "source_completeness_status": "complete",
        "source_bound_package_candidate_use_allowed": True,
        "ultimate_package_source_bound_candidate_use_allowed": True,
        "package_replay_executable_candidate_use_allowed": True,
        "package_replay_order_executable_candidate_use_allowed": True,
        "package_new_entry_authority_valid": True,
        "package_new_entry_authority_uses_outcome_fields": False,
        "predecision_stop_hazard_guard_risk_cap_applied": True,
        "predecision_stop_hazard_guard_risk_cap_pct": 0.10,
        "risk_admitted_scheduler_reallocation_score": -0.85,
        "risk_admitted_scheduler_reallocation_eligible": False,
        "risk_admitted_scheduler_reallocation_hard_failures": (
            replacement_quality["hard_gate_failures"]
        ),
        "replacement_reallocation_quality": replacement_quality,
    }
    option = {
        **common,
        "score": -0.01,
        "runtime_eligible": False,
        "decision_status": "candidate_below_trade_score_floor",
        "vetoes": ["scheduler_option_score_below_min_trade_score"],
        "score_components": {"candidate_decision_inputs": dict(common)},
    }
    return timewarp.scheduler_option_soft_veto_replay_probe_detail(
        option,
        candidate=common,
        packets={
            **common,
            "pretrade_broker_net_cost_packet": {
                "status": "PASSED",
                "authority": "broker_calibrated_replay_cost",
                "cost_source_gap_status": "source_bound_cost_authority_present",
                "candidate_cost_r_fallback_is_authority": False,
            },
        },
        ineligibility_detail={
            "status": "scheduler_option_score_below_min_trade_score",
            "primary_runtime_ineligible_reason": (
                "scheduler_option_score_below_min_trade_score"
            ),
            "vetoes": ["scheduler_option_score_below_min_trade_score"],
            "package_reduce_risk_replay_authority_allowed": True,
            "package_fill_floor_authority_unresolved_failures": [],
        },
        min_trade_score=0.35,
    )


