def test_signed_order_stale_selector_alias_enters_soft_probe_then_fill_quality_blocks() -> None:
    option, candidate, packets = _signed_stale_selector_probe_fixture(
        execution_fill_probability=0.035,
    )
    ineligibility = timewarp.scheduler_option_finalizer_ineligibility_detail(
        option,
        min_trade_score=0.35,
    )

    probe = timewarp.scheduler_option_soft_veto_replay_probe_detail(
        option,
        candidate=candidate,
        packets=packets,
        ineligibility_detail=ineligibility,
        min_trade_score=0.35,
        runtime={
            "scheduler_v4_best_trade_allocator_selected_policy_gate_min_execution_fill_probability": 0.80,
        },
    )
    quality = timewarp.selected_policy_executable_quality_gate_fields(
        option,
        option["score_components"]["candidate_decision_inputs"],
        candidate,
        packets,
        runtime={
            "scheduler_v4_best_trade_allocator_selected_policy_gate_min_execution_fill_probability": 0.80,
        },
    )

    assert probe["eligible"] is True
    assert probe["signed_order_executable_route_probe_allowed"] is True
    assert probe["signed_order_stale_selector_alias_probe_allowed"] is True
    assert probe["signed_order_stale_selector_veto_aliases"] == option["vetoes"][1:3]
    assert probe[
        "signed_order_stale_selector_alias_probe_remaining_terminal_vetoes"
    ] == []
    assert quality["selected_policy_executable_quality_gate_status"] == "blocked"
    assert "selected_policy_execution_fill_probability" in quality[
        "selected_policy_executable_quality_gate_failures"
    ]


