def test_stale_selector_alias_requires_complete_current_disposition_contract() -> None:
    option, candidate, packets = _signed_stale_selector_probe_fixture(
        execution_fill_probability=0.92,
    )
    for malformed_disposition in (
        None,
        {
            "schema_version": "signed_order_stale_selector_veto_disposition_v1",
            "applies": False,
            "finalizer_probe_soft_eligible": False,
            "probe_blockers": ["signed_new_entry_authority_invalid"],
            "uses_outcome_fields": False,
        },
    ):
        mutated = copy.deepcopy(option)
        components = mutated["score_components"]
        decision_inputs = components["candidate_decision_inputs"]
        if malformed_disposition is None:
            components.pop("signed_order_stale_selector_veto_disposition", None)
            decision_inputs.pop("signed_order_stale_selector_veto_disposition", None)
        else:
            components["signed_order_stale_selector_veto_disposition"] = dict(
                malformed_disposition
            )
            decision_inputs["signed_order_stale_selector_veto_disposition"] = dict(
                malformed_disposition
            )
        probe = timewarp.scheduler_option_soft_veto_replay_probe_detail(
            mutated,
            candidate=candidate,
            packets=packets,
            ineligibility_detail=(
                timewarp.scheduler_option_finalizer_ineligibility_detail(
                    mutated,
                    min_trade_score=0.35,
                )
            ),
            min_trade_score=0.35,
        )
        assert probe["eligible"] is False
        assert probe["signed_order_stale_selector_alias_probe_allowed"] is False
        assert probe[
            "signed_order_stale_selector_disposition_contract_failures"
        ]


