def test_replay_pending_replacement_aliases_read_flat_and_nested_surfaces():
    option = {
        "candidate_id": "alias-replace",
        "action_class": "replace_pending",
        "same_side_pending_order_ids": ["same-flat-order"],
        "opposite_pending_ids": ["opposite-flat-id"],
        "package_replay_executable_candidate_use_allowed": True,
        "source_bound_package_candidate_use_allowed": True,
        "ultimate_package_source_bound_candidate_use_allowed": True,
        "package_new_entry_authority_valid": True,
        "package_new_entry_authority_uses_outcome_fields": False,
        "package_new_entry_authority_target_action_intent": "replace_pending",
        "pretrade_cost_packet_status": "PASSED",
        "cost_source_gap_status": "source_bound_cost_authority_present",
        "candidate_cost_r_fallback_is_authority": False,
        "score_components": {
            "candidate_decision_inputs": {
                "same_side_pending_ids": ["same-nested-id"],
                "opposite_pending_order_ids": ["opposite-nested-order"],
            },
        },
    }

    diagnostic = timewarp.replay_pending_replacement_diagnostic_from_surfaces(
        option=option,
        candidate={},
        packets={},
    )

    assert diagnostic["runtime_replacement_applied"] is True
    assert diagnostic["reason"] == "package_same_side_pending_duplicate_release"
    assert diagnostic["runtime_release_pending_ids"] == [
        "same-flat-order",
        "same-nested-id",
        "opposite-flat-id",
        "opposite-nested-order",
    ]
    assert diagnostic["same_side_release_pending_ids"] == [
        "same-flat-order",
        "same-nested-id",
    ]
    assert diagnostic["opposite_release_pending_ids"] == [
        "opposite-flat-id",
        "opposite-nested-order",
    ]
    assert diagnostic["live_broker_authority"] is False
    assert diagnostic["final_selection_claim"] is False
    assert timewarp.replacement_pending_ids_from_surfaces(option) == [
        "same-flat-order",
        "same-nested-id",
        "opposite-flat-id",
        "opposite-nested-order",
    ]


