    assert order_surface["package_lifecycle_root_authority"]["applies"] is False
    assert order_surface["package_lifecycle_root_authority_applies"] is False
    assert order_surface["package_lifecycle_root_authority_allowed"] is True
    assert order_surface["package_lifecycle_root_authority_status"] == "not_applicable"


