def test_adaptive_replay_memory_guard_can_disable_broad_origin_side_axis() -> None:
    account = AccountState()
    assert account.closed_trades is not None
    account.closed_trades.extend(
        [
            {
                "symbol": symbol,
                "side": "LONG",
                "session": session,
                "origin_family": "ob_retest",
                "close_time_utc": f"2026-04-2{idx}T13:00:00+00:00",
                "net_r": -1.0,
            }
            for idx, (symbol, session) in enumerate(
                (
                    ("XAUUSD", "london"),
                    ("GBPJPY", "ny"),
                    ("BTCUSD", "ny_broad"),
                )
            )
        ]
    )
    candidate = {
        "candidate_id": "candidate-broad-origin-side-only",
        "symbol": "USDJPY",
        "side": "LONG",
        "session": "ny",
        "origin_family": "ob_retest",
    }
    decision_time = timewarp.parse_utc("2026-04-23T14:00:00+00:00")

    broad = timewarp.build_adaptive_replay_memory_guard(
        candidate=candidate,
        account=account,
        decision_time=decision_time,
        limits={
            "adaptive_replay_memory_guard_enabled": True,
            "adaptive_replay_memory_guard_min_trades": 3,
            "adaptive_replay_memory_guard_max_net_r": -2.0,
            "adaptive_replay_memory_guard_min_loss_rate": 0.60,
            "adaptive_replay_memory_guard_lookback_days": 30,
            "adaptive_replay_memory_guard_allow_origin_side_axis": True,
        },
    )
    narrow = timewarp.build_adaptive_replay_memory_guard(
        candidate=candidate,
        account=account,
        decision_time=decision_time,
        limits={
            "adaptive_replay_memory_guard_enabled": True,
            "adaptive_replay_memory_guard_min_trades": 3,
            "adaptive_replay_memory_guard_max_net_r": -2.0,
            "adaptive_replay_memory_guard_min_loss_rate": 0.60,
            "adaptive_replay_memory_guard_lookback_days": 30,
            "adaptive_replay_memory_guard_allow_origin_side_axis": False,
        },
    )

    assert broad["status"] == "blocked"
    assert broad["matched_axis_id"] == "origin_side"
    assert narrow["status"] == "clear"
    assert narrow["allow_origin_side_axis"] is False


