    attribution = timewarp.lifecycle_action_attribution_fields(
        candidate={
            "candidate_id": "candidate-stale-risk-action",
            "same_symbol_lifecycle_action": "new_position",
        },
        packets={"lifecycle_packet": {"action": "new_position"}},
        scheduler_option={
            "action_class": "same_direction_scale_in",
            "scheduler_candidate_decision_inputs": {
                "effective_action_intent": "same_direction_scale_in"
            },
        },
        risk_authority={"same_symbol_lifecycle_action": "new_position"},
    )

    assert attribution["risk_lifecycle_action"] == "new_position"
    assert attribution["scheduler_reconciled_lifecycle_action"] == (
        "same_direction_scale_in"
    )
    assert attribution["risk_lifecycle_action_stale_for_scheduler"] is True
    assert attribution["lifecycle_action"] == "same_direction_scale_in"
    assert attribution["same_symbol_lifecycle_action"] == "same_direction_scale_in"


