def test_execution_manager_blocks_source_required_lifecycle_with_replay_reconcile_without_broker_truth() -> None:
    decision = type(
        "ExecutionDecision",
        (),
        {
            "should_block": True,
            "fatal_reasons": [
                "same_symbol_lifecycle_v4_not_permitted:source_required_fail_closed"
            ],
        },
    )()

    admission = timewarp.execution_manager_replay_admission(
        execution_decision=decision,
        config={
            "broad_live_as_if_replay_harness": {
                "live_broker_authority": False,
                "broker_mutation_enabled": False,
                "final_selection_claim": False,
            }
        },
        risk_authority={
            "same_symbol_lifecycle_permission_reconcile_applied": True,
            "source_required_package_risk_lifecycle_reconcile": {"applied": True},
        },
    )

    assert admission["replay_should_block"] is True
    assert admission["live_should_block"] is True
    assert admission["replay_override_applied"] is False
    assert admission["status"] == "execution_manager_replay_block_applied"
    assert admission["live_promotion_blocker_reasons"] == []
    assert admission["replay_blocking_reasons"] == [
        "same_symbol_lifecycle_v4_not_permitted:source_required_fail_closed"
    ]
    assert admission["replay_demoted_live_promotion_blocker_reasons"] == []
    assert admission["source_required_broker_lifecycle_truth_satisfied"] is False


