def test_package_marketable_immediate_route_contract_blocks_limit_first_fallback() -> None:
    contract = timewarp.package_marketable_immediate_route_contract(
        risk_authority={
            "package_marketable_entry_guard_status": (
                "routed_to_immediate_marketable_limit_replay_order_policy"
            ),
            "package_marketable_entry_guard_reason": (
                "package_marketable_limit_entry_routed_to_immediate_marketable_limit"
            ),
        },
        immediate_marketable_fill_metadata={
            "limit_immediate_marketable_fill_at_decision_applied": False,
            "limit_immediate_marketable_fill_at_decision_reason": (
                "missing_source_safe_predecision_marketable_price_source_time"
            ),
        },
        fallback_applied=False,
        fallback_contract_unmet=False,
    )

    assert contract["routed_immediate"] is True
    assert contract["immediate_applied"] is False
    assert contract["unmet"] is True
    assert contract["status"] == "unmet"
    assert contract["reason"] == (
        "package_marketable_immediate_route_contract_unmet:"
        "missing_source_safe_predecision_marketable_price_source_time"
    )


