def test_runtime_risk_package_order_cap_release_inherits_decision_time_cap_release() -> None:
    decision_time = "2026-04-21T00:15:00+00:00"
    account = AccountState()
    account.record_accepted_risk_order(
        "2026-04-21",
        risk_pct=0.25,
        decision_time_key=decision_time,
    )
