def test_build_selector_event_splits_entry_quality_from_limit_fillability() -> None:
    event = timewarp.build_selector_event(
        candidate={
            "candidate_id": "candidate-split-fillability",
            "symbol": "XAGUSD",
            "side": "LONG",
            "entry_price": 87.055,
            "stop_loss": 86.68125,
            "source_fields": {
                "current_price": 87.055,
                "current_price_source": "latest_closed_m15_close",
                "current_price_source_boundary": (
                    "closed_m15_predecision_asof_no_postdecision_path"
                ),
                "current_price_source_time_utc": "2026-05-13T13:00:00+00:00",
                "atr14": 0.327,
            },
        },
        probability_record={
            "theses": [{"action": "BUY", "probability": 0.62, "EV": 1.15}]
        },
        lifecycle_packet={},
        risk_pct=1.0,
        cost_r=0.05,
        pretrade_cost_packet={
            "status": "PASSED",
            "total_cost_r": 0.05,
            "authority": "broker_calibrated_replay_cost",
            "cost_source_gap_status": "source_bound_cost_authority_present",
        },
        asof_utc="2026-05-13T13:15:00+00:00",
        mso=None,
    )

    assert event["predecision_limit_fillability"]["limit_marketable_at_decision"] is True
    assert event["limit_fillability_probability"] == 0.92
    assert event["execution_fill_probability"] == 0.92
    assert event["execution_fill_probability_source"] == (
        "predecision_limit_fillability.fill_probability"
    )
    assert event["execution_fill_probability_source_time_utc"] == (
        "2026-05-13T13:00:00+00:00"
    )
    assert event["execution_fill_probability_source_boundary"] == (
        "closed_m15_predecision_asof_no_postdecision_path"
    )
    assert event.get("execution_fillability_atomic_failure") is None
    assert event["fill_probability"] == event["entry_quality_fill_probability"]
    assert event["fill_probability"] != event["limit_fillability_probability"]
    for inputs_key in (
        "candidate_decision_inputs",
        "scheduler_candidate_decision_inputs",
    ):
        decision_inputs = event[inputs_key]
        assert decision_inputs["execution_fill_probability"] == 0.92
        assert decision_inputs["execution_fill_probability_source_time_utc"] == (
            "2026-05-13T13:00:00+00:00"
        )
        assert decision_inputs.get("execution_fillability_atomic_failure") is None


