def test_package_quality_release_reuses_one_exact_common_across_prefixes(
    monkeypatch,
) -> None:
    candidate = {
        "candidate_id": "candidate-shared-quality-release-common",
        "symbol": "AUDUSD",
        "side": "LONG",
        "ultimate_package_source_bound_candidate_use_allowed": True,
        "ultimate_package_admission_sleeve_match_count": 1.0,
        "ultimate_package_combined_source_bound_signal_r_sum": 1200.0,
    }
    packets = {
        "candidate_ev_r": 1.20,
        "candidate_probability": 0.90,
        "fill_probability": 0.91,
        "broker_calibrated_expected_cost_r": 0.05,
        "pretrade_broker_net_cost_packet": {
            "status": "PASSED",
            "total_cost_r": 0.05,
            "authority": "broker_calibrated_replay_cost",
            "cost_source_gap_status": "source_bound_cost_authority_present",
        },
    }
    scheduler_option = {
        "candidate_id": candidate["candidate_id"],
        "score": 3.8,
        "score_components": {
            "candidate_decision_inputs": {
                "ev_r": 1.20,
                "expected_net_r": 1.15,
                "probability": 0.90,
                "fill_probability": 0.91,
                "source_completeness": 1.0,
            }
        },
    }
    limits: dict[str, object] = {}
    prefixes = (
        "package_marketable_entry_guard_replay_route",
        "package_cooldown_release",
    )
    expected = [
        timewarp.package_candidate_quality_release_packet(
            candidate=candidate,
            packets=packets,
            scheduler_option=scheduler_option,
            limits=limits,
            prefix=prefix,
        )
        for prefix in prefixes
    ]
    quality_calls = 0
    signal_calls = 0
    original_quality = timewarp._scheduler_option_quality_inputs
    original_signal = timewarp.ultimate_package_effective_signal_fields

    def counted_quality(*args, **kwargs):
        nonlocal quality_calls
        quality_calls += 1
        return original_quality(*args, **kwargs)

    def counted_signal(*args, **kwargs):
        nonlocal signal_calls
        signal_calls += 1
        return original_signal(*args, **kwargs)

    monkeypatch.setattr(
        timewarp,
        "_scheduler_option_quality_inputs",
        counted_quality,
    )
    monkeypatch.setattr(
        timewarp,
        "ultimate_package_effective_signal_fields",
        counted_signal,
    )
    common = timewarp.package_candidate_quality_release_common(
        candidate=candidate,
        packets=packets,
        scheduler_option=scheduler_option,
        limits=limits,
    )
    actual = [
        timewarp.package_candidate_quality_release_packet(
            candidate=candidate,
            packets=packets,
            scheduler_option=scheduler_option,
            limits=limits,
            prefix=prefix,
            common=common,
        )
        for prefix in prefixes
    ]

    assert actual == expected
    # One direct quality projection plus the distinct merged-seed projection;
    # neither is repeated for the second release prefix.
    assert quality_calls == 2
    # Effective-signal and authority-context projections are each computed
    # once; neither is repeated for the second release prefix.
    assert signal_calls == 2


