def test_order_policy_risk_action_does_not_use_tampered_signed_authority() -> None:
    candidate_id = "order-policy-tampered-action"
    decision_time = "2026-05-01T10:00:00+00:00"
    instance_key = f"{candidate_id}@@{decision_time}"
    tampered = {
        "candidate_id": candidate_id,
        "decision_time_utc": decision_time,
        "canonical_replay_candidate_instance_key": instance_key,
        "source_bound_replay_candidate_instance_key": instance_key,
        "candidate_instance_identity_status": "materialized",
        "selector_action": "open-reduced-risk",
        "package_new_entry_authority_valid": True,
        "package_new_entry_authority_status": (
            "valid_signed_predecision_new_entry_authority"
        ),
        "package_new_entry_authority_hash_sha256": "0" * 64,
        "expected_package_new_entry_authority_hash_sha256": "0" * 64,
        "package_new_entry_authority_payload": {
            "candidate_id": candidate_id,
            "decision_time_utc": decision_time,
            "canonical_replay_candidate_instance_key": instance_key,
            "source_bound_replay_candidate_instance_key": instance_key,
            "candidate_instance_identity_status": "materialized",
            "selector_action": "open-reduced-risk",
            "target_action_intent": "new_position",
            "authority_applies": True,
            "authority_allowed": True,
        },
    }

    authority = timewarp.order_policy_risk_action_authority(
        tampered,
        mutable_risk_decision="trade",
    )

    assert authority["signed_reduced_authority_valid"] is False
    assert authority["signed_reduced_selector_action"] is None
    assert authority["effective_risk_action"] == "trade"
    assert authority["effective_risk_action_source"] == (
        "mutable_runtime_risk_decision"
    )


