def test_finalizer_admission_rank_demotes_degraded_passive_queue_without_transfer_dominance() -> None:
    base_probe = {
        "risk_admitted": True,
        "package_replay_executable_candidate_use_allowed": True,
        "pretrade_cost_packet_status": "PASSED",
        "cost_source_gap_status": "source_bound_cost_authority_present",
        "cost_authority": "broker_calibrated_replay_cost",
        "candidate_expected_net_r": 1.0,
        "candidate_probability": 0.9,
        "execution_fill_probability": 0.8,
        "source_completeness": 1.0,
        "final_approved_risk_pct": 0.25,
    }
    primary_rank = timewarp.finalizer_admission_rank_fields(
        {**base_probe, "candidate_id": "primary"}
    )
    degraded_rank = timewarp.finalizer_admission_rank_fields(
        {
            **base_probe,
            "candidate_id": "degraded",
            "candidate_expected_net_r": 3.0,
            "passive_limit_fallback_envelope_degraded_to_passive_queue": True,
        }
    )
    dominating_degraded_rank = timewarp.finalizer_admission_rank_fields(
        {
            **base_probe,
            "candidate_id": "dominates",
            "candidate_expected_net_r": 3.0,
            "passive_limit_fallback_envelope_degraded_to_passive_queue": True,
            "risk_finalizer_transfer_dominates_original_allowed": True,
        }
    )

    assert (
        primary_rank["finalizer_admission_rank_key"]
        < degraded_rank["finalizer_admission_rank_key"]
    )
    assert (
        degraded_rank[
            "finalizer_admission_passive_limit_fallback_degraded_rank_penalty"
        ]
        == 1
    )
    assert (
        dominating_degraded_rank[
            "finalizer_admission_passive_limit_fallback_degraded_rank_penalty"
        ]
        == 0
    )
    assert (
        dominating_degraded_rank["finalizer_admission_rank_key"]
        < primary_rank["finalizer_admission_rank_key"]
    )


