def test_zeroed_window_missed_reason_uses_finalizer_probe_reason() -> None:
    reason = timewarp.missed_reason_for_scheduler_nonselection(
        candidate_id="candidate-finalizer-probed",
        scheduler_option={
            "decision_status": "candidate_ranked",
            "reason": "candidate_ranked_against_window",
        },
        original_selected_id_set=set(),
        final_selected_id_set=set(),
        scheduler_zeroed_window=True,
        risk_finalizer_probe={
            "risk_decision_reason": "same_symbol_daily_loss_lockout_after_closed_trade"
        },
    )

    assert reason == (
        "risk_finalizer_rejected_nonpreselected_candidate:"
        "same_symbol_daily_loss_lockout_after_closed_trade"
    )
    assert timewarp.missed_reason_for_scheduler_nonselection(
        candidate_id="candidate-legacy-zero",
        scheduler_option={
            "decision_status": "candidate_ranked",
            "reason": "candidate_ranked_against_window",
        },
        original_selected_id_set=set(),
        final_selected_id_set=set(),
        scheduler_zeroed_window=True,
    ) == "scheduler_zero_trade_window_candidate_not_preselected"


def test_nonzero_window_missed_reason_uses_finalizer_probe_reason() -> None:
    reason = timewarp.missed_reason_for_scheduler_nonselection(
        candidate_id="candidate-finalizer-probed",
        scheduler_option={
            "decision_status": "candidate_ranked",
            "reason": "candidate_ranked_against_window",
        },
        original_selected_id_set=set(),
        final_selected_id_set={"different-selected-candidate"},
        scheduler_zeroed_window=False,
        risk_finalizer_probe={
            "risk_decision": "reject",
            "risk_decision_reason": "decision_time_risk_order_cap_exhausted",
        },
    )

    assert reason == (
        "risk_finalizer_rejected_nonpreselected_candidate:"
        "decision_time_risk_order_cap_exhausted"
    )
    assert timewarp.missed_reason_for_scheduler_nonselection(
        candidate_id="candidate-competed",
        scheduler_option={
            "decision_status": "candidate_ranked",
            "reason": "candidate_ranked_against_window",
        },
        original_selected_id_set=set(),
        final_selected_id_set={"different-selected-candidate"},
        scheduler_zeroed_window=False,
    ) == "scheduler_selected_competing_candidate"

    assert timewarp.missed_reason_for_scheduler_nonselection(
        candidate_id="scale-in-vetoed",
        scheduler_option={
            "decision_status": (
                "candidate_vetoed_package_lifecycle_scale_in_opportunity_cost_failed"
            ),
            "reason": "package_lifecycle_scale_in_opportunity_cost_below_comparator",
            "vetoes": [
                (
                    "package_lifecycle_scale_in_opportunity_cost_failed:"
                    "better_new_position_predecision_edge"
                )
            ],
        },
        original_selected_id_set=set(),
        final_selected_id_set=set(),
        scheduler_zeroed_window=False,
    ) == (
        "scheduler_vetoed_candidate_"
        "package_lifecycle_scale_in_opportunity_cost"
    )

    assert timewarp.missed_reason_for_scheduler_nonselection(
        candidate_id="replace-pending-fill-floor-vetoed",
        scheduler_option={
            "decision_status": "candidate_vetoed_package_fill_floor_quality_failed",
            "reason": (
                "package_fill_floor_quality_failed:"
                "package_fill_floor_authority_invalid:"
                "invalid_package_fill_floor_authority:"
                "package_fill_floor_quality_not_met:execution_fill_probability"
            ),
            "vetoes": [
                "package_lifecycle_root_authority_not_allowed:"
                "signed_package_lifecycle_authority_invalid",
            ],
        },
        original_selected_id_set=set(),
        final_selected_id_set=set(),
        scheduler_zeroed_window=False,
    ) == "scheduler_vetoed_candidate_package_fill_floor_quality_non_executable"

    assert timewarp.missed_reason_for_scheduler_nonselection(
        candidate_id="rank-limited-soft-authority",
        scheduler_option={
            "decision_status": (
                "candidate_rank_limited_package_displacement_quality_below_primary"
            ),
            "reason": "package_soft_authority_edge_below_primary",
        },
        original_selected_id_set=set(),
        final_selected_id_set={"stronger-primary"},
        scheduler_zeroed_window=False,
    ) == "scheduler_rank_limited_package_displacement_quality_below_primary"


def test_preselected_missed_reason_exposes_terminal_finalizer_policy_block() -> None:
    reason = timewarp.missed_reason_for_scheduler_nonselection(
        candidate_id="candidate-preselected-positive-risk",
        scheduler_option={
            "decision_status": "candidate_admitted_reduced_risk",
            "reason": "risk_reduced_to_window_headroom",
        },
        original_selected_id_set={"candidate-preselected-positive-risk"},
        final_selected_id_set=set(),
        scheduler_zeroed_window=True,
        risk_finalizer_probe={
            "risk_decision": "reduce-risk",
            "risk_decision_reason": (
                "scheduler_approved_risk_below_selected_cell_risk_preserved"
            ),
            "policy_selection_block_reason": (
                "selected_policy_executable_quality_gate_failed:"
                "selected_policy_execution_fill_probability,"
                "selected_policy_limit_fill_probability"
            ),
        },
    )

    assert reason == (
        "risk_finalizer_rejected_preselected_candidate:"
        "selected_policy_executable_quality_gate_failed:"
        "selected_policy_execution_fill_probability,"
        "selected_policy_limit_fill_probability"
    )


