def test_repeated_signed_authority_validation_reuses_frozen_payload_hash(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    scheduler.clear_package_new_entry_authority_payload_hash_cache()
    candidate, _, _ = _signed_open_reduced_order_authority_fixture(
        candidate_id="repeated-frozen-authority-validation",
    )
    authority_field = candidate["package_new_entry_authority_authority_field"]
    authority_payload = candidate[authority_field][
        "package_new_entry_authority_payload"
    ]
    assert copy.deepcopy(authority_payload) is authority_payload

    original_stable_sha256 = scheduler._stable_sha256
    calls = 0
    calls_by_caller: dict[str, int] = {}
    calls_by_hash_consumer: dict[str, int] = {}
    payload_types: dict[str, int] = {}
    payload_ids: set[int] = set()
    digest_counts: dict[str, int] = {}

    def counted_stable_sha256(payload: object) -> str:
        nonlocal calls
        calls += 1
        caller = sys._getframe(1).f_code.co_name
        calls_by_caller[caller] = calls_by_caller.get(caller, 0) + 1
        hash_consumer = sys._getframe(2).f_code.co_name
        calls_by_hash_consumer[hash_consumer] = (
            calls_by_hash_consumer.get(hash_consumer, 0) + 1
        )
        payload_type = type(payload).__name__
        payload_types[payload_type] = payload_types.get(payload_type, 0) + 1
        payload_ids.add(id(payload))
        digest = original_stable_sha256(payload)
        digest_counts[digest] = digest_counts.get(digest, 0) + 1
        return digest

    monkeypatch.setattr(scheduler, "_stable_sha256", counted_stable_sha256)

    validations = [
        timewarp.existing_signed_reduced_package_new_entry_authority_validation(
            candidate=candidate,
            packets={},
            selector_action="open-reduced-risk",
            selector_reason=candidate["selector_reason"],
            action_intent="new_position",
            components={"candidate_decision_inputs": candidate},
            prefer_candidate_selected_authority=True,
        )
        for _ in range(3)
    ]

    assert all(validation["valid"] is True for validation in validations)
    assert all(
        validation["package_new_entry_authority_payload"] is authority_payload
        for validation in validations
    )
    assert calls == 0, (
        calls_by_caller,
        calls_by_hash_consumer,
        payload_types,
        len(payload_ids),
        len(digest_counts),
        sorted(digest_counts.values(), reverse=True)[:10],
    )


