@pytest.mark.parametrize(
    "validator_name",
    (
        "existing_signed_reduced_package_new_entry_authority_validation",
        "signed_reduced_package_new_entry_authority_validation",
    ),
)
@pytest.mark.parametrize(
    ("atom", "current_value"),
    (
        ("selected_policy_expected_net_calibration_status", "uncalibrated"),
        (
            "selected_policy_expected_net_calibration_status",
            "selected_policy_expected_net_calibration_missing",
        ),
        ("selected_policy_expected_net_calibration_required", "false"),
    ),
)
def test_signed_authority_projection_rejects_negative_selected_policy_calibration_atoms(
    validator_name: str,
    atom: str,
    current_value: str,
) -> None:
    candidate, packets, scheduler_option = _signed_open_reduced_order_authority_fixture(
        candidate_id=f"negative-selected-policy-calibration-{validator_name}-{atom}",
        canonical_selected_policy_calibration=True,
    )
    signed_payload = candidate[
        "ultimate_candidate_package_open_reduced_risk_authority"
    ]["package_new_entry_authority_payload"]
    assert signed_payload["selected_policy_expected_net_calibration_status"] == (
        "calibrated"
    )
    assert signed_payload["selected_policy_expected_net_calibration_required"] is True

    components = copy.deepcopy(scheduler_option["score_components"])
    components["candidate_decision_inputs"][atom] = current_value
    validator = getattr(timewarp, validator_name)
    validation = validator(
        candidate=candidate,
        packets=packets,
        selector_action="open-reduced-risk",
        selector_reason=candidate["selector_reason"],
        action_intent="new_position",
        components=components,
    )

    expected_failure = f"current_signed_authority_projection_mismatch:{atom}"
    projection_failures = {
        failure
        for failure in validation["failures"]
        if failure.startswith("current_signed_authority_projection_mismatch:")
    }
    assert validation["valid"] is False
    assert projection_failures == {expected_failure}


def test_existing_signed_authority_rejects_atomic_cost_and_dual_fill_projection_drift() -> None:
    candidate, packets, scheduler_option = _signed_open_reduced_order_authority_fixture(
        candidate_id="existing-signed-atomic-cost-dual-fill"
    )
    signed_payload = candidate[
        "ultimate_candidate_package_open_reduced_risk_authority"
    ]["package_new_entry_authority_payload"]
    bound_atoms = (
        "expected_cost_r",
        "cost_atomic_conflicts",
        "entry_quality_fill_probability",
        "execution_fill_probability",
        "limit_fillability_probability",
        "predecision_limit_fillability_probability",
    )
    assert all(atom in signed_payload for atom in bound_atoms)

    baseline = timewarp.existing_signed_reduced_package_new_entry_authority_validation(
        candidate=candidate,
        packets=packets,
        selector_action="open-reduced-risk",
        selector_reason=candidate["selector_reason"],
        action_intent="new_position",
        components=scheduler_option["score_components"],
    )
    assert baseline["valid"] is True, baseline.get("failures")

    mutations = {
        "expected_cost_r": 0.09,
        "cost_atomic_conflicts": ["total_cost_r_vs_expected_cost_r"],
        "entry_quality_fill_probability": 0.81,
        "execution_fill_probability": 0.82,
        "limit_fillability_probability": 0.83,
        "predecision_limit_fillability_probability": 0.84,
    }
    for atom, mutated_value in mutations.items():
        mutated_candidate = copy.deepcopy(candidate)
        mutated_components = copy.deepcopy(scheduler_option["score_components"])
        mutated_candidate[atom] = mutated_value
        mutated_components["candidate_decision_inputs"][atom] = mutated_value

        validation = (
            timewarp.existing_signed_reduced_package_new_entry_authority_validation(
                candidate=mutated_candidate,
                packets=packets,
                selector_action="open-reduced-risk",
                selector_reason=candidate["selector_reason"],
                action_intent="new_position",
                components=mutated_components,
            )
        )

        assert validation["valid"] is False, atom
        assert f"current_signed_authority_projection_mismatch:{atom}" in validation[
            "failures"
        ]


