def test_order_preflight_does_not_rederive_selected_policy_after_valid_signature(
    monkeypatch,
) -> None:
    candidate, packets, scheduler_option = _signed_open_reduced_order_authority_fixture(
        candidate_id="signed-selected-policy-no-late-rederivation",
        canonical_selected_policy_calibration=True,
    )
    surface = timewarp.order_materialization_authority_candidate_surface(
        candidate=candidate,
        packets=packets,
        scheduler_option=scheduler_option,
        risk_authority={},
        config={},
    )
    signed_hash = candidate[
        "ultimate_candidate_package_open_reduced_risk_authority"
    ]["package_new_entry_authority_payload"][
        "selected_policy_expected_net_calibration_hash"
    ]
    assert surface["selected_policy_expected_net_calibration_hash"] == signed_hash

    def unexpected_late_rederivation(**_kwargs):
        raise AssertionError(
            "valid signed selected-policy calibration must not be rederived"
        )

    monkeypatch.setattr(
        timewarp,
        "owner_approved_reconstructed_proxy_selected_policy_expected_net_fields",
        unexpected_late_rederivation,
    )
    reason = timewarp.replay_order_materialization_authority_block_reason(
        candidate=surface,
        packets=packets,
        config={
            "gtos_vnext_runtime": {
                "broad_live_as_if_replay_owner_approved_reconstructed_proxy_selected_policy_expected_net_enabled": True,
                "broad_live_as_if_replay_owner_approved_reconstructed_proxy_selected_policy_expected_net_boundary": (
                    "unit_test_late_rederivation_must_not_replace_signed_hash"
                ),
            }
        },
    )

    assert reason is None
    assert timewarp.package_new_entry_authority_attribution_fields(surface)[
        "package_new_entry_authority_valid"
    ] is True


def test_order_materialization_preserves_current_order_denial_over_signed_true_triplet() -> None:
    candidate, packets, scheduler_option = _signed_open_reduced_order_authority_fixture(
        candidate_id="current-order-denial-over-signed-allow"
    )
    signed_payload = candidate[
        "ultimate_candidate_package_open_reduced_risk_authority"
    ]["package_new_entry_authority_payload"]
    assert signed_payload["package_replay_order_executable_candidate_use_allowed"] is True
    current_reason = "current_lifecycle_fill_authority_denied_order_materialization"
    current_source = "current_runtime_lifecycle_fill_authority"
    denial_triplet = {
        "package_replay_order_executable_candidate_use_allowed": False,
        "package_replay_order_executable_candidate_use_allowed_reason": current_reason,
        "package_replay_order_executable_authority_source": current_source,
    }
    for denial_owner in ("candidate", "risk_authority"):
        current_candidate = copy.deepcopy(candidate)
        current_risk_authority = {
            "package_replay_order_executable_candidate_use_allowed": True,
            "package_replay_order_executable_candidate_use_allowed_reason": (
                "mutable_risk_alias_allowed"
            ),
        }
        if denial_owner == "candidate":
            current_candidate.update(denial_triplet)
        else:
            current_risk_authority.update(denial_triplet)

        surface = timewarp.order_materialization_authority_candidate_surface(
            candidate=current_candidate,
            packets=packets,
            scheduler_option=scheduler_option,
            risk_authority=current_risk_authority,
            config={},
        )

        assert surface["package_replay_order_executable_candidate_use_allowed"] is False
        assert surface[
            "package_replay_order_executable_candidate_use_allowed_reason"
        ] == current_reason
        assert surface["package_replay_order_executable_authority_source"] == current_source
        assert surface[
            "order_materialization_current_denial_preserved_over_signed_allow"
        ] is True
        for projection_field, payload_field in (
            (
                "package_new_entry_authority_package_replay_order_executable_candidate_use_allowed",
                "package_replay_order_executable_candidate_use_allowed",
            ),
            (
                "package_new_entry_authority_package_replay_order_executable_candidate_use_allowed_reason",
                "package_replay_order_executable_candidate_use_allowed_reason",
            ),
            (
                "package_new_entry_authority_package_replay_order_executable_authority_source",
                "package_replay_order_executable_authority_source",
            ),
        ):
            assert surface[projection_field] == signed_payload[payload_field]
        assert timewarp.replay_order_materialization_authority_block_reason(
            candidate=surface,
            packets=packets,
            config={"gtos_vnext_runtime": {}},
        ) == f"package_replay_order_executable_candidate_use_not_allowed:{current_reason}"


