def test_accepted_risk_counter_releases_same_decision_cluster_side() -> None:
    account = AccountState()
    day = "2026-05-01"
    decision_time_key = "2026-05-01T14:15:00+00:00"

    account.record_accepted_risk_order(
        day,
        0.5,
        decision_time_key=decision_time_key,
        decision_cluster_key="us_index",
        decision_side="LONG",
    )
    assert (
        account.accepted_risk_order_count_for_decision_cluster_side(
            day,
            decision_time_key,
            "us_index",
            "LONG",
        )
        == 1
    )

    release = account.release_accepted_risk_order(
        day,
        0.5,
        decision_time_key=decision_time_key,
        decision_cluster_key="us_index",
        decision_side="LONG",
    )

    assert release["same_decision_cluster_side_key"].endswith("/us_index/LONG")
    assert release[
        "same_decision_cluster_side_accepted_risk_order_count_before_release"
    ] == 1
    assert release[
        "same_decision_cluster_side_accepted_risk_order_count_after_release"
    ] == 0
    assert (
        account.accepted_risk_order_count_for_decision_cluster_side(
            day,
            decision_time_key,
            "us_index",
            "LONG",
        )
        == 0
    )


def test_runtime_risk_authority_blocks_same_decision_cluster_side_burst() -> None:
    account = AccountState()
    day = "2026-05-01"
    decision_time_key = "2026-05-01T14:15:00+00:00"
    account.record_accepted_risk_order(
        day,
        1.0,
        decision_time_key=decision_time_key,
        decision_cluster_key="us_index",
        decision_side="LONG",
    )
    candidate = _runtime_burst_guard_candidate("candidate-nas100-burst")

    packet = build_runtime_risk_authority(
        candidate=candidate,
        packets=_runtime_burst_guard_packets(),
        scheduler_packet=_runtime_burst_guard_scheduler_packet(
            "candidate-nas100-burst"
        ),
        account=account,
        day=day,
        config=_runtime_burst_guard_config(),
    )

    assert packet["risk_decision"] == "reject"
    assert packet["risk_decision_reason"] == "same_decision_cluster_burst_guard"
    assert packet["same_decision_cluster_side_risk_order_guard_applies"] is True
    assert packet["same_decision_cluster_side_burst_guard_blocked"] is True
    assert packet["same_decision_cluster_side_risk_order_cluster"] == "us_index"
    assert packet["same_decision_cluster_side_accepted_risk_order_count_before"] == 1


def test_runtime_risk_authority_allows_same_decision_cluster_side_bypass_authority() -> None:
    account = AccountState()
    day = "2026-05-01"
    decision_time_key = "2026-05-01T14:15:00+00:00"
    account.record_accepted_risk_order(
        day,
        1.0,
        decision_time_key=decision_time_key,
        decision_cluster_key="us_index",
        decision_side="LONG",
    )
    candidate = _runtime_burst_guard_candidate("candidate-nas100-authorized-burst")

    packet = build_runtime_risk_authority(
        candidate=candidate,
        packets=_runtime_burst_guard_packets(),
        scheduler_packet=_runtime_burst_guard_scheduler_packet(
            "candidate-nas100-authorized-burst",
            bypass=True,
        ),
        account=account,
        day=day,
        config=_runtime_burst_guard_config(),
    )

    assert packet["risk_decision"] in {"trade", "reduce-risk"}
    assert packet["risk_decision_reason"] != "same_decision_cluster_burst_guard"
    assert packet[
        "same_decision_cluster_side_burst_guard_explicit_authority_allowed"
    ] is True
    assert packet["same_decision_cluster_side_burst_guard_blocked"] is False


