def test_order_time_same_cluster_recompute_defers_to_finalizer_selected_authority() -> None:
    risk_authority = {
        "risk_decision": "trade",
        "risk_decision_reason": "risk_ok",
        "final_approved_risk_pct": 0.50,
        "same_decision_cluster_side_burst_guard_blocked": False,
        "risk_finalizer_execution_authority_reused": True,
    }
    finalizer_risk_authority = {
        "selected": True,
        "risk_decision": "trade",
        "risk_decision_reason": "risk_ok",
        "final_approved_risk_pct": 0.50,
        "same_decision_cluster_side_burst_guard_blocked": False,
    }
    recomputed_fields = {
        "same_decision_cluster_side_risk_order_counter_key": (
            "2026-05-01T14:15:00+00:00/us_index/LONG"
        ),
        "same_decision_cluster_side_accepted_risk_order_count_before": 1,
        "same_decision_cluster_side_risk_order_limit": 1,
        "same_decision_cluster_side_risk_order_cap_exhausted": True,
        "same_decision_cluster_side_burst_guard_blocked": True,
    }

    packet = timewarp._apply_order_time_same_cluster_guard_recompute(
        risk_authority=risk_authority,
        recomputed_guard_fields=recomputed_fields,
        recomputed_blocked=True,
        finalizer_risk_authority=finalizer_risk_authority,
    )

    assert packet["risk_decision"] == "trade"
    assert packet["risk_decision_reason"] == "risk_ok"
    assert packet["final_approved_risk_pct"] == 0.50
    assert packet["same_decision_cluster_side_burst_guard_blocked"] is False
    assert (
        packet[
            "runtime_recomputed_same_decision_cluster_side_burst_guard_blocked"
        ]
        is True
    )
    assert (
        packet[
            "runtime_recomputed_same_decision_cluster_side_guard_deferred_to_finalizer"
        ]
        is True
    )
    assert (
        packet[
            "risk_finalizer_execution_authority_reused_overrode_recomputed_same_decision_cluster_side_guard"
        ]
        is True
    )
    assert (
        "risk_finalizer_execution_authority_reused_blocked_by_runtime_same_decision_cluster_side_guard"
        not in packet
    )


def test_order_time_same_cluster_recompute_rejects_without_finalizer_selected_authority() -> None:
    risk_authority = {
        "risk_decision": "trade",
        "risk_decision_reason": "risk_ok",
        "final_approved_risk_pct": 0.50,
    }
    recomputed_fields = {
        "same_decision_cluster_side_accepted_risk_order_count_before": 1,
        "same_decision_cluster_side_burst_guard_blocked": True,
    }

    packet = timewarp._apply_order_time_same_cluster_guard_recompute(
        risk_authority=risk_authority,
        recomputed_guard_fields=recomputed_fields,
        recomputed_blocked=True,
        finalizer_risk_authority=None,
    )

    assert packet["risk_decision"] == "reject"
    assert packet["risk_decision_reason"] == "same_decision_cluster_burst_guard"
    assert packet["final_approved_risk_pct"] == 0.0
    assert packet["same_decision_cluster_side_burst_guard_blocked"] is True
    assert (
        packet[
            "risk_finalizer_execution_authority_reused_blocked_by_runtime_same_decision_cluster_side_guard"
        ]
        is True
    )


