def test_recent_trade_cooldown_uses_fx_cluster_exposure_direction() -> None:
    account = AccountState()
    account.closed_trades.append(
        {
            "simulated_trade_id": "prior-usdchf-long",
            "candidate_id": "prior-candidate",
            "symbol": "USDCHF",
            "side": "LONG",
            "cluster": "usd_fx",
            "close_time_utc": "2024-01-02T11:45:00+00:00",
            "net_proxy_r": 0.70,
        }
    )
    asof = timewarp.parse_utc("2024-01-02T12:15:00+00:00")

    same_usd_exposure_conflicts = account.recent_trade_cooldown_conflicts(
        candidate={"symbol": "EURUSD", "side": "SHORT"},
        asof=asof,
        cooldown_minutes=90,
        same_symbol_enabled=False,
        same_cluster_opposite_side_enabled=True,
        min_prior_net_r=0.0,
    )
    assert same_usd_exposure_conflicts == []

    opposite_usd_exposure_conflicts = account.recent_trade_cooldown_conflicts(
        candidate={"symbol": "EURUSD", "side": "LONG"},
        asof=asof,
        cooldown_minutes=90,
        same_symbol_enabled=False,
        same_cluster_opposite_side_enabled=True,
        min_prior_net_r=0.0,
    )

    assert len(opposite_usd_exposure_conflicts) == 1
    conflict = opposite_usd_exposure_conflicts[0]
    assert conflict["reason"] == "recent_same_cluster_opposite_side_closed_trade_cooldown"
    assert conflict["prior_cluster_exposure_side"] == "USD_LONG"
    assert conflict["candidate_cluster_exposure_side"] == "USD_SHORT"


