def test_simulated_broker_blocks_order_send_and_reports_boundary() -> None:
    broker = SimulatedBroker()
    assert broker.get_account_balance() == 100000.0
    try:
        broker.order_send({"symbol": "XAUUSD"})
    except RuntimeError as exc:
        assert "broker mutation is disabled" in str(exc)
    else:
        raise AssertionError("SimulatedBroker.order_send must raise")
    boundary = broker.mutation_boundary()
    assert boundary["broker_adapter"] == "SimulatedBroker"
    assert boundary["broker_mutation_enabled"] is False
    assert boundary["broker_account_order_history_deal_position_mutation"] is False
    assert boundary["order_send_attempts"] == 1


def test_path_truth_index_returns_bisect_window_metadata() -> None:
    rows = tuple(
        {
            "time": f"2026-04-20T07:{minute:02d}:00+00:00",
            "time_utc": f"2026-04-20T07:{minute:02d}:00+00:00",
            "symbol": "XAUUSD",
            "bid": 100.0 + minute,
            "ask": 100.1 + minute,
        }
        for minute in (0, 1, 2, 3)
    )
    source = ResolvedSource(
        spec=SourceSpec(
            symbol="XAUUSD",
            mapped_symbol="XAUUSD",
            timeframe="TICK",
            path=Path("fixture_ticks.jsonl"),
            source_family="fixture",
            source_broker="FTMO",
            source_role="owner_authorized_research_hydration",
            ordered_tick_truth_satisfied=True,
        ),
        rows=rows,
        rows_by_day={"2026-04-20": rows},
        sha256="a" * 64,
        day_counts={"2026-04-20": len(rows)},
        selected_status="fixture",
        min_required_rows_per_day=1,
    )
    query = PathTruthIndex(source).query(
        after=parse_utc("2026-04-20T07:00:30+00:00"),
        until=parse_utc("2026-04-20T07:02:00+00:00"),
    )
    assert [row["time_utc"] for row in query.rows] == [
        "2026-04-20T07:01:00+00:00",
        "2026-04-20T07:02:00+00:00",
    ]
    assert query.metadata["path_index_lookup_mode"] == "day_time_bisect_index"
    assert query.metadata["path_index_ordered_tick_truth"] is True
    assert query.metadata["path_index_rows_returned"] == 2


