def test_verify_route_rejects_m1_claiming_ordered_tick_truth(tmp_path: Path) -> None:
    route = minimal_route(tmp_path)
    manifest = json.loads((route / "TIMEWARP_SOURCE_MANIFEST.json").read_text(encoding="utf-8"))
    for source in manifest["sources"]:
        if source["timeframe"] == "M1":
            source["ordered_tick_truth_satisfied"] = True
            break
    write_json(route / "TIMEWARP_SOURCE_MANIFEST.json", manifest)
    result = verify_route(repo_root=tmp_path, route_dir=route, write_result=False)
    assert result["status"] == "failed"
    assert any(check["check"] == "source_labels" for check in result["checks"] if check["status"] == "failed")


