def _v220r1_set_current_router_quality(
    surface: dict,
    *,
    expected_net_r: float,
    probability: float,
    fill_probability: float,
    source_completeness: float,
) -> None:
    surface.update(
        {
            "expected_net_r": expected_net_r,
            "candidate_expected_net_r": expected_net_r,
            "probability": probability,
            "candidate_probability": probability,
            "confidence": probability,
            "candidate_confidence": probability,
            "fill_probability": fill_probability,
            "candidate_fill_probability": fill_probability,
            "entry_quality_fill_probability": fill_probability,
            "source_completeness": source_completeness,
        }
    )
    _add_strict_limit_fillability(surface, fill_probability)
    quality = dict(surface.get("candidate_decision_quality") or {})
    quality.update(
        {
            "expected_net_r": expected_net_r,
            "probability": probability,
            "confidence": probability,
            "fill_probability": fill_probability,
            "entry_quality_fill_probability": fill_probability,
            "execution_fill_probability": fill_probability,
            "limit_fillability_probability": fill_probability,
            "predecision_limit_fillability_probability": fill_probability,
            "source_completeness": source_completeness,
        }
    )
    surface["candidate_decision_quality"] = quality


def test_v220r1_refresh_keeps_finalized_scheduler_authority_over_distinct_candidate_provisional() -> None:
    route_floors = {
        "expected_net_r": 0.55,
        "probability": 0.70,
        "fill_probability": 0.55,
        "source_completeness": 0.95,
    }
    row, _, _, finalized_authority = _v220r1_source_bound_router_authority_fixture(
        candidate_id="v220r1-finalized-scheduler-authority",
        route_floors=route_floors,
        authority_source="unit_test_v220r1_finalized_scheduler_authority",
    )
    provisional_candidate, packets, _, provisional_authority = (
        _v220r1_source_bound_router_authority_fixture(
            candidate_id="v220r1-finalized-scheduler-authority",
            route_floors=route_floors,
            authority_source="unit_test_v220r1_distinct_candidate_provisional",
            provisional=True,
        )
    )
    finalized_hash = finalized_authority["package_new_entry_authority_hash_sha256"]
    provisional_hash = provisional_authority[
        "package_new_entry_authority_hash_sha256"
    ]
    assert finalized_hash != provisional_hash
    assert row["package_new_entry_authority_valid"] is True
    row["score_components"] = {
        "unrelated_diagnostic_provisional_authority": copy.deepcopy(
            provisional_authority
        )
    }

    timewarp.refresh_scheduler_backfilled_candidate_namespace_aliases(
        row,
        candidate=provisional_candidate,
        packets=packets,
        decision_time_utc=row["decision_time_utc"],
        config={
            "ultimate_candidate_package_source_bound_router_refusal_open_reduced_materialization_enabled": True,
        },
    )

    assert row["package_new_entry_authority_hash_sha256"] == finalized_hash
    assert row["package_new_entry_authority_payload"]["authority_source"] == (
        "unit_test_v220r1_finalized_scheduler_authority"
    )
    assert (
        row["ultimate_candidate_package_open_reduced_risk_authority"]
        ["package_new_entry_authority_hash_sha256"]
        == finalized_hash
    )
    assert row["score_components"][
        "unrelated_diagnostic_provisional_authority"
    ]["package_new_entry_authority_hash_sha256"] == provisional_hash
    assert (
        "package_new_entry_authority_provisional_until_scheduler_row_finalized"
        not in json.dumps(row, sort_keys=True)
    )


