def _v220r2_hash_valid_authority_without_payload_atoms(
    authority: dict,
    atoms: tuple[str, ...],
) -> dict:
    mutated = copy.deepcopy(authority)
    payload = dict(mutated["package_new_entry_authority_payload"])
    for atom in atoms:
        payload.pop(atom, None)
        mutated.pop(atom, None)
        mutated.pop(f"package_new_entry_authority_{atom}", None)
    canonical_hash = timewarp.package_new_entry_authority_payload_hash_sha256(
        payload
    )
    mutated["package_new_entry_authority_payload"] = payload
    mutated["package_new_entry_authority_hash_sha256"] = canonical_hash
    mutated["expected_package_new_entry_authority_hash_sha256"] = canonical_hash
    mutated["package_new_entry_authority_valid"] = True
    mutated["package_new_entry_authority_status"] = (
        "valid_signed_predecision_new_entry_authority"
    )
    mutated["package_new_entry_authority_failures"] = []
    return mutated


