    assert authority_class == timewarp.UNSAFE_PREDECISION_EXECUTION_FILLABILITY_SOURCE
    assert aliases["execution_fill_probability"] is None
    assert aliases["execution_fillability_atomic_failure"] == (
        "predecision_limit_fillability_cross_surface_atomic_conflict"
    )


