def test_v220r3_runtime_quality_hash_binds_fillability_time_and_boundary() -> None:
    candidate = {
        "candidate_id": "runtime-quality-temporal-hash",
        "decision_time_utc": "2026-05-13T08:15:00+00:00",
        "candidate_expected_net_r": 1.10,
        "candidate_probability": 0.82,
        "candidate_confidence": 0.78,
        "candidate_fill_probability": 0.64,
        "source_completeness": 1.0,
        "source_completeness_status": "complete",
    }
    _add_strict_limit_fillability(candidate, 0.64)
    packets = {"decision_time_utc": candidate["decision_time_utc"]}
    original = timewarp.runtime_candidate_quality_contract_fields(candidate, packets)

    changed_time = copy.deepcopy(candidate)
    changed_time["predecision_limit_fillability"][
        "current_price_source_time_utc"
    ] = "2026-05-13T07:45:00+00:00"
    changed_boundary = copy.deepcopy(candidate)
    changed_boundary["predecision_limit_fillability"]["source_boundary"] = (
        "closed_m15_predecision_asof_no_postdecision_path"
    )
    time_contract = timewarp.runtime_candidate_quality_contract_fields(
        changed_time,
        packets,
    )
    boundary_contract = timewarp.runtime_candidate_quality_contract_fields(
        changed_boundary,
        packets,
    )

    assert original["runtime_quality_contract_schema_version"] == (
        "runtime_candidate_quality_contract_v2"
    )
    assert original["runtime_quality_contract_hash_sha256"] != time_contract[
        "runtime_quality_contract_hash_sha256"
    ]
    assert original["runtime_quality_contract_hash_sha256"] != boundary_contract[
        "runtime_quality_contract_hash_sha256"
    ]


