def test_v220r2_hash_valid_payload_missing_each_required_quality_atom_fails(
    atom: str,
) -> None:
    candidate, _, _ = _signed_open_reduced_order_authority_fixture(
        candidate_id=f"v220r2-missing-quality-{atom}",
    )
    authority_field = candidate["package_new_entry_authority_authority_field"]
    removed_atoms = (
        ("fill_probability", "entry_quality_fill_probability")
        if atom == "fill_probability"
        else (atom,)
    )
    authority = _v220r2_hash_valid_authority_without_payload_atoms(
        candidate[authority_field],
        removed_atoms,
    )
    surface = _v220r2_current_identity_with_selected_authority(
        candidate,
        authority,
    )

    attribution = timewarp.package_new_entry_authority_attribution_fields(surface)
    failures = tuple(attribution["package_new_entry_authority_failures"])
    required_atom_failures = (
        timewarp.package_new_entry_authority_required_payload_atom_failures(
            authority["package_new_entry_authority_payload"]
        )
    )
    expected_failure = V220R2_REQUIRED_QUALITY_FAILURES[atom]

    assert authority["package_new_entry_authority_hash_sha256"] == (
        timewarp.package_new_entry_authority_payload_hash_sha256(
            authority["package_new_entry_authority_payload"]
        )
    )
    assert expected_failure in required_atom_failures
    assert attribution["package_new_entry_authority_valid"] is False
    assert expected_failure in failures
    assert timewarp.has_finalized_package_new_entry_authority_surface(surface) is False


