def test_v220r2_selected_finalized_nested_authority_outranks_coherent_stale_top_level() -> None:
    candidate_id = "v220r2-selected-nested-over-stale-top-level"
    stale_row, _, _, stale_authority = _v220r1_source_bound_router_authority_fixture(
        candidate_id=candidate_id,
        route_floors=STRICT_SOURCE_BOUND_ROUTER_REFUSAL_FLOORS,
        fill_probability=0.96,
    )
    _, _, _, selected_authority = _v220r1_source_bound_router_authority_fixture(
        candidate_id=candidate_id,
        route_floors=STRICT_SOURCE_BOUND_ROUTER_REFUSAL_FLOORS,
        fill_probability=0.88,
    )
    assert stale_authority["package_new_entry_authority_hash_sha256"] != (
        selected_authority["package_new_entry_authority_hash_sha256"]
    )
    surface = copy.deepcopy(stale_row)
    authority_field = selected_authority[
        "package_new_entry_authority_authority_field"
    ]
    surface["package_new_entry_authority_authority_field"] = authority_field
    surface[authority_field] = copy.deepcopy(selected_authority)

    attribution = timewarp.package_new_entry_authority_attribution_fields(surface)

    assert attribution["package_new_entry_authority_valid"] is True
    assert attribution["package_new_entry_authority_hash_sha256"] == (
        selected_authority["package_new_entry_authority_hash_sha256"]
    )
    assert attribution["package_new_entry_authority_payload"] == (
        selected_authority["package_new_entry_authority_payload"]
    )
    assert attribution["package_new_entry_authority_payload"][
        "execution_fill_probability"
    ] == 0.88
    runtime_fill, runtime_source, runtime_claimed = (
        timewarp._signed_payload_execution_fillability_with_source(surface)
    )
    scheduler_detail = scheduler._signed_payload_execution_fillability(surface)
    scheduler_fill = scheduler_detail.get("value")
    scheduler_source = scheduler_detail.get("source")
    scheduler_claimed = scheduler_detail.get("claimed")
    assert (runtime_fill, runtime_source, runtime_claimed) == (
        0.88,
        selected_authority["package_new_entry_authority_payload"][
            "execution_fill_probability_source"
        ],
        True,
    )
    assert (scheduler_fill, scheduler_source, scheduler_claimed) == (
        0.88,
        selected_authority["package_new_entry_authority_payload"][
            "execution_fill_probability_source"
        ],
        True,
    )


