def test_post_window_candidate_retention_preserves_only_downstream_truth() -> None:
    full = {
        "campaign": "campaign-1",
        "candidate_id": "candidate-1",
        "decision_time_utc": "2026-06-04T07:00:00+00:00",
        "canonical_replay_candidate_instance_key": "candidate-1@@window-1",
        "risk_finalizer_probe_instance_key": "candidate-1@@window-1",
        "source_bound_replay_candidate_instance_key": "candidate-1@@window-1",
        "symbol": "XAUUSD",
        "route_session": "london",
        "framework": "momentum",
        "dynamic_geometry_policy": "partial_be_runner",
        "selector_action": "source-required",
        "selector_reason": "source_gap",
        "source_required_fields": ["tick_path"],
        "package_replay_order_executable_transfer_status": "final_blocked",
        "same_symbol_replay_exposure_context": {"pending": 1},
        "large_candidate_packet": {
            "duplicated_config": {"payload": ["x" * 4096]},
        },
    }

    retained = timewarp.post_window_candidate_retention_row(full)

    assert retained["canonical_replay_candidate_instance_key"] == (
        "candidate-1@@window-1"
    )
    assert retained["source_required_fields"] == ["tick_path"]
    assert retained["source_required_fields"] is not full["source_required_fields"]
    assert retained["same_symbol_replay_exposure_context"] == {"pending": 1}
    assert retained["package_replay_order_executable_transfer_status"] == (
        "final_blocked"
    )
    assert "large_candidate_packet" not in retained
    baseline_ledgers = {
        "candidate": [copy.deepcopy(full)],
        "order": [
            {
                "canonical_replay_candidate_instance_key": (
                    "candidate-1@@window-1"
                ),
                "package_replay_order_executable_transfer_status": "order_bound",
                "package_replay_order_executable_bound_order_id": "order-1",
            }
        ],
        "trade": [],
        "rollup": [],
    }
    retained_ledgers = {
        "candidate": [copy.deepcopy(retained)],
        "order": copy.deepcopy(baseline_ledgers["order"]),
        "trade": [],
        "rollup": [],
    }
    baseline_rollup = copy.deepcopy(baseline_ledgers)
    retained_rollup = copy.deepcopy(retained_ledgers)
    timewarp.build_rollup_rows(
        baseline_rollup,
        campaign=CampaignConfig(
            name="campaign-1",
            phase="phase-1",
            days=(),
            pending_expiry_minutes=60,
            use_repaired_pending_expiry=True,
        ),
    )
    timewarp.build_rollup_rows(
        retained_rollup,
        campaign=CampaignConfig(
            name="campaign-1",
            phase="phase-1",
            days=(),
            pending_expiry_minutes=60,
            use_repaired_pending_expiry=True,
        ),
    )
    assert retained_rollup["rollup"] == baseline_rollup["rollup"]
    baseline_reconciliation = (
        timewarp.reconcile_terminal_package_execution_truth(baseline_ledgers)
    )
    retained_reconciliation = (
        timewarp.reconcile_terminal_package_execution_truth(retained_ledgers)
    )
    assert retained_reconciliation == baseline_reconciliation
    assert (
        retained_ledgers["candidate"][0][
            "package_replay_order_executable_bound_order_id"
        ]
        == "order-1"
    )
